```powershell
# install_redtools.ps1 - generates 30 small CTF helper scripts (PowerShell + Python3)
# For legal CTF/lab use only.

param(
    [string]$Dir = "pico-redtools"
)

$ErrorActionPreference = "Stop"

# Create directory
if (!(Test-Path $Dir)) {
    New-Item -ItemType Directory -Path $Dir | Out-Null
}

function Write-Script {
    param(
        [string]$Name,
        [string]$Content
    )
    $Path = Join-Path $Dir $Name
    Set-Content -Path $Path -Value $Content -Encoding UTF8
    Write-Host "Created: $Name" -ForegroundColor Green
}

# 1) b64decode_loop.ps1
Write-Script "b64decode_loop.ps1" @'
# Repeatedly base64-decode input until it fails
param([string]$InputFile)
if ($InputFile -and (Test-Path $InputFile)) {
    $data = Get-Content $InputFile -Raw
} else {
    $data = $input | Out-String
}
$count = 0
while ($true) {
    try {
        $bytes = [Convert]::FromBase64String($data)
        $data = [System.Text.Encoding]::UTF8.GetString($bytes)
        $count++
    } catch {
        break
    }
}
Write-Output $data
Write-Host "[decoded $count time(s)]" -ForegroundColor Yellow
'@

