Write-Script "vigenere.ps1" @'
# Vigenere cipher
param(
    [switch]$Encrypt,
    [switch]$Decrypt,
    [string]$Key,
    [string]$Text
)
if (!$Text) { $Text = $input | Out-String }
$Key = $Key.ToUpper() -replace '[^A-Z]',''
$result = ""
$j = 0
foreach ($ch in $Text.ToCharArray()) {
    if ($ch -match '[a-zA-Z]') {
        $isUpper = [char]::IsUpper($ch)
        $base = if ($isUpper) { 65 } else { 97 }
        $o = [int]$ch - $base
        $k = [int]$Key[$j % $Key.Length] - 65
        if ($Decrypt) {
            $n = ($o - $k + 26) % 26
        } else {
            $n = ($o + $k) % 26
        }
        $result += [char]($n + $base)
        $j++
    } else {
        $result += $ch
    }
}
Write-Output $result -NoNewline
'@

