# 14) carve_png.ps1
Write-Script "carve_png.ps1" @'
# Carve PNG from blob
param(
    [string]$InputFile,
    [string]$OutputFile
)
$pythonScript = @"
import sys
data = open(sys.argv[1],'rb').read()
sig = b'\x89PNG\r\n\x1a\n'
start = data.find(sig)
if start == -1: sys.exit("PNG signature not found")
iend = data.find(b'IEND', start)
if iend == -1: sys.exit("IEND not found")
iend += 8  # IEND + CRC
open(sys.argv[2],'wb').write(data[start:iend])
print("Wrote", sys.argv[2])
"@
python -c $pythonScript $InputFile $OutputFile
'@

# 15) png_chunk_dump.ps1
Write-Script "png_chunk_dump.ps1" @'
# List PNG chunks
param([string]$PngFile)
$pythonScript = @"
import sys, struct, zlib
with open(sys.argv[1],'rb') as f:
    sig = f.read(8)
    if sig != b'\x89PNG\r\n\x1a\n': sys.exit("Not a PNG")
    off = 8; i = 0
    while True:
        lenb = f.read(4)
        if not lenb: break
        ln = struct.unpack(">I",lenb)[0]
        typ = f.read(4)
        data = f.read(ln)
        crc = f.read(4)
        print(f"{i:02d} off=0x{off:08x} type={typ.decode()} len={ln}")
        if typ in [b'tEXt', b'zTXt']:
            try:
                if typ == b'zTXt':
                    k,rest = data.split(b'\x00',1)
                    txt = zlib.decompress(rest[1:])
                    print("   key:", k.decode(errors='ignore'))
                    print("   text:", txt.decode(errors='replace')[:200])
                else:
                    print("   text:", data.decode(errors='replace')[:200])
            except: pass
        off += 12+ln; i+=1
"@
python -c $pythonScript $PngFile
'@

