Write-Host "== Header ==" -ForegroundColor Cyan
ConvertFrom-Base64Url $parts[0] | ConvertFrom-Json | ConvertTo-Json
Write-Host "`n== Payload ==" -ForegroundColor Cyan
ConvertFrom-Base64Url $parts[1] | ConvertFrom-Json | ConvertTo-Json
'@

# 23) zip_list_extract.ps1
Write-Script "zip_list_extract.ps1" @'
# List or extract from ZIP
param(
    [string]$ZipFile,
    [string]$ExtractFile
)
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead($ZipFile)
