# 30) quick_webserver.ps1
Write-Script "quick_webserver.ps1" @'
# Start simple HTTP server
param(
    [int]$Port = 8080,
    [string]$Path = "."
)
Write-Host "Starting HTTP server on port $Port..." -ForegroundColor Yellow
Write-Host "Serving files from: $Path" -ForegroundColor Yellow
Write-Host "Press Ctrl+C to stop" -ForegroundColor Yellow

$http = [System.Net.HttpListener]::new()
$http.Prefixes.Add("http://+:$Port/")
$http.Start()

try {
    while ($http.IsListening) {
        $context = $http.GetContext()
        $request = $context.Request
        $response = $context.Response

        Write-Host "$($request.HttpMethod) $($request.Url.LocalPath)" -ForegroundColor Cyan

        $localPath = Join-Path $Path $request.Url.LocalPath.TrimStart('/')

        if (Test-Path $localPath -PathType Leaf) {
            $bytes = [System.IO.File]::ReadAllBytes($localPath)
            $response.ContentLength64 = $bytes.Length
            $response.OutputStream.Write($bytes, 0, $bytes.Length)
        } else {
            $response.StatusCode = 404
            $msg = [System.Text.Encoding]::UTF8.GetBytes("Not Found")
            $response.OutputStream.Write($msg, 0, $msg.Length)
        }
        $response.Close()
    }
} finally {
    $http.Stop()
}
'@

