enum rcc_error_code_type rcc_configure_frequency_msi_oscillator(uint32_t flags)
{
    uint32_t reg = RCC->CR,
        vos_msk = (PWR->CR1 & PWR_CR1_VOS_Msk),
        cfgr = RCC->CFGR,
        pllcfgr = RCC->PLLCFGR,
        freq = 0;

    if(((reg & RCC_CR_MSION) && !(reg & RCC_CR_MSIRDY)) || (flags > RCC_CR_MSIRANGE11))
    {
        return RCC_ERROR;
    }

    freq = __msi_frequency_table[((flags & RCC_CR_MSIRANGE_Msk) >> RCC_CR_MSIRANGE_Pos)];

    switch(vos_msk)
    {
        case PWR_CR1_VOS_RANGE1:
        {
            if(freq > RCC_FREQUENCY_MAX_RANGE1_MSI)
            {
                return RCC_ERROR;
            }

            if ((cfgr & RCC_CFGR_SWS_Msk) == RCC_CFGR_SWS_MSI)
            {
                freq /= __hpre_table[((cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos)];

                if (freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT)
                {
                    return RCC_ERROR;
                }
            }

            if (((cfgr & RCC_CFGR_SWS_Msk) == RCC_CFGR_SWS_PLL) && ((pllcfgr & RCC_PLLCFGR_PLLSRC_Msk) == RCC_PLLCFGR_PLLSRC_MSI))
            {
                freq /= (((flags & RCC_PLLCFGR_PLLM_Msk) >> RCC_PLLCFGR_PLLM_Pos) + 1);

                if ((freq < RCC_FREQUENCY_MIN_PLL_VCO_INPUT) || (freq > RCC_FREQUENCY_MAX_PLL_VCO_INPUT))
                {
                    return RCC_ERROR;
                }

                freq *= ((flags & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos);

                if ((freq < RCC_FREQUENCY_MIN_PLL_VCO_OUTPUT) || (freq > RCC_FREQUENCY_MAX_RANGE1_PLL_VCO_OUTPUT))
                {
                    return RCC_ERROR;
                }

                freq /= ((((flags & RCC_PLLCFGR_PLLR_Msk) >> RCC_PLLCFGR_PLLR_Pos) + 1) << 1);

                freq /= __hpre_table[((cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos)];

                if (freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT)
                {
                    return RCC_ERROR;
                }
            }
            break;
        }
        case PWR_CR1_VOS_RANGE2:
        {
            if (freq > RCC_FREQUENCY_MAX_RANGE2_MSI)
            {
                return RCC_ERROR;
            }

            if ((cfgr & RCC_CFGR_SWS_Msk) == RCC_CFGR_SWS_MSI)
            {
                freq /= __hpre_table[((cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos)];

                if (freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT)
                {
                    return RCC_ERROR;
                }
            }
            if (((cfgr & RCC_CFGR_SWS_Msk) == RCC_CFGR_SWS_PLL) && ((pllcfgr & RCC_PLLCFGR_PLLSRC_Msk) == RCC_PLLCFGR_PLLSRC_MSI))
            {
                freq /= (((flags & RCC_PLLCFGR_PLLM_Msk) >> RCC_PLLCFGR_PLLM_Pos) + 1);

                if ((freq < RCC_FREQUENCY_MIN_PLL_VCO_INPUT) || (freq > RCC_FREQUENCY_MAX_PLL_VCO_INPUT))
                {
                    return RCC_ERROR;
                }

                freq *= ((flags & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos);

                if ((freq < RCC_FREQUENCY_MIN_PLL_VCO_OUTPUT) || (freq > RCC_FREQUENCY_MAX_RANGE2_PLL_VCO_OUTPUT))
                {
                    return RCC_ERROR;
                }

                freq /= ((((flags & RCC_PLLCFGR_PLLR_Msk) >> RCC_PLLCFGR_PLLR_Pos) + 1) << 1);

                freq /= __hpre_table[((cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos)];

                if (freq > RCC_FREQUENCY_MAX_RANGE2_OUTPUT)
                {
                    return RCC_ERROR;
                }
            }
            break;
        }
        default:
        {
            return RCC_ERROR;
        }
    }

    RCC->CR = ((reg & ~RCC_CR_MSIRANGE_Msk) | (flags & RCC_CR_MSIRANGE_Msk));
    return RCC_OK;
}

