static enum rcc_error_code_type rcc_calculate_pll_vco_frequency(uint32_t configuration, uint32_t vos, uint32_t *frequency)
{
    uint32_t freq = 0;

    configuration &= (RCC_PLLCFGR_PLLM_Msk | RCC_PLLCFGR_PLLN_Msk | RCC_PLLCFGR_PLLSRC_Msk);

    if ((frequency == NULL) || (((configuration & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos) < RCC_MIN_VALID_PLLN_VALUE) || (((configuration & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos) > RCC_MAX_VALID_PLLN_VALUE))
    {
        return RCC_ERROR;
    }

    switch (configuration & RCC_PLLCFGR_PLLSRC_Msk)
    {
        case RCC_PLLCFGR_PLLSRC_NONE:
        {
            *frequency = 0;
            return RCC_OK;
        }
        case RCC_PLLCFGR_PLLSRC_HSE:
        {
            freq = rcc_get_frequency_hse_oscillator();
            break;
        }
        case RCC_PLLCFGR_PLLSRC_HSI16:
        {
            freq = rcc_get_frequency_hsi16_oscillator();
            break;
        }
        case RCC_PLLCFGR_PLLSRC_MSI:
        {
            freq = rcc_get_frequency_msi_oscillator();
            break;
        }
        default:
        {
            return RCC_ERROR;
        }
    }
    freq /= (((configuration & RCC_PLLCFGR_PLLM_Msk) >> RCC_PLLCFGR_PLLM_Pos) + 1);

    if ((freq < RCC_FREQUENCY_MIN_PLL_VCO_INPUT) || (freq > RCC_FREQUENCY_MAX_PLL_VCO_INPUT))
    {
        return RCC_ERROR;
    }

    freq *= ((configuration & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos);

    if (freq < RCC_FREQUENCY_MIN_PLL_VCO_OUTPUT)
    {
        return RCC_ERROR;
    }

    switch (vos)
    {
        case PWR_CR1_VOS_RANGE1:
        {
            if (freq > RCC_FREQUENCY_MAX_RANGE1_PLL_VCO_OUTPUT)
            {
                return RCC_ERROR;
            }

            break;
        }
        case PWR_CR1_VOS_RANGE2:
        {
            if (freq > RCC_FREQUENCY_MAX_RANGE2_PLL_VCO_OUTPUT)
            {
                return RCC_ERROR;
            }
            break;
        }
    }
    *frequency = freq;
    return RCC_OK;
}

static enum rcc_error_code_type rcc_calculate_pll_ouput_frequency(uint32_t div, uint32_t vos, uint32_t vco_frequency, uint32_t* frequency)
{
    uint32_t tmp_freq = 0;

    if ((frequency == NULL) || (div == 0))
    {
        return RCC_ERROR;
    }

    tmp_freq = vco_frequency / div;

    switch (vos)
    {
        case PWR_CR1_VOS_RANGE1:
        {
            if (tmp_freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT)
            {
                return RCC_ERROR;
            }
            break;
        }
        case PWR_CR1_VOS_RANGE2:
        {
            if (tmp_freq > RCC_FREQUENCY_MAX_RANGE2_OUTPUT)
            {
                return RCC_ERROR;
            }
            break;
        }
    }

    *frequency = tmp_freq;
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_pll_vco(uint32_t flags)
{
    uint32_t vos_msk = (PWR->CR1 & PWR_CR1_VOS_Msk),
        msk = (RCC->PLLCFGR & ~(RCC_PLLCFGR_PLLM_Msk | RCC_PLLCFGR_PLLN_Msk | RCC_PLLCFGR_PLLSRC_Msk)),
