response:
Here’s one way to drastically cut down on boiler-plate, improve readability and maintainability, and still cover all of the use‐cases you had:

1.  Define a small descriptor for each oscillator, then write one generic set of “enable/disable/is-enabled/get‐freq” routines.  
2.  Do the same for your bus‐clock/peripheral enables.  
3.  Factor out all of the duplicated bit-tweaking into table lookups and a handful of inline helpers.

Below is a sketch.  It’s not a drop-in replacement (you’ll still need to add your HSE/MSI/HSE-BYP special checks, PLL, SYSCLK, etc.), but it demonstrates the pattern:

```c
#include "stm32l412xx.h"    /* CMSIS device header */
#include <stddef.h>
#include <stdbool.h>

/* common error code */
typedef enum {
  RCC_OK    = 0,
  RCC_ERROR = 1
} rcc_error_t;

/* which oscillator? */
typedef enum {
  OSC_HSE,
  OSC_HSE_BYP,
  OSC_HSI16,
  OSC_HSI48,
  OSC_MSI,
  OSC_LSE,
  OSC_LSI,
  OSC_NR
} rcc_osc_t;

/* descriptor for each oscillator */
typedef struct {
  volatile uint32_t *reg;    /* CR, CRRCR, BDCR, CSR */
  uint32_t            on_bit; /* RCC_CR_HSEON, …    */
  uint32_t            rdy_bit;
  uint32_t            byp_bit;/* 0 if N/A           */
  uint32_t            def_freq;/* 0 if range/MSI needs lookup */
} osc_cfg_t;

/* you must fill in correct registers & bit-masks here */
static const osc_cfg_t osc_cfg[OSC_NR] = {
  [OSC_HSE]     = { &RCC->CR,     RCC_CR_HSEON,   RCC_CR_HSERDY,   0,             0           },
  [OSC_HSE_BYP] = { &RCC->CR,     RCC_CR_HSEON,   RCC_CR_HSERDY,   RCC_CR_HSEBYP, 0           },
  [OSC_HSI16]   = { &RCC->CR,     RCC_CR_HSION,   RCC_CR_HSIRDY,   0,             16000000UL },
  [OSC_HSI48]   = { &RCC->CRRCR,  RCC_CRRCR_HSI48ON, RCC_CRRCR_HSI48RDY, 0,       48000000UL },
  [OSC_MSI]     = { &RCC->CR,     RCC_CR_MSION,   RCC_CR_MSIRDY,   0,             0           },
  [OSC_LSE]     = { &RCC->BDCR,   RCC_BDCR_LSEON, RCC_BDCR_LSERDY, RCC_BDCR_LSEBYP,32768UL    },
  [OSC_LSI]     = { &RCC->CSR,    RCC_CSR_LSION,  RCC_CSR_LSIRDY,  0,             32000UL    },
};

/* helper to test if ON+RDY are both set */
static inline bool _osc_is_ready(const osc_cfg_t *c) {
  return ((*c->reg & (c->on_bit | c->rdy_bit)) == (c->on_bit | c->rdy_bit));
}

/* enable oscillator (bypass only if c->byp_bit!=0 and 'bypass'==true) */
rcc_error_t rcc_osc_enable(rcc_osc_t o, bool bypass, uint32_t freq) {
  if (o >= OSC_NR)            return RCC_ERROR;
  const osc_cfg_t *c = &osc_cfg[o];

  /* for ones with a bypass option, if user asked bypass => set BYP first */
  if (bypass) {
    if (c->byp_bit == 0)      return RCC_ERROR;
    *c->reg |= c->byp_bit;
  }

  /* turn it on */
  *c->reg |= c->on_bit;

  /* optionally store freq somewhere if needed… */
  /* user must still check range, VOS, etc. */

  /* wait for ready? */
  /* while(! _osc_is_ready(c)); */  
  return RCC_OK;
}

/* disable oscillator */
rcc_error_t rcc_osc_disable(rcc_osc_t o) {
  if (o >= OSC_NR)            return RCC_ERROR;
  const osc_cfg_t *c = &osc_cfg[o];
  /* you may wish to guard against “in use as SYSCLK/PLL” here */
  *c->reg &= ~(c->on_bit | c->byp_bit);
  return RCC_OK;
}

bool rcc_osc_is_enabled(rcc_osc_t o) {
  if (o >= OSC_NR)            return false;
  return _osc_is_ready(&osc_cfg[o]);
}

/* get frequency (MSI needs special table lookup via MSIRANGE bits) */
uint32_t rcc_osc_get_freq(rcc_osc_t o) {
  if (o >= OSC_NR)            return 0;
  const osc_cfg_t *c = &osc_cfg[o];

  if (!_osc_is_ready(c))      return 0;
  if (c->def_freq)            return c->def_freq;

  /* MSI special case: */
  if (o == OSC_MSI) {
    static const uint32_t msi_tbl[] = {
      100000,200000,400000,800000,
      1000000,2000000,4000000,8000000,
      16000000,24000000,32000000,48000000
    };
    uint32_t range = (RCC->CR & RCC_CR_MSIRANGE_Msk) >> RCC_CR_MSIRANGE_Pos;
    return msi_tbl[range];
  }

  return 0;
}

/* --------------------------------------------------------------------------
   BUS / PERIPHERAL CLOCKS
   Instead of 6× enable/disable/is-enabled functions, use one generic:
   rcc_bus_enable(RCC_BUS_AHB1, GPIOA|…);
   ------------------------------------------------------------------------ */
typedef enum {
  RCC_BUS_AHB1,
  RCC_BUS_AHB2,
  RCC_BUS_AHB3,
  RCC_BUS_APB1_1,
  RCC_BUS_APB1_2,
  RCC_BUS_APB2,
  RCC_BUS_NR
} rcc_bus_t;

/* map to the ENR registers */
static volatile uint32_t * const bus_enr[RCC_BUS_NR] = {
  [RCC_BUS_AHB1]   = &RCC->AHB1ENR,
  [RCC_BUS_AHB2]   = &RCC->AHB2ENR,
  [RCC_BUS_AHB3]   = &RCC->AHB3ENR,
  [RCC_BUS_APB1_1] = &RCC->APB1ENR1,
  [RCC_BUS_APB1_2] = &RCC->APB1ENR2,
  [RCC_BUS_APB2]   = &RCC->APB2ENR,
};

rcc_error_t rcc_bus_enable(rcc_bus_t b, uint32_t mask) {
  if (b >= RCC_BUS_NR)    return RCC_ERROR;
  *bus_enr[b] |= mask;
  return RCC_OK;
}
rcc_error_t rcc_bus_disable(rcc_bus_t b, uint32_t mask) {
  if (b >= RCC_BUS_NR)    return RCC_ERROR;
  *bus_enr[b] &= ~mask;
  return RCC_OK;
}
bool rcc_bus_is_enabled(rcc_bus_t b, uint32_t mask) {
  if (b >= RCC_BUS_NR)    return false;
  return ((*bus_enr[b] & mask) == mask);
}

/* --------------------------------------------------------------------------
   … and you’d still write your PLL/SYSCLK helpers exactly the same way,
   just replacing dozens of near-identical enable/disable functions
   with a single generic one plus a small map.
   ------------------------------------------------------------------------ */
```

## What did we gain?

• **One place to add new oscillators**, instead of 20 nearly-identical functions.  
• **All bit fiddling centralized** in tables, not spread through 2000 lines of code.  
• **Easier to audit/maintain**: add range checks or VOS-limits in one spot.  
• **Consistent API** (`rcc_osc_enable(...)`, `rcc_bus_enable(...)`) for all clocks.  

You can layer on top of this pattern your full PLL/SYSCLK configuration checks (VCO-input, VCO-output, prescalers, etc.) exactly the same way.  This approach will make your driver both leaner and far more maintainable.

