// --- MSI ---
enum rcc_error_code_type rcc_configure_frequency_msi_oscillator(uint32_t flags)
{
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
    uint32_t cr = RCC->CR;
    uint32_t cfgr = RCC->CFGR;
    uint32_t pllcfgr = RCC->PLLCFGR;

    // Validate MSIRANGE
    uint32_t msirange = (flags & RCC_CR_MSIRANGE_Msk) >> RCC_CR_MSIRANGE_Pos;
    if (msirange > 11U || (cr & RCC_CR_MSION) && !(cr & RCC_CR_MSIRDY)) {
        return RCC_ERROR;
    }

    uint32_t freq = __msi_frequency_table[msirange];

    // Check voltage range limits
    if (vos == PWR_CR1_VOS_RANGE1 && freq > RCC_FREQUENCY_MAX_RANGE1_MSI) return RCC_ERROR;
    if (vos == PWR_CR1_VOS_RANGE2 && freq > RCC_FREQUENCY_MAX_RANGE2_MSI) return RCC_ERROR;

    // Check SYSCLK path if MSI is source
    if ((cfgr & RCC_CFGR_SWS_Msk) == RCC_CFGR_SWS_MSI) {
        uint32_t hpre_idx = (cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos;
        uint32_t hpre_div = __hpre_table[hpre_idx];
        freq /= hpre_div;
        if (freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT) return RCC_ERROR;
    }

    // Check PLL path if MSI is PLL source
    if (((cfgr & RCC_CFGR_SWS_Msk) == RCC_CFGR_SWS_PLL) &&
        ((pllcfgr & RCC_PLLCFGR_PLLSRC_Msk) == RCC_PLLCFGR_PLLSRC_MSI)) {
        uint32_t pllm = ((flags & RCC_PLLCFGR_PLLM_Msk) >> RCC_PLLCFGR_PLLM_Pos) + 1U;
        freq /= pllm;

        if (freq < RCC_FREQUENCY_MIN_PLL_VCO_INPUT || freq > RCC_FREQUENCY_MAX_PLL_VCO_INPUT) return RCC_ERROR;

        uint32_t plln = (flags & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos;
        if (!IS_VALID_PLL_N(plln)) return RCC_ERROR;
        freq *= plln;

        if (freq < RCC_FREQUENCY_MIN_PLL_VCO_OUTPUT) return RCC_ERROR;
        if (vos == PWR_CR1_VOS_RANGE1 && freq > RCC_FREQUENCY_MAX_RANGE1_PLL_VCO_OUTPUT) return RCC_ERROR;
        if (vos == PWR_CR1_VOS_RANGE2 && freq > RCC_FREQUENCY_MAX_RANGE2_PLL_VCO_OUTPUT) return RCC_ERROR;

        uint32_t pllr = ((flags & RCC_PLLCFGR_PLLR_Msk) >> RCC_PLLCFGR_PLLR_Pos) + 1U;
        freq /= (pllr << 1); // Divide by 2 * pllr

        hpre_idx = (cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos;
        hpre_div = __hpre_table[hpre_idx];
        freq /= hpre_div;

        if (vos == PWR_CR1_VOS_RANGE1 && freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT) return RCC_ERROR;
        if (vos == PWR_CR1_VOS_RANGE2 && freq > RCC_FREQUENCY_MAX_RANGE2_OUTPUT) return RCC_ERROR;
    }

    RCC->CR = (cr & ~RCC_CR_MSIRANGE_Msk) | (flags & RCC_CR_MSIRANGE_Msk);
    return RCC_OK;
}

