{
    RCC->CR |= RCC_CR_MSION;
    return RCC_OK;
}

enum rcc_error_code_type rcc_disable_msi_oscillator(void)
{
    uint32_t cfgr_src = RCC->CFGR & RCC_CFGR_SWS_Msk;
    uint32_t pll_src = RCC->PLLCFGR & RCC_PLLCFGR_PLLSRC_Msk;

    if (cfgr_src == RCC_CFGR_SWS_MSI ||
        (cfgr_src == RCC_CFGR_SWS_PLL && pll_src == RCC_PLLCFGR_PLLSRC_MSI)) {
