    uint32_t idx = (RCC->CR & RCC_CR_MSIRANGE_Msk) >> RCC_CR_MSIRANGE_Pos;
    return __msi_frequency_table[idx];
}

// --- PLL ---
static enum rcc_error_code_type rcc_calculate_pll_vco_frequency(uint32_t pll_config, uint32_t vos, uint32_t* out_freq)
{
    if (!out_freq) return RCC_ERROR;

    uint32_t src = pll_config & RCC_PLLCFGR_PLLSRC_Msk;
    uint32_t pllm = ((pll_config & RCC_PLLCFGR_PLLM_Msk) >> RCC_PLLCFGR_PLLM_Pos) + 1U;
    uint32_t plln = (pll_config & RCC_PLLCFGR_PLLN_Msk) >> RCC_PLLCFGR_PLLN_Pos;

    if (!IS_VALID_PLL_N(plln)) return RCC_ERROR;

    uint32_t freq = 0;

    switch (src) {
        case RCC_PLLCFGR_PLLSRC_HSE:
            freq = rcc_get_frequency_hse_oscillator();
            break;
        case RCC_PLLCFGR_PLLSRC_HSI16:
            freq = rcc_get_frequency_hsi16_oscillator();
            break;
        case RCC_PLLCFGR_PLLSRC_MSI:
            freq = rcc_get_frequency_msi_oscillator();
            break;
        case RCC_PLLCFGR_PLLSRC_NONE:
            *out_freq = 0U;
            return RCC_OK;
        default:
            return RCC_ERROR;
    }

    if (freq == 0U) return RCC_ERROR;

    freq /= pllm;

    if (freq < RCC_FREQUENCY_MIN_PLL_VCO_INPUT || freq > RCC_FREQUENCY_MAX_PLL_VCO_INPUT) return RCC_ERROR;

    freq *= plln;

    if (freq < RCC_FREQUENCY_MIN_PLL_VCO_OUTPUT) return RCC_ERROR;

    if (vos == PWR_CR1_VOS_RANGE1 && freq > RCC_FREQUENCY_MAX_RANGE1_PLL_VCO_OUTPUT) return RCC_ERROR;
    if (vos == PWR_CR1_VOS_RANGE2 && freq > RCC_FREQUENCY_MAX_RANGE2_PLL_VCO_OUTPUT) return RCC_ERROR;

    *out_freq = freq;
    return RCC_OK;
}

static enum rcc_error_code_type rcc_calculate_pll_output_frequency(uint32_t div, uint32_t vos, uint32_t vco_freq, uint32_t* out_freq)
{
    if (!out_freq || div == 0U) return RCC_ERROR;

    uint32_t result = vco_freq / div;

    if (vos == PWR_CR1_VOS_RANGE1 && result > RCC_FREQUENCY_MAX_RANGE1_OUTPUT) return RCC_ERROR;
    if (vos == PWR_CR1_VOS_RANGE2 && result > RCC_FREQUENCY_MAX_RANGE2_OUTPUT) return RCC_ERROR;

    *out_freq = result;
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_pll_vco(uint32_t flags)
{
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
    uint32_t msk = RCC->PLLCFGR & ~(RCC_PLLCFGR_PLLM_Msk | RCC_PLLCFGR_PLLN_Msk | RCC_PLLCFGR_PLLSRC_Msk);
    uint32_t config = flags & (RCC_PLLCFGR_PLLM_Msk | RCC_PLLCFGR_PLLN_Msk | RCC_PLLCFGR_PLLSRC_Msk);

    if (rcc_is_enabled_pll() || rcc_calculate_pll_vco_frequency(config, vos, NULL) != RCC_OK) {
        return RCC_ERROR;
    }

    RCC->PLLCFGR = msk | config;
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_pll_r_output(uint32_t flags)
{
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
    uint32_t reg = RCC->PLLCFGR;
    uint32_t msk = reg & ~RCC_PLLCFGR_PLLR_Msk;
    uint32_t pllr = ((flags & RCC_PLLCFGR_PLLR_Msk) >> RCC_PLLCFGR_PLLR_Pos) + 1U;
    uint32_t div = pllr << 1; // 2 * pllr

    uint32_t vco_freq = 0;
    if (rcc_calculate_pll_vco_frequency(reg, vos, &vco_freq) != RCC_OK || vco_freq == 0U) return RCC_ERROR;

    uint32_t output_freq = 0;
    if (rcc_calculate_pll_output_frequency(div, vos, vco_freq, &output_freq) != RCC_OK || output_freq == 0U) return RCC_ERROR;

    RCC->PLLCFGR = msk | (flags & RCC_PLLCFGR_PLLR_Msk);
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_pll_q_output(uint32_t flags)
{
