}

enum rcc_error_code_type rcc_enable_pll(void)
{
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
    uint32_t reg = RCC->PLLCFGR;
    uint32_t vco_freq = 0;

    if (rcc_is_enabled_pll() || rcc_calculate_pll_vco_frequency(reg, vos, &vco_freq) != RCC_OK || vco_freq == 0U) {
        return RCC_ERROR;
    }

    bool need_check_r = (reg & RCC_PLLCFGR_PLLREN) != 0;
    bool need_check_q = (reg & RCC_PLLCFGR_PLLQEN) != 0;

    if (need_check_r) {
        uint32_t pllr = ((reg & RCC_PLLCFGR_PLLR_Msk) >> RCC_PLLCFGR_PLLR_Pos) + 1U;
        uint32_t div = pllr << 1;
        uint32_t freq = 0;
        if (rcc_calculate_pll_output_frequency(div, vos, vco_freq, &freq) != RCC_OK || freq == 0U) return RCC_ERROR;
    }

    if (need_check_q) {
        uint32_t pllr = ((reg & RCC_PLLCFGR_PLLQ_Msk) >> RCC_PLLCFGR_PLLQ_Pos) + 1U;
        uint32_t div = pllr << 1;
        uint32_t freq = 0;
        if (rcc_calculate_pll_output_frequency(div, vos, vco_freq, &freq) != RCC_OK || freq == 0U) return RCC_ERROR;
    }

    RCC->CR |= RCC_CR_PLLON;
    return RCC_OK;
}

enum rcc_error_code_type rcc_enable_pll_r_output(void)
{
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
