    uint32_t pllr = ((reg & RCC_PLLCFGR_PLLR_Msk) >> RCC_PLLCFGR_PLLR_Pos) + 1U;
    uint32_t div = pllr << 1;

    if (!rcc_is_enabled_pll() || rcc_calculate_pll_vco_frequency(reg, vos, &vco_freq) != RCC_OK || vco_freq == 0U) {
        return RCC_ERROR;
    }

    uint32_t freq = 0;
    if (rcc_calculate_pll_output_frequency(div, vos, vco_freq, &freq) != RCC_OK || freq == 0U) return RCC_ERROR;

    RCC->PLLCFGR |= RCC_PLLCFGR_PLLREN;
    return RCC_OK;
}

