static enum rcc_error_code_type rcc_calculate_sysclk_frequency(uint32_t hpre_div, uint32_t vos, uint32_t src, uint32_t* out_freq)
{
    if (!out_freq) return RCC_ERROR;

    uint32_t freq = 0;

    switch (src) {
        case RCC_CFGR_SW_HSE:
            freq = rcc_get_frequency_hse_oscillator();
            break;
        case RCC_CFGR_SW_HSI16:
            freq = rcc_get_frequency_hsi16_oscillator();
            break;
        case RCC_CFGR_SW_MSI:
            freq = rcc_get_frequency_msi_oscillator();
            break;
        case RCC_CFGR_SW_PLL:
            freq = rcc_get_frequency_pll_r_output();
            break;
        default:
            return RCC_ERROR;
    }

    if (freq == 0U) return RCC_ERROR;

    freq /= hpre_div;

    if (vos == PWR_CR1_VOS_RANGE1 && freq > RCC_FREQUENCY_MAX_RANGE1_OUTPUT) return RCC_ERROR;
    if (vos == PWR_CR1_VOS_RANGE2 && freq > RCC_FREQUENCY_MAX_RANGE2_OUTPUT) return RCC_ERROR;

    *out_freq = freq;
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_sysclk(uint32_t flags)
{
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
    uint32_t hpre_idx = (flags & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos;
    uint32_t hpre_div = __hpre_table[hpre_idx];

    uint32_t msk = RCC->CFGR & ~(RCC_CFGR_HPRE_Msk | RCC_CFGR_SW_Msk);
    uint32_t freq = 0;

    if (rcc_calculate_sysclk_frequency(hpre_div, vos, (flags & RCC_CFGR_SW_Msk), &freq) != RCC_OK || freq == 0U) {
        return RCC_ERROR;
    }

    RCC->CFGR = (msk | (flags & (RCC_CFGR_HPRE_Msk | RCC_CFGR_SW_Msk)));
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_pclk1(uint32_t flags)
{
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_PPRE1_Msk) | (flags & RCC_CFGR_PPRE1_Msk);
    return RCC_OK;
}

enum rcc_error_code_type rcc_configure_pclk2(uint32_t flags)
{
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_PPRE2_Msk) | (flags & RCC_CFGR_PPRE2_Msk);
    return RCC_OK;
}

bool rcc_is_ready_sysclk(void)
{
    uint32_t sws = (RCC->CFGR & RCC_CFGR_SWS_Msk) >> RCC_CFGR_SWS_Pos;
    uint32_t sw = (RCC->CFGR & RCC_CFGR_SW_Msk) >> RCC_CFGR_SW_Pos;
    return sws == sw;
}

uint32_t rcc_get_frequency_sysclk(void)
{
    uint32_t cfgr = RCC->CFGR;
    uint32_t vos = PWR->CR1 & PWR_CR1_VOS_Msk;
    uint32_t hpre_idx = (cfgr & RCC_CFGR_HPRE_Msk) >> RCC_CFGR_HPRE_Pos;
    uint32_t hpre_div = __hpre_table[hpre_idx];
    uint32_t src = cfgr & RCC_CFGR_SW_Msk;
    uint32_t freq = 0;

    if (rcc_calculate_sysclk_frequency(hpre_div, vos, src, &freq) != RCC_OK) {
        return 0U;
    }

    return freq;
}

uint32_t rcc_get_frequency_pclk1(void)
{
    uint32_t cfgr = RCC->CFGR;
    uint32_t sysclk = rcc_get_frequency_sysclk();
    uint32_t ppre1_div = ((cfgr & RCC_CFGR_PPRE1_DIV2) ? (((cfgr & RCC_CFGR_PPRE1_DIV_Msk) + 1) << 1) : 1U);
    return sysclk / ppre1_div;
}

uint32_t rcc_get_frequency_pclk2(void)
{
    uint32_t cfgr = RCC->CFGR;
    uint32_t sysclk = rcc_get_frequency_sysclk();
    uint32_t ppre2_div = ((cfgr & RCC_CFGR_PPRE2_DIV2) ? (((cfgr & RCC_CFGR_PPRE2_DIV_Msk) + 1) << 1) : 1U);
    return sysclk / ppre2_div;
}

