		const node = new NodeClass(n.x, n.y, n.id);
		nodeMap.set(n.id, node);

		// Restore port data
		if (n.ports_data && node.ports.out) {
			n.ports_data.forEach((bKeepValue, key) => {
				if (node.ports.out[key]) {
					node.ports.out[key].bKeepValue = bKeepValue;
				}
			});
		}
	});

	// Create links
	state.links.forEach(l => {
		const nodeOut = nodeMap.get(l.port_out.node);
		const nodeIn = nodeMap.get(l.port_in.node);

		if (nodeOut && nodeIn) {
			const port_out = nodeOut.ports.out[l.port_out.key];
			const port_in = nodeIn.ports.in[l.port_in.key];

			if (port_out && port_in) {
				createLink(port_out, port_in);
			}
		}
	});
}

