			${config.direction === 'out' ? '<span class="frame-toggle" title="Toggle keep output">↻</span>' : ''}
			<div class="port-circle"></div>
			<i class="label">${config.label}</i>
		`;
		frag_container.appendChild(port_el);

		const port_model = {
			direction: config.direction,
			type: config.type,
			key: config.key,
			node: this,
			element: port_el,
			circle_element: port_el.querySelector('.port-circle'),
			label_element: port_el.querySelector('.label'),
			b_keep_value: config.b_keep_value !== undefined ? config.b_keep_value : false,
			_value: null,
			value_temp: null,
			value_changed: 0,
			get value() { return this._value; },
			set value(v) {
				if (this._value === v) return;
				this._value = v;
				this.value_changed = true;
			}
		};
		port_el.querySelector('.port-circle').port = port_model;
		if (config.direction === 'out') {
			const toggle_el = port_el.querySelector('.frame-toggle');
			toggle_el.port = port_model;
			toggle_el.addEventListener('click', () => {
				port_model.b_keep_value = !port_model.b_keep_value;
				toggle_el.classList.toggle('active', port_model.b_keep_value);
			});
		}
		this.ports[config.direction].push(port_model);
		return port_model;
	}

	to_json() {
		return {
			id: this.id,
			type: this.constructor.name,
			x: this.x,
			y: this.y,
			b_update_every_frame: this.b_update_every_frame,
			settings: this.get_settings()
		};
	}

	get_settings() {
		const settings = {};
		this.ports.out.forEach(port => {
			settings[port.key] = port.b_keep_value;
		});
		// add custom settings for node type (e.g. channel, format)
		Object.assign(settings, this._get_custom_settings());
		return settings;
	}

	_get_custom_settings() {
		// override in child classes
		return {};
	}

	save_settings(name = this.element.querySelector('.settings-name').value) {
		if (!name) return;
		const settings = this.get_settings();
		this.constructor.save_setting_for_class(name, settings);
		this.update_settings_list();
	}

	load_settings(name = this.element.querySelector('.settings-list').value) {
		const settings = this.constructor.load_setting_for_class(name);
		if (!settings) return;
		Object.entries(settings).forEach(([key, value]) => {
			if (this.ports.out.find(port => port.key === key)) {
				this.ports.out.find(port => port.key === key).b_keep_value = value;
			} else {
				this._apply_custom_setting(key, value);
			}
		});
	}

	_apply_custom_setting(key, value) {
		// override in child classes
	}

	delete_settings(name = this.element.querySelector('.settings-list').value) {
		this.constructor.delete_setting_for_class(name);
		this.update_settings_list();
	}

	update_settings_list() {
		const list_el = this.element.querySelector('.settings-list');
		list_el.innerHTML = '';
		const settings_names = this.constructor.list_settings_for_class();
		settings_names.forEach(name => {
			const option_el = document.createElement('option');
			option_el.value = name;
			option_el.textContent = name;
			list_el.appendChild(option_el);
		});
	}

	static _settings_storage_key(name) { return `node_settings::${name}`; }

	static list_settings_for_class() {
		const key = this._settings_storage_key(this.name);
		const raw = localStorage.getItem(key);
		if (!raw) return [];
		try { return Object.keys(JSON.parse(raw)); } catch { return []; }
	}

	static save_setting_for_class(name, data) {
		if (!name) return;
		const map = this.load_settings_map();
		map[name] = data;
		localStorage.setItem(this._settings_storage_key(this.name), JSON.stringify(map));
	}

	static load_setting_for_class(name) {
		const map = this.load_settings_map();
		return map[name] ?? null;
	}

	static delete_setting_for_class(name) {
		const map = this.load_settings_map();
		if (map[name] === undefined) return;
		delete map[name];
		localStorage.setItem(this._settings_storage_key(this.name), JSON.stringify(map));
	}

	static load_settings_map() {
		const key = this._settings_storage_key(this.name);
		const raw = localStorage.getItem(key);
		if (!raw) return {};
		try { return JSON.parse(raw); } catch { return {}; }
	}

	duplicate() {
		const json = this.to_json();
		delete json.id;
		const new_node = new this.constructor(json);
		new_node.element.style.left = `${parseInt(this.element.style.left, 10) + 20}px`;
		new_node.element.style.top = `${parseInt(this.element.style.top, 10) + 20}px`;
		return new_node;
	}

	remove() {
		// Remove links connected to node
		[...this.ports.in, ...this.ports.out].forEach(port => delete_link(port.link));
		nodes.splice(nodes.indexOf(this), 1);
		const updatable_index = nodes_updatable.indexOf(this);
		if (updatable_index !== -1) nodes_updatable.splice(updatable_index, 1);
		this.element.remove();
	}
}
