	let port=el.port;
	port.bKeepValue=!port.bKeepValue;
	el.classList.toggle('active', port.bKeepValue);
	if (port.bKeepValue && port.value_temp != null) // restore value from value_temp
		port.value = port.value_temp;
}

function tooltip_portCircle_show(e) {
	let port=e.currentTarget.port;
	const typ = port.type || '*';
	const val = port.value;
	str = val === null ? typ : `${typ}: ${shortVal(val)}`;
	showTooltip(e, str)
}

function makeDraggable(elem, header) {
	let dragging = false,
	sx = 0,
	sy = 0;
	header.addEventListener('pointerdown', e => {
	dragging = true;
	sx = e.clientX;
	sy = e.clientY;
	header.setPointerCapture(e.pointerId);
	});
	header.addEventListener('pointermove', e => {
	if (!dragging) return;
	elem.style.left = `${elem.offsetLeft + (e.clientX - sx)}px`;
	elem.style.top = `${elem.offsetTop + (e.clientY - sy)}px`;
	elem.node.bViewInvalid = true; 	// check in drawLinks 
	sx = e.clientX;
	sy = e.clientY;
	});
	header.addEventListener('pointerup', () => dragging = false);
}


function handlePortClick(e) {
	e.stopPropagation();
	let o_el_clicked=e.currentTarget;
	if (!port_o_el_selected) {
		port_o_el_selected=o_el_clicked;
		port_o_el_selected.classList.add('selected');
		highlight_possible_target(port_o_el_selected.type);
		return;
	}

	const port_sel = port_o_el_selected.port;
	const direction_clicked=o_el_clicked.port.direction;
	const direction_sel = port_o_el_selected.port.direction;

	if (port_o_el_selected === o_el_clicked) {
		if (direction_clicked === 'in') { // same port: if it's input, remove link
			if (links.has(port_sel))
				delete_link(links.get(port_sel));
		}
		port_o_el_selected.classList.remove('selected');
		port_o_el_selected = null; highlight_possible_target_remove();
		return;
	}
	let p_in=false;
	let p_out=false;
	if(direction_clicked === 'in') p_in=o_el_clicked.port;
	else p_out=o_el_clicked.port;

	if(direction_sel === 'in') p_in=port_sel;
	else p_out=port_sel;

	if (p_in && p_out) createLink(p_out, p_in);
	else return;
}
function highlight_possible_target(port_type) {
	document.querySelectorAll('.port-circle').forEach(el => {
	const port = el.port;
	if (port && (port.type === '*' || port.type === port_type)) {
		el.classList.add('port-possible');
	}
	});
}
function highlight_possible_target_remove() {
	document.querySelectorAll('.port-possible').forEach(el => el.classList.remove('port-possible'));
}

function createLink(port_out, port_in) {
	if (!(port_in.type === '*' || port_in.type === undefined) && port_out.type !== port_in.type) return;
	port_in.node.bViewInvalid=true;

	// Ensure single connection to input: remove existing link if any
	if (links.has(port_in)) {
		let l=links.get(port_in);
		if (l.port_out === port_out) return;
		delete_link(l);
	}

  const newLink = {
    port_out,
    port_in,
  };
  links.set(port_in, newLink);

  port_in.link = newLink;
  port_out.link = newLink;

  if (port_o_el_selected) {
    port_o_el_selected.classList.remove('selected');
    port_o_el_selected = null;
    highlight_possible_target_remove();
  }
}

