Ниже — минимальный, но полный ре-фактор, который решает все описанные задачи:

•	любая нода сама объявляет, какие параметры нужно хранить  
•	сохранение / загрузка пресетов выполняется одной строкой  
•	дублирование и сериализация графа не требуют ручного перечисления полей  
•	при расширении API ничего менять не нужно — добавили поле → оно само сохранится

--------------------------------------------------------------------
1.  Базовый контракт ноды
--------------------------------------------------------------------
```js
class BaseNode {
	static _store_key(name) { return `node_settings::${name}`; }

	//	== 1. Параметры, которые сериализуются ======================
	//	Потомок обязан переопределить static params c дефолтами.
	static params = {};			// примеры: {x:20,y:20,w:280,h:120}

	constructor(opt={}, id=null){
		//---------------------------------------------------------
		// 1.1	Merge defaults ↔ user options
		//---------------------------------------------------------
		this.opt = Object.assign(
			JSON.parse(JSON.stringify(this.constructor.params)), // клон дефолтов
			opt
		);

		//---------------------------------------------------------
		// 1.2	ui + порты
		//---------------------------------------------------------
		this.id = id ?? BaseNode.next_id++;
		this.element = this._build_element();		// потомок делает шаблон
		this._sync_gui_with_opt();					// + бинды радио/селектов

		//---------------------------------------------------------
		// 1.3	регистрация
		//---------------------------------------------------------
		nodes.push(this);
		if (this.opt.b_update_every_frame) nodes_updatable.push(this);
	}

	//-----------------------------------------------------------------
	// 2.  Авто-бинд gui<->opt
	//-----------------------------------------------------------------
	_sync_gui_with_opt(){
		// любые input/textarea/select с data-key="field_name"
		this.element.querySelectorAll('[data-key]').forEach(el=>{
			const k = el.dataset.key;
			const set_gui = ()=>{					// опция → элемент
				if(el.type==='checkbox')	el.checked = !!this.opt[k];
				else if(el.type==='radio')	el.checked = String(this.opt[k])===el.value;
				else						el.value = this.opt[k];
			};
			const read_gui = ()=>{					// элемент → опция
				this.opt[k] = (el.type==='checkbox')
					? el.checked
					: (el.type==='radio'
						? (el.checked?el.value:this.opt[k])
						: el.value);
				this.dirtyIn = true;
			};
			set_gui();
			el.oninput = read_gui;
			el.onchange = read_gui;
		});
	}

	//-----------------------------------------------------------------
	// 3.  Сохранение / загрузка пресетов (per-class)
	//-----------------------------------------------------------------
	static list_presets(){
		try{ return Object.keys(JSON.parse(localStorage.getItem(this._store_key(this.name)))||{}); }
		catch{ return []; }
	}
	static _read_store(){
		try{ return JSON.parse(localStorage.getItem(this._store_key(this.name)))||{}; }
		catch{ return {}; }
	}
	static _write_store(map){
		localStorage.setItem(this._store_key(this.name), JSON.stringify(map));
	}

	save_preset(name){
		if(!name) return;
		const map = this.constructor._read_store();
		map[name]=this.opt;
		this.constructor._write_store(map);
	}
	load_preset(name){
		const map = this.constructor._read_store();
		if(map[name]) {
			this.opt = JSON.parse(JSON.stringify(map[name]));
			this._sync_gui_with_opt();
			this.dirtyIn = true;
		}
	}
	delete_preset(name){
		const map = this.constructor._read_store();
		delete map[name];
		this.constructor._write_store(map);
	}

	//-----------------------------------------------------------------
	// 4.  Дублирование
	//-----------------------------------------------------------------
	duplicate(with_gui=true){
		const opt_copy = with_gui ? JSON.parse(JSON.stringify(this.opt))
								  : Object.fromEntries(Object.entries(this.opt)
											.filter(([k])=>k in this.constructor.params));
		// немного смещаем, чтобы было видно копию
		opt_copy.x = (opt_copy.x|0)+30;
		opt_copy.y = (opt_copy.y|0)+30;
		return new this.constructor(opt_copy);
	}

	//-----------------------------------------------------------------
	// 5.  Сериализация графа
	//-----------------------------------------------------------------
	toJSON(){
		return {	id:	this.id,
					type:	this.constructor.name,
					opt:	this.opt	};
	}
	static fromJSON(o){
		return new (nodesCatalog[o.type])(o.opt, o.id);
	}
}
```

