function save_graph(){
	const state = {
		nodes : nodes.map(n=>n.toJSON()),
		links : [...links].map(([pin,l])=>({
			in : {id:l.port_in.node.id,  key:l.port_in.key},
			out: {id:l.port_out.node.id, key:l.port_out.key}
		}))
	};
	localStorage.setItem('node_editor_state', JSON.stringify(state));
}

function load_graph(){
	const raw = localStorage.getItem('node_editor_state');
	if(!raw) return;
	const state = JSON.parse(raw);
	const id2node = new Map();
	state.nodes.forEach(n=>{
		const obj = BaseNode.fromJSON(n);
		id2node.set(obj.id, obj);
	});
	state.links.forEach(l=>{
		const p_out = id2node.get(l.out.id).ports.out[l.out.key];
		const p_in  = id2node.get(l.in.id ).ports.in [l.in.key ];
		createLink(p_out, p_in);
	});
}
