## 🚫 PROBLEM 1: Your recipe doesn’t support random outputs

Currently, your `FossilCleaningRecipe` returns a **fixed** `output` ItemStack. You need to **generate random output per craft**, not store it statically.

### ✅ SOLUTION: Remove `output` field from recipe, generate randomly at crafting time

Change your `FossilCleaningRecipe` class:

```java
public class FossilCleaningRecipe implements Recipe<SimpleContainer> {
    private final NonNullList<Ingredient> inputItems;
    private final ResourceLocation id;

    public FossilCleaningRecipe(NonNullList<Ingredient> inputItems, ResourceLocation id) {
        this.inputItems = inputItems;
        this.id = id;
    }

    @Override
    public boolean matches(SimpleContainer pContainer, Level pLevel) {
        if (pLevel.isClientSide()) {
            return false;
        }
        return inputItems.get(0).test(pContainer.getItem(0)) &&
               inputItems.get(1).test(pContainer.getItem(4)); // Slot 4 is second input
    }

    @Override
    public ItemStack assemble(SimpleContainer pContainer, RegistryAccess pRegistryAccess) {
        // This is called server-side during crafting — generate random output here
        return getRandomOutput(pRegistryAccess);
    }

    @Override
    public boolean canCraftInDimensions(int pWidth, int pHeight) {
        return true;
    }

    @Override
    public ItemStack getResultItem(RegistryAccess pRegistryAccess) {
        // This is used for JEI/recipe display — return a placeholder or first possible item
        return getRandomOutput(pRegistryAccess); // Or use a default like bone
    }

    @Override
    public ResourceLocation getId() {
        return id;
    }

    @Override
    public RecipeSerializer<?> getSerializer() {
        return Serializer.INSTANCE;
    }

    @Override
    public RecipeType<?> getType() {
        return Type.INSTANCE;
    }

    // --- RANDOM OUTPUT GENERATION ---
    private ItemStack getRandomOutput(RegistryAccess registryAccess) {
        // List of possible outputs with weights
        WeightedRandom<ItemStack> weightedOutputs = new WeightedRandom<>();

        // Add weighted outputs
        weightedOutputs.add(new WeightedRandom.WeightedEntry<>(new ItemStack(Items.BONE), 20));
        weightedOutputs.add(new WeightedRandom.WeightedEntry<>(new ItemStack(Items.BONE_MEAL), 15));
        weightedOutputs.add(new WeightedRandom.WeightedEntry<>(new ItemStack(Items.COAL), 10));
        weightedOutputs.add(new WeightedRandom.WeightedEntry<>(new ItemStack(Items.DEEPSLATE), 8));
        weightedOutputs.add(new WeightedRandom.WeightedEntry<>(new ItemStack(Items.COBBLESTONE), 8));
        weightedOutputs.add(new WeightedRandom.WeightedEntry<>(new ItemStack(Items.SAND), 8));

        // Random fossil from tag
        var fossilTag = registryAccess.lookupOrThrow(Registries.ITEM).getOrThrow(TagKey.create(Registries.ITEM, new ResourceLocation("prehistoricascension", "fossils")));
        var fossilItems = fossilTag.stream().toList();
        if (!fossilItems.isEmpty()) {
            ItemStack randomFossil = new ItemStack(fossilItems.get(random.nextInt(fossilItems.size())));
            weightedOutputs.add(new WeightedRandom.WeightedEntry<>(randomFossil, 10)); // Adjust weight as needed
        }

        return weightedOutputs.getRandom(random);
    }

    private static final Random random = new Random();

    // Helper class for weighted random selection
    public static class WeightedRandom<T> {
        private final List<WeightedEntry<T>> entries = new ArrayList<>();
        private double totalWeight = 0;

        public void add(WeightedEntry<T> entry) {
            entries.add(entry);
            totalWeight += entry.weight;
        }

        public T getRandom(Random rand) {
            if (entries.isEmpty()) return null;

            double r = rand.nextDouble() * totalWeight;
            double cumulativeWeight = 0;

            for (WeightedEntry<T> entry : entries) {
                cumulativeWeight += entry.weight;
                if (r <= cumulativeWeight) {
                    return entry.item;
                }
            }

            return entries.get(entries.size() - 1).item; // fallback
        }

        public static class WeightedEntry<T> {
            public final T item;
            public final double weight;

            public WeightedEntry(T item, double weight) {
                this.item = item;
                this.weight = weight;
            }
        }
    }

    // ... rest of recipe classes unchanged
}
