```java
private boolean hasRecipe() {
    Optional<FossilCleaningRecipe> recipe = getCurrentRecipe();
    if(recipe.isEmpty()) {
        return false;
    }

    // Check if inputs are present
    if (!inputItemsMatch(recipe.get())) {
        return false;
    }

    // Check if ANY output slot can accept an item (we’ll generate 3 random ones later)
    return hasEmptyOrCompatibleOutputSlots();
}

private boolean inputItemsMatch(FossilCleaningRecipe recipe) {
    SimpleContainer inventory = new SimpleContainer(this.itemHandler.getSlots());
    for(int i = 0; i < itemHandler.getSlots(); i++) {
        inventory.setItem(i, this.itemHandler.getStackInSlot(i));
    }
    return recipe.matches(inventory, level);
}

private boolean hasEmptyOrCompatibleOutputSlots() {
    for (int i = 0; i < 3; i++) {
        ItemStack stack = this.itemHandler.getStackInSlot(OUTPUT_SLOT + i);
        if (stack.isEmpty() || stack.getCount() < stack.getMaxStackSize()) {
            return true;
        }
    }
    return false;
}
```

