Okay, let's refactor the code to use the Web Speech API instead of the Hugging Face transformers library.

The Web Speech API handles the audio capture, processing, and transcription natively in the browser, simplifying the code significantly.

```javascript
// import dynamicImportESM from "../../common-utils/dynamic-import-esm.js"; // No longer needed

export async function handleSpeechToText(app, plugin) {
    // Check for Web Speech API support
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
        const errorMessage = 'Web Speech API is not supported in this browser. Please try a modern browser like Chrome or Edge.';
        console.error(errorMessage);
        // Update selection with error message
        await app.context.replaceSelection(errorMessage);
        // Send error message to embed
        await plugin.sendMessageToEmbed(app, 'speechtotext', errorMessage);
        // Optionally throw an error to halt further execution
        throw new Error(errorMessage);
    }

    let recognition = null; // Variable to hold the SpeechRecognition instance
    let transcribeResult = ''; // Variable to accumulate the final transcribed text
    const initialPrompt = 'Say something...';

    try {
        // Set initial text in the selection
        await app.context.replaceSelection(initialPrompt);

        // Open the sidebar embed (assuming it's used to show state or provide a stop button)
        app.openSidebarEmbed(1, { openSpeechToText: true });

        // Wait for the embed to be open (existing logic)
        // This loop also serves to keep the main function scope alive
        // while the recognition is active and the embed is open.
        let embedIsOpen = await plugin.isEmbedOpen(app);
        while (!embedIsOpen) {
             console.log('Waiting for embed...');
             await new Promise(resolve => setTimeout(resolve, 500));
             embedIsOpen = await plugin.isEmbedOpen(app);
        }

        // Initialize SpeechRecognition
        recognition = new SpeechRecognition();
        recognition.continuous = true; // Keep listening even after pauses
        recognition.interimResults = false; // We only care about final results for accumulating text
        recognition.lang = 'en-US'; // Set the language (e.g., 'en-US', 'es-ES', etc.)

        console.log('Web Speech API recognition initialized.');

        // --- Event Handlers ---

        recognition.onstart = () => {
            console.log('Speech recognition started.');
            // Optional: Send a message to the embed indicating state
            plugin.sendMessageToEmbed(app, 'speechtotext', 'listening');
             // Update selection to reflect listening state if it's still the initial prompt
             if (app.context.getSelection().text === initialPrompt) {
                 app.context.replaceSelection('Listening...');
             }
        };

        recognition.onresult = (event) => {
            console.log('Speech recognition result received.');
            let finalTranscript = '';
            // event.results is a SpeechRecognitionResultList
            // Iterate through results to find final ones
            for (let i = event.resultIndex; i < event.results.length; ++i) {
                const result = event.results[i]; // SpeechRecognitionResult
                if (result.isFinal) {
                    // result[0] is the highest confidence SpeechRecognitionAlternative
                    finalTranscript += result[0].transcript;
                }
            }

            if (finalTranscript) {
                transcribeResult += finalTranscript; // Accumulate the final text

                // Update the selection with the current accumulated text
                // Trim trailing whitespace that might come from the API results
                const currentText = transcribeResult.trim();
                console.log('Accumulated text:', currentText);

                // Replace the selection content
                // Only replace if there's new text to avoid unnecessary updates/cursor jumps
                // unless the current selection is still the initial prompt/loading text
                const currentSelectionText = app.context.getSelection().text;
                if (currentSelectionText === initialPrompt || currentSelectionText === 'Listening...' || currentText !== currentSelectionText.trim()) {
