                // Optional: Send updated text to the embed
                // plugin.sendMessageToEmbed(app, 'speechtotext', currentText);
            }
        };

        recognition.onerror = (event) => {
            console.error('Speech recognition error:', event.error);
            // Stop recognition on error to prevent it from continuing
            if (recognition && (recognition.state === 'listening' || recognition.state === 'recognizing')) {
                 recognition.stop(); // Use stop to allow onend to fire gracefully
            }
            // Update selection/embed with error message
            const errorMessage = `Speech recognition error: ${event.error}`;
             app.context.replaceSelection(`Error: ${event.error}`);
             plugin.sendMessageToEmbed(app, 'speechtotext', errorMessage);

             // You might want to re-throw or handle the error here
             // Depending on desired behavior (e.g., stop process or try again)
             // Let's rely on the outer catch for final cleanup and re-throwing
        };

        recognition.onend = () => {
            console.log('Speech recognition ended.');
