//+------------------------------------------------------------------+
void OpenBuy()
{
   double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
   double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);
   double point = SymbolInfoDouble(_Symbol, SYMBOL_POINT);

   double sl = bid - InpStopLoss * point;
   double tp = bid + InpTakeProfit * point;

   //--- Normalize prices
   int digits = (int)SymbolInfoInteger(_Symbol, SYMBOL_DIGITS);
   sl = NormalizeDouble(sl, digits);
   tp = NormalizeDouble(tp, digits);

   //--- Calculate slippage
   ulong slippagePoints = (ulong)(ask * InpSlippage / 100.0 / point);
   trade.SetDeviationInPoints(slippagePoints);

   if(trade.Buy(InpLot, _Symbol, ask, sl, tp, "Trend Konfirmasi"))
   {
      Print("Buy order opened successfully at ", ask);
   }
   else
   {
      Print("Failed to open buy order. Error: ", trade.ResultRetcode(), " - ", trade.ResultRetcodeDescription());
   }
}

//+------------------------------------------------------------------+
//| Open Sell Position                                               |
//+------------------------------------------------------------------+
void OpenSell()
{
   double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
   double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);
   double point = SymbolInfoDouble(_Symbol, SYMBOL_POINT);

   double sl = ask + InpStopLoss * point;
   double tp = ask - InpTakeProfit * point;

   //--- Normalize prices
   int digits = (int)SymbolInfoInteger(_Symbol, SYMBOL_DIGITS);
   sl = NormalizeDouble(sl, digits);
   tp = NormalizeDouble(tp, digits);

   //--- Calculate slippage
   ulong slippagePoints = (ulong)(bid * InpSlippage / 100.0 / point);
   trade.SetDeviationInPoints(slippagePoints);

   if(trade.Sell(InpLot, _Symbol, bid, sl, tp, "Trend Konfirmasi"))
   {
      Print("Sell order opened successfully at ", bid);
   }
   else
   {
      Print("Failed to open sell order. Error: ", trade.ResultRetcode(), " - ", trade.ResultRetcodeDescription());
   }
}

//+------------------------------------------------------------------+
//| Manage Trailing Stop                                             |
//+------------------------------------------------------------------+
void ManageTrailingStop()
{
   if(!PositionSelectByMagic(_Symbol, magicNumber)) return;

   double point = SymbolInfoDouble(_Symbol, SYMBOL_POINT);
   int digits = (int)SymbolInfoInteger(_Symbol, SYMBOL_DIGITS);
   double currentPrice = 0;
   double positionPrice = PositionGetDouble(POSITION_PRICE_OPEN);
   double currentSL = PositionGetDouble(POSITION_SL);
   double currentTP = PositionGetDouble(POSITION_TP);
   ENUM_POSITION_TYPE posType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);

   if(posType == POSITION_TYPE_BUY)
   {
      currentPrice = SymbolInfoDouble(_Symbol, SYMBOL_BID);

      if(currentPrice - positionPrice >= InpTrailingStart * point)
      {
         double newSL = currentPrice - InpTrailingStop * point;
         newSL = NormalizeDouble(newSL, digits);

         if(newSL > currentSL + InpTrailingStep * point)
         {
            if(trade.PositionModify(PositionGetInteger(POSITION_TICKET), newSL, currentTP))
            {
               Print("Trailing stop updated for BUY position. New SL: ", newSL);
            }
         }
      }
   }
   else if(posType == POSITION_TYPE_SELL)
   {
      currentPrice = SymbolInfoDouble(_Symbol, SYMBOL_ASK);

      if(positionPrice - currentPrice >= InpTrailingStart * point)
      {
         double newSL = currentPrice + InpTrailingStop * point;
         newSL = NormalizeDouble(newSL, digits);

         if(newSL < currentSL - InpTrailingStep * point || currentSL == 0)
         {
            if(trade.PositionModify(PositionGetInteger(POSITION_TICKET), newSL, currentTP))
            {
               Print("Trailing stop updated for SELL position. New SL: ", newSL);
            }
         }
      }
   }
}

//+------------------------------------------------------------------+
//| Calculate MA on Buffer                                           |
//+------------------------------------------------------------------+
double CalculateMAOnBuffer(int handle, int period, ENUM_MA_METHOD method, int shift = 1)
{
   if(period <= 0) return 0;  // Validasi period

   double buffer[];
   ArraySetAsSeries(buffer, true);

   if(CopyBuffer(handle, 0, shift, period, buffer) != period) 
   {
      Print("Failed to copy buffer for MA calculation");
      return 0;
   }

   if(method == MODE_SMA)
   {
      double sum = 0;
      for(int i = 0; i < period; i++)
         sum += buffer[i];

      if(period > 0)
         return sum / period;
      else
         return 0;
   }
   else if(method == MODE_EMA)
   {
      double alpha = 2.0 / (period + 1.0);
      double ema = buffer[period-1];

      for(int i = period-2; i >= 0; i--)
         ema = buffer[i] * alpha + ema * (1 - alpha);

      return ema;
   }
   else if(method == MODE_SMMA)
   {
      double sum = 0;
      for(int i = 0; i < period; i++)
         sum += buffer[i];

      double smma = sum / period;

      for(int i = period - 1; i >= 0; i--)
         smma = (smma * (period - 1) + buffer[i]) / period;

      return smma;
   }
   else if(method == MODE_LWMA)
   {
      double sum = 0;
      double weight_sum = 0;

      for(int i = 0; i < period; i++)
      {
         int weight = period - i;
         sum += buffer[i] * weight;
         weight_sum += weight;
      }

      if(weight_sum > 0)
         return sum / weight_sum;
      else
         return 0;
   }

   return 0;
}

//+------------------------------------------------------------------+
//| Position Select by Magic Number                                  |
//+------------------------------------------------------------------+
bool PositionSelectByMagic(string symbol, ulong magic)
{
   for(int i = PositionsTotal()-1; i >= 0; i--)
   {
      ulong ticket = PositionGetTicket(i);
      if(PositionSelectByTicket(ticket))
      {
         if(PositionGetString(POSITION_SYMBOL) == symbol && 
            PositionGetInteger(POSITION_MAGIC) == magic)
         {
            return true;
         }
      }
   }
   return false;
}
