//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
   //--- Check for new candle
   static datetime lastTime = 0;
   datetime currentTime = iTime(_Symbol, PERIOD_CURRENT, 0);

   if(currentTime != lastTime)
   {
      lastTime = currentTime;

      //--- Check spread
      long spread = SymbolInfoInteger(_Symbol, SYMBOL_SPREAD);
      if(spread > InpMaxSpread) 
      {
         Print("Spread too high: ", spread);
         return;
      }

      //--- Check if position already exists
      bool hasPosition = false;
      for(int i = PositionsTotal()-1; i >= 0; i--)
      {
         ulong ticket = PositionGetTicket(i);
         if(PositionSelectByTicket(ticket))
         {
            if(PositionGetString(POSITION_SYMBOL) == _Symbol && 
               PositionGetInteger(POSITION_MAGIC) == magicNumber)
            {
               hasPosition = true;
               break;
            }
         }
      }

      if(hasPosition) return;

      //--- Check trading conditions
      if(CheckBuyConditions())
      {
         OpenBuy();
      }
      else if(CheckSellConditions())
      {
         OpenSell();
      }
   }

   //--- Manage trailing stop
   ManageTrailingStop();
}

//+------------------------------------------------------------------+
//| Check Buy Conditions                                             |
//+------------------------------------------------------------------+
bool CheckBuyConditions()
{
   //--- MA Filter
   if(InpUseMA)
   {
      double ma1[], ma2[], ma3[], ma4[], ma5[];
      ArraySetAsSeries(ma1, true);
      ArraySetAsSeries(ma2, true);
      ArraySetAsSeries(ma3, true);
      ArraySetAsSeries(ma4, true);
      ArraySetAsSeries(ma5, true);

      if(CopyBuffer(handleMA1, 0, 1, 1, ma1) != 1) return false;
      if(CopyBuffer(handleMA2, 0, 1, 1, ma2) != 1) return false;
      if(CopyBuffer(handleMA3, 0, 1, 1, ma3) != 1) return false;
      if(CopyBuffer(handleMA4, 0, 1, 1, ma4) != 1) return false;
      if(CopyBuffer(handleMA5, 0, 1, 1, ma5) != 1) return false;

      if(!(ma1[0] > ma2[0] && ma2[0] > ma3[0] && ma3[0] > ma4[0] && ma4[0] > ma5[0]))
         return false;
   }

   //--- RSI Filter
   if(InpUseRSI)
   {
      double rsi[];
      ArraySetAsSeries(rsi, true);
      if(CopyBuffer(handleRSI, 0, 1, 1, rsi) != 1) return false;

      //--- RSI > 50
      if(rsi[0] <= 50) return false;

      //--- RSI > MA
      if(InpRSIMAFilter)
      {
         double rsiMA = CalculateMAOnBuffer(handleRSI, InpRSIMAPeriod, InpRSIMAMethod);
         if(rsiMA == 0 || rsi[0] <= rsiMA) return false;
      }
   }

   //--- Stochastic Filter
   if(InpUseStoch)
   {
      double main[], signal[];
      ArraySetAsSeries(main, true);
      ArraySetAsSeries(signal, true);

      if(CopyBuffer(handleStoch, 0, 1, 1, main) != 1) return false;
      if(CopyBuffer(handleStoch, 1, 1, 1, signal) != 1) return false;

      //--- Main > Signal
      if(main[0] <= signal[0]) return false;

      //--- Main > 50
      if(main[0] <= 50) return false;

      //--- Main > MA
      if(InpStochMAFilter)
      {
         double stochMA = CalculateMAOnBuffer(handleStoch, InpStochMAPeriod, InpStochMAMethod);
         if(stochMA == 0 || main[0] <= stochMA) return false;
      }
   }

   //--- MACD Filter
   if(InpUseMACD)
   {
      double macdMain[], macdSignal[];
      ArraySetAsSeries(macdMain, true);
      ArraySetAsSeries(macdSignal, true);

      if(CopyBuffer(handleMACD, 0, 1, 1, macdMain) != 1) return false;
      if(CopyBuffer(handleMACD, 1, 1, 1, macdSignal) != 1) return false;

      //--- Main > Signal
      if(macdMain[0] <= macdSignal[0]) return false;

      //--- Main & Signal > 0
      if(macdMain[0] <= 0 || macdSignal[0] <= 0) return false;
   }

   //--- ADX Filter
   if(InpUseADX)
   {
      double adx[];
      ArraySetAsSeries(adx, true);
      if(CopyBuffer(handleADX, 0, 1, 1, adx) != 1) return false;

      if(adx[0] <= InpADXLevel) return false;
   }

   //--- Volume Filter
   if(InpUseVolume)
   {
      int volumeShift = InpVolumeOnTick ? 0 : 1;
      double volume[];
      ArraySetAsSeries(volume, true);

      if(CopyBuffer(handleVolume, 0, volumeShift, 1, volume) != 1) return false;

      double volumeMA = CalculateMAOnBuffer(handleVolume, InpVolumeMAPeriod, InpVolumeMAMethod, volumeShift);
      if(volumeMA == 0 || volume[0] <= volumeMA) return false;
   }

   //--- OBV Filter
   if(InpUseOBV)
   {
      int obvShift = InpOBVOnTick ? 0 : 1;
      double obv[];
      ArraySetAsSeries(obv, true);

      if(CopyBuffer(handleOBV, 0, obvShift, 1, obv) != 1) return false;

      double obvMA = CalculateMAOnBuffer(handleOBV, InpOBVMAPeriod, InpOBVMAMethod, obvShift);
      if(obvMA == 0 || obv[0] <= obvMA) return false;
   }

   //--- ATR Filter
   if(InpUseATR)
   {
      double atr[];
      ArraySetAsSeries(atr, true);

      if(CopyBuffer(handleATR, 0, 1, 1, atr) != 1) return false;

      double atrMA = CalculateMAOnBuffer(handleATR, InpATRMAPeriod, InpATRMAMethod);
      if(atrMA == 0 || atr[0] <= atrMA) return false;
   }

   return true;
}

//+------------------------------------------------------------------+
//| Check Sell Conditions                                            |
//+------------------------------------------------------------------+
bool CheckSellConditions()
{
   //--- MA Filter (Reversed)
   if(InpUseMA)
   {
      double ma1[], ma2[], ma3[], ma4[], ma5[];
      ArraySetAsSeries(ma1, true);
      ArraySetAsSeries(ma2, true);
      ArraySetAsSeries(ma3, true);
      ArraySetAsSeries(ma4, true);
      ArraySetAsSeries(ma5, true);

      if(CopyBuffer(handleMA1, 0, 1, 1, ma1) != 1) return false;
      if(CopyBuffer(handleMA2, 0, 1, 1, ma2) != 1) return false;
      if(CopyBuffer(handleMA3, 0, 1, 1, ma3) != 1) return false;
      if(CopyBuffer(handleMA4, 0, 1, 1, ma4) != 1) return false;
      if(CopyBuffer(handleMA5, 0, 1, 1, ma5) != 1) return false;

      if(!(ma1[0] < ma2[0] && ma2[0] < ma3[0] && ma3[0] < ma4[0] && ma4[0] < ma5[0]))
         return false;
   }

   //--- RSI Filter (Reversed)
   if(InpUseRSI)
   {
      double rsi[];
      ArraySetAsSeries(rsi, true);
      if(CopyBuffer(handleRSI, 0, 1, 1, rsi) != 1) return false;

      //--- RSI < 50
      if(rsi[0] >= 50) return false;

      //--- RSI < MA
      if(InpRSIMAFilter)
      {
         double rsiMA = CalculateMAOnBuffer(handleRSI, InpRSIMAPeriod, InpRSIMAMethod);
         if(rsiMA == 0 || rsi[0] >= rsiMA) return false;
      }
   }

   //--- Stochastic Filter (Reversed)
   if(InpUseStoch)
   {
      double main[], signal[];
      ArraySetAsSeries(main, true);
      ArraySetAsSeries(signal, true);

      if(CopyBuffer(handleStoch, 0, 1, 1, main) != 1) return false;
      if(CopyBuffer(handleStoch, 1, 1, 1, signal) != 1) return false;

      //--- Main < Signal
      if(main[0] >= signal[0]) return false;

      //--- Main < 50
      if(main[0] >= 50) return false;

      //--- Main < MA
      if(InpStochMAFilter)
      {
         double stochMA = CalculateMAOnBuffer(handleStoch, InpStochMAPeriod, InpStochMAMethod);
         if(stochMA == 0 || main[0] >= stochMA) return false;
      }
