      double macdMain[], macdSignal[];
      ArraySetAsSeries(macdMain, true);
      ArraySetAsSeries(macdSignal, true);

      if(CopyBuffer(handleMACD, 0, 1, 1, macdMain) != 1) return false;
      if(CopyBuffer(handleMACD, 1, 1, 1, macdSignal) != 1) return false;

      //--- Main < Signal
      if(macdMain[0] >= macdSignal[0]) return false;

      //--- Main & Signal < 0
      if(macdMain[0] >= 0 || macdSignal[0] >= 0) return false;
   }

   //--- ADX Filter (Same as Buy)
   if(InpUseADX)
   {
      double adx[];
      ArraySetAsSeries(adx, true);
      if(CopyBuffer(handleADX, 0, 1, 1, adx) != 1) return false;

      if(adx[0] <= InpADXLevel) return false;
   }

   //--- Volume Filter (Same as Buy)
   if(InpUseVolume)
   {
      int volumeShift = InpVolumeOnTick ? 0 : 1;
      double volume[];
      ArraySetAsSeries(volume, true);

      if(CopyBuffer(handleVolume, 0, volumeShift, 1, volume) != 1) return false;

      double volumeMA = CalculateMAOnBuffer(handleVolume, InpVolumeMAPeriod, InpVolumeMAMethod, volumeShift);
      if(volumeMA == 0 || volume[0] <= volumeMA) return false;
   }

   //--- OBV Filter (Reversed)
   if(InpUseOBV)
   {
      int obvShift = InpOBVOnTick ? 0 : 1;
      double obv[];
      ArraySetAsSeries(obv, true);

      if(CopyBuffer(handleOBV, 0, obvShift, 1, obv) != 1) return false;

      double obvMA = CalculateMAOnBuffer(handleOBV, InpOBVMAPeriod, InpOBVMAMethod, obvShift);
      if(obvMA == 0 || obv[0] >= obvMA) return false;  // FIXED: untuk sell, OBV harus di bawah MA
   }

   //--- ATR Filter (Same as Buy)
   if(InpUseATR)
   {
      double atr[];
      ArraySetAsSeries(atr, true);

      if(CopyBuffer(handleATR, 0, 1, 1, atr) != 1) return false;

      double atrMA = CalculateMAOnBuffer(handleATR, InpATRMAPeriod, InpATRMAMethod);
      if(atrMA == 0 || atr[0] <= atrMA) return false;
   }

