void ManageTrailingStop()
{
   if(!PositionSelectByMagic(_Symbol, magicNumber)) return;

   double point = SymbolInfoDouble(_Symbol, SYMBOL_POINT);
   int digits = (int)SymbolInfoInteger(_Symbol, SYMBOL_DIGITS);
   double currentPrice = 0;
   double positionPrice = PositionGetDouble(POSITION_PRICE_OPEN);
   double currentSL = PositionGetDouble(POSITION_SL);
   double currentTP = PositionGetDouble(POSITION_TP);
   ENUM_POSITION_TYPE posType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);

   if(posType == POSITION_TYPE_BUY)
   {
      currentPrice = SymbolInfoDouble(_Symbol, SYMBOL_BID);

      if(currentPrice - positionPrice >= InpTrailingStart * point)
      {
         double newSL = currentPrice - InpTrailingStop * point;
         newSL = NormalizeDouble(newSL, digits);

         if(newSL > currentSL + InpTrailingStep * point)
         {
            if(trade.PositionModify(PositionGetInteger(POSITION_TICKET), newSL, currentTP))
            {
               Print("Trailing stop updated for BUY position. New SL: ", newSL);
            }
         }
      }
   }
   else if(posType == POSITION_TYPE_SELL)
   {
      currentPrice = SymbolInfoDouble(_Symbol, SYMBOL_ASK);

      if(positionPrice - currentPrice >= InpTrailingStart * point)
      {
         double newSL = currentPrice + InpTrailingStop * point;
         newSL = NormalizeDouble(newSL, digits);

         if(newSL < currentSL - InpTrailingStep * point || currentSL == 0)
         {
            if(trade.PositionModify(PositionGetInteger(POSITION_TICKET), newSL, currentTP))
            {
               Print("Trailing stop updated for SELL position. New SL: ", newSL);
            }
         }
      }
