//| Calculate MA on Buffer                                           |
//+------------------------------------------------------------------+
double CalculateMAOnBuffer(int handle, int period, ENUM_MA_METHOD method, int shift = 1)
{
   if(period <= 0) return 0;  // Validasi period

   double buffer[];
   ArraySetAsSeries(buffer, true);

   if(CopyBuffer(handle, 0, shift, period, buffer) != period) 
   {
      Print("Failed to copy buffer for MA calculation");
      return 0;
   }

   if(method == MODE_SMA)
   {
      double sum = 0;
      for(int i = 0; i < period; i++)
         sum += buffer[i];

      if(period > 0)
         return sum / period;
      else
         return 0;
   }
   else if(method == MODE_EMA)
   {
      double alpha = 2.0 / (period + 1.0);
      double ema = buffer[period-1];

      for(int i = period-2; i >= 0; i--)
         ema = buffer[i] * alpha + ema * (1 - alpha);

      return ema;
   }
   else if(method == MODE_SMMA)
   {
      double sum = 0;
      for(int i = 0; i < period; i++)
         sum += buffer[i];

      double smma = sum / period;

      for(int i = period - 1; i >= 0; i--)
         smma = (smma * (period - 1) + buffer[i]) / period;

      return smma;
   }
   else if(method == MODE_LWMA)
   {
      double sum = 0;
      double weight_sum = 0;

      for(int i = 0; i < period; i++)
      {
         int weight = period - i;
         sum += buffer[i] * weight;
         weight_sum += weight;
      }

      if(weight_sum > 0)
         return sum / weight_sum;
      else
         return 0;
   }

   return 0;
}

