                   .Lookup<GraphTreeWithDevices<DoorSchema>, Property, GraphTreeWithAll<DoorSchema>>(
                       DB.Collection<Property>(),
                       d => d.TreeNodes.Select(x => x.PropertyIds),
                       p => p.Id,
                       r => r.Properties)
                   .Project(p => new GraphTreeWithAll<DoorSchema>
                   {
