    <script>
        // Game Configuration
        const CONFIG = {
            GRID_SIZE: 40,
            TILE_SIZE: 20,
            GROWTH_RATE: 0.02,
            EVOLUTION_CHANCE: 0.001,
            POPULATION_PER_RESIDENTIAL: 10,
            JOBS_PER_COMMERCIAL: 8,
            JOBS_PER_INDUSTRIAL: 12,
            SPEED_MULTIPLIERS: {
                slow: 0.5,
                normal: 1,
                fast: 3
            }
        };

        // Zone Types and Colors
        const ZONES = {
            empty: { color: '#111111', glow: false },
            road: { color: '#333333', glow: false },
            residential: { 
                color: '#00ff00', 
                glow: true,
                subzones: ['apartments', 'megaTowers', 'slums']
            },
            commercial: { 
                color: '#0064ff', 
                glow: true,
                subzones: ['shops', 'malls', 'markets']
            },
            industrial: { 
                color: '#ffc800', 
                glow: true,
                subzones: ['factories', 'techLabs', 'warehouses']
            },
            // Subzones
            apartments: { color: '#00cc00', glow: true, parent: 'residential' },
            megaTowers: { color: '#00ff99', glow: true, parent: 'residential' },
            slums: { color: '#669900', glow: true, parent: 'residential' },
            shops: { color: '#0099ff', glow: true, parent: 'commercial' },
            malls: { color: '#0033cc', glow: true, parent: 'commercial' },
            markets: { color: '#3366ff', glow: true, parent: 'commercial' },
            factories: { color: '#ff9900', glow: true, parent: 'industrial' },
            techLabs: { color: '#ffcc00', glow: true, parent: 'industrial' },
            warehouses: { color: '#cc9900', glow: true, parent: 'industrial' }
        };

        // Grid Module
        const Grid = {
            data: [],

            init() {
                this.data = Array(CONFIG.GRID_SIZE).fill(null).map(() => 
                    Array(CONFIG.GRID_SIZE).fill('empty')
                );
            },

            getCell(x, y) {
                if (x < 0 || x >= CONFIG.GRID_SIZE || y < 0 || y >= CONFIG.GRID_SIZE) {
                    return null;
                }
                return this.data[y][x];
            },

            setCell(x, y, type) {
                if (x >= 0 && x < CONFIG.GRID_SIZE && y >= 0 && y < CONFIG.GRID_SIZE) {
                    this.data[y][x] = type;
                }
            },

            getNeighbors(x, y) {
                const neighbors = [];
                const dirs = [[-1,0], [1,0], [0,-1], [0,1]];

                for (const [dx, dy] of dirs) {
                    const nx = x + dx;
                    const ny = y + dy;
                    const cell = this.getCell(nx, ny);
                    if (cell !== null) {
                        neighbors.push({ x: nx, y: ny, type: cell });
                    }
                }

                return neighbors;
            },

            countZones() {
                const counts = {};

                for (let y = 0; y < CONFIG.GRID_SIZE; y++) {
                    for (let x = 0; x < CONFIG.GRID_SIZE; x++) {
                        const type = this.data[y][x];
                        counts[type] = (counts[type] || 0) + 1;
                    }
                }

                return counts;
            }
        };

        // Population Module
        const Population = {
            current: 0,
            capacity: 0,
            jobs: 0,
            employed: 0,

            update() {
                const zones = Grid.countZones();

                // Calculate capacity
                this.capacity = 0;
                this.capacity += (zones.residential || 0) * CONFIG.POPULATION_PER_RESIDENTIAL;
                this.capacity += (zones.apartments || 0) * CONFIG.POPULATION_PER_RESIDENTIAL * 2;
                this.capacity += (zones.megaTowers || 0) * CONFIG.POPULATION_PER_RESIDENTIAL * 5;
                this.capacity += (zones.slums || 0) * CONFIG.POPULATION_PER_RESIDENTIAL * 3;

                // Calculate jobs
                this.jobs = 0;
                this.jobs += (zones.commercial || 0) * CONFIG.JOBS_PER_COMMERCIAL;
                this.jobs += (zones.shops || 0) * CONFIG.JOBS_PER_COMMERCIAL * 1.5;
                this.jobs += (zones.malls || 0) * CONFIG.JOBS_PER_COMMERCIAL * 3;
                this.jobs += (zones.markets || 0) * CONFIG.JOBS_PER_COMMERCIAL * 2;
                this.jobs += (zones.industrial || 0) * CONFIG.JOBS_PER_INDUSTRIAL;
                this.jobs += (zones.factories || 0) * CONFIG.JOBS_PER_INDUSTRIAL * 2;
                this.jobs += (zones.techLabs || 0) * CONFIG.JOBS_PER_INDUSTRIAL * 1.5;
                this.jobs += (zones.warehouses || 0) * CONFIG.JOBS_PER_INDUSTRIAL * 2.5;

                // Update population
                if (this.current < this.capacity) {
                    const growthRate = this.jobs > this.current ? 0.1 : 0.02;
                    this.current += Math.min(growthRate * Simulation.speedMultiplier, 
                                            this.capacity - this.current);
                }

                // Update employment
                this.employed = Math.min(this.current, this.jobs);

                this.updateUI();
            },

            updateUI() {
                document.getElementById('population').textContent = 
                    `${Math.floor(this.current)} / ${Math.floor(this.capacity)}`;
                document.getElementById('employment').textContent = 
                    `${Math.floor(this.employed)} / ${Math.floor(this.jobs)}`;

                // Update demand
                const demandEl = document.getElementById('demand');
                if (this.capacity === 0 && this.jobs === 0) {
                    demandEl.textContent = 'BUILD SOMETHING!';
                    demandEl.className = 'font-bold text-gray-400 mt-1';
                } else if (this.jobs > this.current * 1.2) {
                    demandEl.textContent = 'WORKERS NEEDED';
                    demandEl.className = 'font-bold text-green-400 mt-1';
                } else if (this.current > this.jobs * 1.2 && this.current > 10) {
                    demandEl.textContent = 'JOBS NEEDED';
                    demandEl.className = 'font-bold text-blue-400 mt-1';
                } else {
                    demandEl.textContent = 'BALANCED';
                    demandEl.className = 'font-bold text-yellow-400 mt-1';
                }
            },

            getDemandMultiplier(zoneType) {
                if (this.jobs > this.current * 1.2 && zoneType === 'residential') {
                    return 3;
                } else if (this.current > this.jobs * 1.2 && 
                          (zoneType === 'commercial' || zoneType === 'industrial')) {
                    return 3;
                }
                return 1;
            }
        };

        // Simulation Module
        const Simulation = {
            time: 0,
            speedMultiplier: 1,
            running: true,

            update() {
                if (!this.running) return;

                // Update time
                this.time += 0.01 * this.speedMultiplier;
                if (this.time >= 24) this.time = 0;

                // Growth simulation
                for (let y = 0; y < CONFIG.GRID_SIZE; y++) {
                    for (let x = 0; x < CONFIG.GRID_SIZE; x++) {
                        const currentType = Grid.getCell(x, y);

                        if (currentType === 'empty') {
                            this.tryGrowth(x, y);
                        } else if (ZONES[currentType]?.subzones) {
                            this.tryEvolution(x, y, currentType);
                        }
                    }
                }

                // Update population
                Population.update();

                // Update UI
                this.updateTimeDisplay();
                this.updateZoneData();
            },

            tryGrowth(x, y) {
                const neighbors = Grid.getNeighbors(x, y);
                const zoneNeighbors = neighbors.filter(n => 
                    n.type !== 'empty' && n.type !== 'road'
                );

                if (zoneNeighbors.length === 0) return;

                // Don't grow across roads
                const hasRoadBetween = neighbors.some(n => n.type === 'road');
                if (hasRoadBetween) return;

                // Pick a random zone type from neighbors
                const source = zoneNeighbors[Math.floor(Math.random() * zoneNeighbors.length)];
                let zoneType = source.type;

                // Convert subzones back to main type for spreading
                if (ZONES[zoneType].parent) {
                    zoneType = ZONES[zoneType].parent;
                }

                const demandMultiplier = Population.getDemandMultiplier(zoneType);
                const growthChance = CONFIG.GROWTH_RATE * this.speedMultiplier * demandMultiplier;

                if (Math.random() < growthChance) {
                    Grid.setCell(x, y, zoneType);
                }
            },

            tryEvolution(x, y, zoneType) {
                const neighbors = Grid.getNeighbors(x, y);
                const sameTypeCount = neighbors.filter(n => 
                    n.type === zoneType || ZONES[n.type]?.parent === zoneType
                ).length;

                if (sameTypeCount >= 3 && Math.random() < CONFIG.EVOLUTION_CHANCE * this.speedMultiplier) {
                    const subzones = ZONES[zoneType].subzones;
                    const evolved = subzones[Math.floor(Math.random() * subzones.length)];
                    Grid.setCell(x, y, evolved);
                }
            },

            updateTimeDisplay() {
                const hours = Math.floor(this.time);
                const minutes = Math.floor((this.time - hours) * 60);
                document.getElementById('gameTime').textContent = 
                    `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
            },

            updateZoneData() {
                const counts = Grid.countZones();
                const zoneDataEl = document.getElementById('zoneData');
                let html = '';

                const mainZones = ['residential', 'commercial', 'industrial'];

                for (const zone of mainZones) {
                    if (counts[zone] || ZONES[zone].subzones.some(sz => counts[sz])) {
                        html += `<div class="mb-2">`;
                        html += `<div class="font-bold ${zone}">${zone.toUpperCase()}: ${counts[zone] || 0}</div>`;

                        for (const subzone of ZONES[zone].subzones) {
                            if (counts[subzone]) {
                                html += `<div class="ml-4 text-gray-400">- ${subzone}: ${counts[subzone]}</div>`;
                            }
                        }
                        html += `</div>`;
                    }
                }

                zoneDataEl.innerHTML = html;
            },

            setSpeed(speed) {
                this.speedMultiplier = CONFIG.SPEED_MULTIPLIERS[speed];

                // Update UI
                document.querySelectorAll('.speed-button').forEach(btn => {
                    btn.classList.toggle('active', btn.dataset.speed === speed);
                });
            },

            isDayTime() {
                return this.time >= 6 && this.time < 18;
            }
        };

        // Renderer Module
        const Renderer = {
            canvas: null,
            ctx: null,

            init() {
                this.canvas = document.getElementById('gameCanvas');
                this.ctx = this.canvas.getContext('2d');

                // Set actual canvas size
                this.canvas.width = CONFIG.GRID_SIZE * CONFIG.TILE_SIZE;
                this.canvas.height = CONFIG.GRID_SIZE * CONFIG.TILE_SIZE;
            },

            render() {
                // Clear canvas
                this.ctx.fillStyle = '#0a0a0a';
                this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

                const isDayTime = Simulation.isDayTime();
                const glowIntensity = isDayTime ? 0.3 : 1;

                // Draw grid
                for (let y = 0; y < CONFIG.GRID_SIZE; y++) {
                    for (let x = 0; x < CONFIG.GRID_SIZE; x++) {
                        const type = Grid.getCell(x, y);
                        const zone = ZONES[type];

                        if (zone) {
                            const px = x * CONFIG.TILE_SIZE;
                            const py = y * CONFIG.TILE_SIZE;

                            // Draw base tile
                            this.ctx.fillStyle = isDayTime ? zone.color : 
                                this.adjustColorForNight(zone.color);
                            this.ctx.fillRect(px, py, CONFIG.TILE_SIZE - 1, CONFIG.TILE_SIZE - 1);

                            // Draw glow effect
                            if (zone.glow) {
                                this.ctx.shadowColor = zone.color;
                                this.ctx.shadowBlur = 10 * glowIntensity;
                                this.ctx.fillRect(px, py, CONFIG.TILE_SIZE - 1, CONFIG.TILE_SIZE - 1);
                                this.ctx.shadowBlur = 0;
                            }
                        }
                    }
                }

                // Draw grid lines
                this.ctx.strokeStyle = '#222';
                this.ctx.lineWidth = 1;

                for (let i = 0; i <= CONFIG.GRID_SIZE; i++) {
                    this.ctx.beginPath();
                    this.ctx.moveTo(i * CONFIG.TILE_SIZE, 0);
                    this.ctx.lineTo(i * CONFIG.TILE_SIZE, this.canvas.height);
                    this.ctx.stroke();

                    this.ctx.beginPath();
                    this.ctx.moveTo(0, i * CONFIG.TILE_SIZE);
                    this.ctx.lineTo(this.canvas.width, i * CONFIG.TILE_SIZE);
                    this.ctx.stroke();
                }
            },

            adjustColorForNight(color) {
                // Darken colors at night
                const r = parseInt(color.slice(1, 3), 16);
                const g = parseInt(color.slice(3, 5), 16);
                const b = parseInt(color.slice(5, 7), 16);

                const factor = 0.4;
                const nr = Math.floor(r * factor);
                const ng = Math.floor(g * factor);
                const nb = Math.floor(b * factor);

                return `#${nr.toString(16).padStart(2, '0')}${ng.toString(16).padStart(2, '0')}${nb.toString(16).padStart(2, '0')}`;
            }
        };

        // Input Handler Module
        const InputHandler = {
            currentTool: 'residential',
            isDrawing: false,
            lastX: -1,
            lastY: -1,

            init() {
                const canvas = document.getElementById('gameCanvas');

                // Mouse events
                canvas.addEventListener('mousedown', (e) => this.startDrawing(e));
                canvas.addEventListener('mousemove', (e) => this.draw(e));
                canvas.addEventListener('mouseup', () => this.stopDrawing());
                canvas.addEventListener('mouseleave', () => this.stopDrawing());

                // Touch events
                canvas.addEventListener('touchstart', (e) => {
                    e.preventDefault();
                    this.startDrawing(e.touches[0]);
                });
                canvas.addEventListener('touchmove', (e) => {
                    e.preventDefault();
                    this.draw(e.touches[0]);
                });
                canvas.addEventListener('touchend', () => this.stopDrawing());

                // Tool buttons
                document.querySelectorAll('.tool-button').forEach(btn => {
                    btn.addEventListener('click', () => {
                        this.setTool(btn.dataset.tool);
                    });
                });

                // Speed buttons
                document.querySelectorAll('.speed-button').forEach(btn => {
                    btn.addEventListener('click', () => {
                        Simulation.setSpeed(btn.dataset.speed);
                    });
                });

                // Preset buttons
                document.querySelectorAll('.preset-button').forEach(btn => {
                    btn.addEventListener('click', () => {
                        this.applyPreset(btn.dataset.preset);
                    });
                });

                // Advisor button
                document.getElementById('advisorButton').addEventListener('click', () => {
                    this.generateAdvisorReport();
                });

                // Set initial tool
                this.setTool('residential');
            },

            setTool(tool) {
                this.currentTool = tool;

                // Update UI
                document.querySelectorAll('.tool-button').forEach(btn => {
                    btn.classList.toggle('active', btn.dataset.tool === tool);
                });
            },

            startDrawing(e) {
                this.isDrawing = true;
                this.draw(e);
            },

            draw(e) {
                if (!this.isDrawing) return;

                const rect = Renderer.canvas.getBoundingClientRect();
                const scaleX = Renderer.canvas.width / rect.width;
                const scaleY = Renderer.canvas.height / rect.height;

                const x = Math.floor((e.clientX - rect.left) * scaleX / CONFIG.TILE_SIZE);
                const y = Math.floor((e.clientY - rect.top) * scaleY / CONFIG.TILE_SIZE);

                if (x !== this.lastX || y !== this.lastY) {
                    const zoneType = this.currentTool === 'clear' ? 'empty' : this.currentTool;
                    Grid.setCell(x, y, zoneType);

                    this.lastX = x;
                    this.lastY = y;
                }
            },

            stopDrawing() {
                this.isDrawing = false;
                this.lastX = -1;
                this.lastY = -1;
            },

            applyPreset(preset) {
                switch (preset) {
                    case 'clear':
                        Grid.init();
                        break;

                    case 'grid':
                        Grid.init();
                        // Create a grid pattern of roads
                        for (let i = 0; i < CONFIG.GRID_SIZE; i += 8) {
                            for (let j = 0; j < CONFIG.GRID_SIZE; j++) {
                                Grid.setCell(i, j, 'road');
                                Grid.setCell(j, i, 'road');
                            }
                        }
                        break;

                    case 'park':
                        Grid.init();
                        // Create roads around edges and center park
                        const center = Math.floor(CONFIG.GRID_SIZE / 2);
                        const parkSize = 8;

                        // Outer roads
                        for (let i = 0; i < CONFIG.GRID_SIZE; i++) {
                            Grid.setCell(i, 5, 'road');
                            Grid.setCell(i, CONFIG.GRID_SIZE - 6, 'road');
                            Grid.setCell(5, i, 'road');
                            Grid.setCell(CONFIG.GRID_SIZE - 6, i, 'road');
                        }

                        // Park roads
                        for (let i = center - parkSize; i <= center + parkSize; i++) {
                            Grid.setCell(i, center - parkSize, 'road');
                            Grid.setCell(i, center + parkSize, 'road');
                            Grid.setCell(center - parkSize, i, 'road');
                            Grid.setCell(center + parkSize, i, 'road');
                        }
                        break;

                    case 'highway':
                        Grid.init();
                        // Create main highway through center
                        const highway = Math.floor(CONFIG.GRID_SIZE / 2);

                        for (let i = 0; i < CONFIG.GRID_SIZE; i++) {
                            Grid.setCell(i, highway - 1, 'road');
                            Grid.setCell(i, highway, 'road');
                            Grid.setCell(i, highway + 1, 'road');

                            // Side roads
                            if (i % 10 === 0) {
                                for (let j = 0; j < CONFIG.GRID_SIZE; j++) {
                                    Grid.setCell(i, j, 'road');
                                }
                            }
                        }
                        break;
                }
            },

            generateAdvisorReport() {
                const zones = Grid.countZones();
                const pop = Population.current;
                const jobs = Population.jobs;

                let report = "";

                if (pop === 0 && jobs === 0) {
                    report = "Listen up, rookie. This empty wasteland ain't gonna build itself. " +
                             "Start laying down some zones before the corps decide this land's better off as a toxic dump.";
                } else if (jobs > pop * 1.5) {
                    report = "Your corps are screaming for warm bodies, choom. All these empty workstations... " +
                             `${Math.floor(jobs - pop)} positions unfilled. Build more residential before the suits start importing cheap labor from the wastelands.`;
