                             "watch the demand indicators, and maybe - just maybe - you won't end up with another failed dystopia.";
                }

                const reportEl = document.getElementById('advisorReport');
                reportEl.textContent = report;
                reportEl.classList.remove('hidden');
            }
        };

        // Main Game Loop
        const Game = {
            init() {
                Grid.init();
                Renderer.init();
                InputHandler.init();
                Simulation.setSpeed('normal');

                this.loop();
            },

            loop() {
                Simulation.update();
                Renderer.render();

