    <script>
        // Constants
        const TILE_SIZE = 20;
        const GRID_WIDTH = 40;
        const GRID_HEIGHT = 30;
        const CANVAS_WIDTH = TILE_SIZE * GRID_WIDTH;
        const CANVAS_HEIGHT = TILE_SIZE * GRID_HEIGHT;
        const GAME_SPEED = { SLOW: 0.5, NORMAL: 1, FAST: 2 };
        const ZONE_TYPES = {
            EMPTY: { name: 'Empty', color: '#111', spread: 0 },
            ROAD: { name: 'Road', color: '#444', spread: 0 },
            RESIDENTIAL: { name: 'Residential', color: '#0f0', spread: 0.005, subZones: ['Apartments', 'Mega-Towers', 'Slums'] },
            COMMERCIAL: { name: 'Commercial', color: '#0ff', spread: 0.003, subZones: ['Mall', 'Corporate', 'Market'] },
            INDUSTRIAL: { name: 'Industrial', color: '#f00', spread: 0.004, subZones: ['Factory', 'Refinery', 'Warehouse'] },
            BULLDOZE: { name: 'Bulldoze', color: '#f0f' }
        };

        // Game State
        let currentTool = ZONE_TYPES.RESIDENTIAL;
        let simulationSpeed = GAME_SPEED.NORMAL;
        let lastTime = 0;
        let timeOfDay = 0; // 0-24 hours
        let populationData = { current: 0, capacity: 0, jobs: 0 };

        // Initialize Canvas
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        canvas.style.backgroundColor = '#000';

        // Grid Class
        class Grid {
            constructor(width, height) {
                this.width = width;
                this.height = height;
                this.tiles = Array(height).fill().map(() => 
                    Array(width).fill().map(() => ({
                        type: ZONE_TYPES.EMPTY,
                        subZone: null,
                        age: 0
                    }))
                );
                this.zoneCounts = {};
            }

            getTile(x, y) {
                if (x < 0 || y < 0 || x >= this.width || y >= this.height) return null;
                return this.tiles[y][x];
            }

            setTile(x, y, type) {
                if (x < 0 || y < 0 || x >= this.width || y >= this.height) return;
                const tile = this.tiles[y][x];
                tile.type = type;
                tile.subZone = null;
                tile.age = 0;
                this.updateZoneCounts();
            }

            updateZoneCounts() {
                this.zoneCounts = {};
                for (let y = 0; y < this.height; y++) {
                    for (let x = 0; x < this.width; x++) {
                        const tile = this.tiles[y][x];
                        const key = tile.subZone || tile.type.name;
                        this.zoneCounts[key] = (this.zoneCounts[key] || 0) + 1;
                    }
                }
            }

            spreadZones() {
                for (let y = 0; y < this.height; y++) {
                    for (let x = 0; x < this.width; x++) {
                        const tile = this.tiles[y][x];
                        if (tile.type.spread > 0 && Math.random() < tile.type.spread * simulationSpeed) {
                            const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
                            const dir = dirs[Math.floor(Math.random() * dirs.length)];
                            const target = this.getTile(x + dir[0], y + dir[1]);
                            if (target && target.type === ZONE_TYPES.EMPTY) {
                                this.setTile(x + dir[0], y + dir[1], tile.type);
                            }
                        }
                    }
                }
            }

            evolveZones() {
                for (let y = 0; y < this.height; y++) {
                    for (let x = 0; x < this.width; x++) {
                        const tile = this.tiles[y][x];
                        if (tile.type.subZones && tile.age > 100) {
                            let adjacentCount = 0;
                            for (let dy = -1; dy <= 1; dy++) {
                                for (let dx = -1; dx <= 1; dx++) {
                                    if (dx === 0 && dy === 0) continue;
                                    const adj = this.getTile(x + dx, y + dy);
                                    if (adj && adj.type === tile.type) adjacentCount++;
                                }
                            }
                            if (adjacentCount >= 3 && Math.random() < 0.001) {
                                tile.subZone = tile.type.subZones[Math.floor(Math.random() * tile.type.subZones.length)];
                            }
                        }
                    }
                }
            }

            update() {
                this.spreadZones();
                this.evolveZones();
                this.updateZoneCounts();

                // Age tiles for evolution
                for (let y = 0; y < this.height; y++) {
                    for (let x = 0; x < this.width; x++) {
                        this.tiles[y][x].age++;
