                for (let y = 0; y < this.height; y++) {
                    for (let x = 0; x < this.width; x++) {
                        const tile = this.tiles[y][x];
                        const baseColor = tile.type.color;
                        const subZone = tile.subZone;

                        // Base tile color
                        ctx.fillStyle = baseColor;
