            bulldozeBtn.className = 'tool-btn bg-gray-800 p-2 rounded border border-purple-500';
            bulldozeBtn.style.color = '#f0f';
            bulldozeBtn.textContent = 'Bulldoze';
            bulldozeBtn.dataset.type = 'BULLDOZE';
            toolButtons.appendChild(bulldozeBtn);

            // Preset buttons
            const presetButtons = document.getElementById('preset-buttons');
            const presets = ['Grid', 'Park', 'Highway', 'Clear'];
            presets.forEach(preset => {
                const btn = document.createElement('button');
                btn.className = 'preset-btn bg-gray-800 p-2 rounded border border-green-500 text-green-400';
                btn.textContent = preset;
                presetButtons.appendChild(btn);
            });

            // Event Listeners
            document.querySelectorAll('.tool-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    currentTool = ZONE_TYPES[btn.dataset.type];
                    document.querySelectorAll('.tool-btn').forEach(b => b.classList.remove('bg-green-900'));
                    btn.classList.add('bg-green-900');
