        }

        // Preset functions
        function applyPreset(name) {
            switch(name) {
                case 'Grid':
                    // Create road grid
                    for(let x = 0; x < GRID_WIDTH; x += 5) {
                        for(let y = 0; y < GRID_HEIGHT; y++) {
                            grid.setTile(x, y, ZONE_TYPES.ROAD);
                        }
                    }
                    for(let y = 0; y < GRID_HEIGHT; y += 5) {
                        for(let x = 0; x < GRID_WIDTH; x++) {
                            grid.setTile(x, y, ZONE_TYPES.ROAD);
                        }
                    }
                    break;
                case 'Park':
                    // Central park
                    const cx = Math.floor(GRID_WIDTH/2);
                    const cy = Math.floor(GRID_HEIGHT/2);
                    for(let dx = -3; dx <= 3; dx++) {
                        for(let dy = -3; dy <= 3; dy++) {
                            grid.setTile(cx+dx, cy+dy, ZONE_TYPES.EMPTY);
                        }
                    }
                    break;
                case 'Highway':
                    // Main highway
                    const midY = Math.floor(GRID_HEIGHT/2);
                    for(let x = 0; x < GRID_WIDTH; x++) {
                        grid.setTile(x, midY, ZONE_TYPES.ROAD);
                        grid.setTile(x, midY+1, ZONE_TYPES.ROAD);
                    }
                    break;
                case 'Clear':
                    // Clear all
                    for(let y = 0; y < GRID_HEIGHT; y++) {
                        for(let x = 0; x < GRID_WIDTH; x++) {
                            grid.setTile(x, y, ZONE_TYPES.EMPTY);
                        }
                    }
                    break;
            }
        }

        // Simulation loop
        function update(deltaTime) {
            // Update time of day
            timeOfDay = (timeOfDay + deltaTime * simulationSpeed * 0.001) % 24;

            // Update population and jobs
            const zoneCounts = grid.zoneCounts;
            populationData = calculatePopulationData(zoneCounts);

            // Update grid
            grid.update();
        }

        function calculatePopulationData(zoneCounts) {
            let capacity = 0;
            let jobs = 0;
            let current = 0;

            for(const [zone, count] of Object.entries(zoneCounts)) {
                switch(zone) {
                    case 'Residential':
                    case 'Apartments':
                    case 'Mega-Towers':
                    case 'Slums':
                        capacity += count * (zone === 'Residential' ? 1 : 2);
                        break;
                    case 'Commercial':
                    case 'Mall':
                    case 'Corporate':
                    case 'Market':
                    case 'Industrial':
                    case 'Factory':
                    case 'Refinery':
                    case 'Warehouse':
                        jobs += count * (zone.includes('Industrial') ? 3 : 2);
                        break;
                }
            }

            // Calculate population growth
            const growthRate = calculateGrowthRate(capacity, jobs);
            current = Math.min(populationData.current + growthRate * deltaTime * 0.001, capacity);

            return { current, capacity, jobs };
        }

        function calculateGrowthRate(capacity, jobs) {
            const workerRatio = capacity / jobs;
            if (workerRatio < 0.5) {
                return capacity * 0.01; // High demand for workers
            } else if (workerRatio > 2) {
                return capacity * 0.001; // Housing needed
            } else {
                return capacity * 0.005; // Balanced growth
            }
        }

        // Rendering
        function render() {
            ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
            grid.draw(ctx, timeOfDay);
        }

        // UI Updates
        function updateUI() {
            // Update vitals
            document.getElementById('population').textContent = Math.floor(populationData.current);
            document.getElementById('capacity').textContent = populationData.capacity;
            document.getElementById('employment').textContent = Math.floor(populationData.current);
            document.getElementById('jobs').textContent = populationData.jobs;

            // Update demand indicator
            const workerRatio = populationData.capacity / populationData.jobs;
            const demandEl = document.getElementById('demand');
            if (workerRatio < 0.5) {
                demandEl.textContent = "Housing Needed";
                demandEl.className = "font-bold text-blue-400";
            } else if (workerRatio > 2) {
                demandEl.textContent = "Jobs Needed";
                demandEl.className = "font-bold text-red-400";
            } else {
                demandEl.textContent = "Balanced";
                demandEl.className = "font-bold text-green-400";
            }

            // Update time display
            const hours = Math.floor(timeOfDay);
            const minutes = Math.floor((timeOfDay % 1) * 60);
            document.getElementById('timeDisplay').textContent = 
                `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;

            // Update zone data
            const zoneDataEl = document.getElementById('zoneData');
            zoneDataEl.innerHTML = '';
            for(const [zone, count] of Object.entries(grid.zoneCounts)) {
                const div = document.createElement('div');
                div.textContent = `${zone}: ${count}`;
                zoneDataEl.appendChild(div);
            }
        }

        // Advisor Report
        function generateAdvisorReport() {
            const output = document.getElementById('advisorOutput');
            const workerRatio = populationData.capacity / populationData.jobs;
            let report = "CYBERPUNK CITY ADVISOR REPORT\n\n";

            if (workerRatio < 0.5) {
                report += "STATUS: CRITICAL LABOR SHORTAGE\n";
                report += "SUGGESTION: EXPAND HOUSING DEVELOPMENT\n";
                report += "WARNING: INDUSTRIAL SECTOR MAY SHUT DOWN\n";
            } else if (workerRatio > 2) {
                report += "STATUS: URBAN SPRAWL DETECTED\n";
                report += "SUGGESTION: INVEST IN COMMERCIAL INFRASTRUCTURE\n";
                report += "WARNING: SOCIAL UNREST RISK INCREASED\n";
            } else {
                report += "STATUS: TEMPORARY BALANCE MAINTAINED\n";
                report += "SUGGESTION: CONTINUE CURRENT DEVELOPMENT PLAN\n";
                report += "CAUTION: MARKET CONDITIONS CAN CHANGE\n";
            }

            // Add zone analysis
            report += "\nZONE ANALYSIS:\n";
            for(const [zone, count] of Object.entries(grid.zoneCounts)) {
                if (count > 0) {
                    report += `- ${zone}: ${count}\n`;
                }
            }

            output.textContent = report;
        }

        // Mouse handling
        canvas.addEventListener('mousedown', (e) => {
            let painting = true;
            const rect = canvas.getBoundingClientRect();

            const paint = (e) => {
                if (!painting) return;
                const x = Math.floor((e.clientX - rect.left) * canvas.width / rect.width);
                const y = Math.floor((e.clientY - rect.top) * canvas.height / rect.height);

                if (currentTool.name === 'Bulldoze') {
                    grid.setTile(x, y, ZONE_TYPES.EMPTY);
                } else {
                    grid.setTile(x, y, currentTool);
                }
            };

            paint(e);
            document.addEventListener('mousemove', paint);
            document.addEventListener('mouseup', () => {
                painting = false;
                document.removeEventListener('mousemove', paint);
            });
        });

        // Game Loop
        function gameLoop(timestamp) {
            const deltaTime = timestamp - lastTime;
            lastTime = timestamp;

            update(deltaTime);
            render();
            updateUI();

            requestAnimationFrame(gameLoop);
        }

        // Initialize
        setupUI();
        requestAnimationFrame((timestamp) => {
            lastTime = timestamp;
            gameLoop(timestamp);
        });
    </script>
