/// Specifies the configuration for a `Connection`.
#[derive(Debug, Clone)]
pub struct ConnectionConfig {
    /// The default timeout for sending a command to the browser.
    pub default_timeout: Duration,
    /// The maximum number of commands that can be buffered before new commands
    /// will be rejected. This is the capacity of the command channel.
    pub max_pending_commands: usize,
    /// The maximum number of events that can be buffered. This is the capacity
    /// of the event channel.
    pub max_buffered_events: usize,
}

impl Default for ConnectionConfig {
    fn default() -> Self {
        Self {
            default_timeout: Duration::from_secs(30),
            max_pending_commands: 1000,
            max_buffered_events: 10000,
        }
    }
}

/// Represents an active WebSocket connection to a Chrome DevTools Protocol server.
///
/// `Connection` is the primary entry point for interacting with the browser.
/// It allows sending commands and receiving events.
///
