        let (command_tx, command_rx) = mpsc::channel(config.max_pending_commands);
        let (event_tx, event_rx) = mpsc::channel(config.max_buffered_events);
        let (shutdown_tx, shutdown_rx) = mpsc::unbounded_channel();
        let next_id = Arc::new(AtomicU32::new(1));

