            # Store the select_related fields on the view instance
            if not hasattr(self, '_select_related_fields'):
                self._select_related_fields = []
            self._select_related_fields.extend(fields)

            # Call the original function
            result = func(self, *args, **kwargs)

            # Clean up after the request
            if hasattr(self, '_select_related_fields'):
                self._select_related_fields = []

            return result

        # Also store fields as an attribute on the function itself
        # This is useful for ViewSet methods like list, retrieve, etc.
        wrapper._select_related_fields = fields
