from __future__ import annotations

import uuid
from collections import defaultdict
from typing import Callable, List, Optional

import flet as ft
from pydantic import BaseModel, Field


# ────────────────────────────── Domain layer ──────────────────────────────────
class TreeNode(BaseModel):
    """
    Single conversation unit with navigation capabilities.

    Manages hierarchical structure and child navigation independently of UI.
    """

    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    role: str
    reasoning: str
    response: str
    children: List["TreeNode"] = Field(default_factory=list)
    active_index: int = 0

    @property
    def active_child(self) -> Optional["TreeNode"]:
        """Get currently selected child node."""
        if not self.children:
            return None
        self._ensure_valid_index()
        return self.children[self.active_index]

    @property
    def has_siblings(self) -> bool:
        """Check if this node has multiple siblings (used by parent)."""
        return len(self.children) > 1

    @property
    def sibling_info(self) -> tuple[int, int]:
        """Get current position and total count of children."""
        return self.active_index + 1, len(self.children)

    def navigate_to_next_child(self) -> bool:
        """Navigate to next child. Returns True if navigation occurred."""
        if not self.children:
            return False

        old_index = self.active_index
        self.active_index = min(self.active_index + 1, len(self.children) - 1)
        return old_index != self.active_index

    def navigate_to_prev_child(self) -> bool:
        """Navigate to previous child. Returns True if navigation occurred."""
        if not self.children:
            return False

        old_index = self.active_index
        self.active_index = max(self.active_index - 1, 0)
        return old_index != self.active_index

    def can_navigate_next(self) -> bool:
        """Check if can navigate to next child."""
        return self.children and self.active_index < len(self.children) - 1

    def can_navigate_prev(self) -> bool:
        """Check if can navigate to previous child."""
        return self.children and self.active_index > 0

    def update_content(self, reasoning: str, response: str) -> None:
        """Update node content."""
        self.reasoning = reasoning
        self.response = response

    def _ensure_valid_index(self) -> None:
        """Ensure active_index is within valid bounds."""
        if self.children:
            self.active_index = max(0, min(self.active_index, len(self.children) - 1))


class Tree(BaseModel):
    """
    Tree aggregate root managing multiple conversation trees.
    """

    root_nodes: List[TreeNode] = Field(default_factory=list)
    active_tree_index: int = 0

    def get_active_path(self) -> List[TreeNode]:
        """Get the path from active root to current leaf."""
        if not self.root_nodes:
            return []

        self._ensure_valid_tree_index()

        path: List[TreeNode] = []
        current_node: Optional[TreeNode] = self.root_nodes[self.active_tree_index]

        while current_node:
            path.append(current_node)
            current_node = current_node.active_child

        return path

    def _ensure_valid_tree_index(self) -> None:
        """Ensure active_tree_index is within valid bounds."""
        if self.root_nodes:
            self.active_tree_index = max(0, min(self.active_tree_index, len(self.root_nodes) - 1))


# ───────────────────────────── Event system ──────────────────────────────────
class EventBus:
    """
    Simple synchronous event bus for decoupled communication.
    """

    def __init__(self) -> None:
        self._subscribers: dict[str, list[Callable]] = defaultdict(list)

    def subscribe(self, event_type: str, callback: Callable) -> None:
        """Subscribe to an event type."""
        self._subscribers[event_type].append(callback)

    def publish(self, event_type: str, data=None) -> None:
        """Publish an event to all subscribers."""
        for callback in self._subscribers.get(event_type, []):
            callback(data)


# ──────────────────────────── Application service ─────────────────────────────
class TreeService:
    """
    Application service managing tree operations and state changes.
    """

    def __init__(self, tree: Tree, event_bus: EventBus) -> None:
        self._tree = tree
        self._event_bus = event_bus

    def update_node_content(
        self, 
        node: TreeNode, 
        reasoning: str, 
        response: str, 
        *, 
        show_notification: bool = True
    ) -> None:
        """Update node content and notify subscribers."""
        node.update_content(reasoning, response)
        self._notify_state_changed()

        if show_notification:
            self._event_bus.publish("notification", "ノードを更新しました")

    def navigate_to_next_sibling(self, parent_node: TreeNode) -> None:
        """Navigate to next sibling and notify if changed."""
        if parent_node.navigate_to_next_child():
            self._notify_state_changed()

    def navigate_to_prev_sibling(self, parent_node: TreeNode) -> None:
        """Navigate to previous sibling and notify if changed."""
        if parent_node.navigate_to_prev_child():
            self._notify_state_changed()

    def get_active_conversation_path(self) -> List[TreeNode]:
        """Get the current active conversation path."""
        return self._tree.get_active_path()

    def _notify_state_changed(self) -> None:
        """Notify subscribers that state has changed."""
        self._event_bus.publish("state_changed")


# ──────────────────────────────── UI Components ────────────────────────────────
class EditableContent:
    """Manages editable content state and operations."""

    def __init__(self, initial_reasoning: str, initial_response: str):
        self.reasoning_field = ft.TextField(
            label="Reasoning", 
            multiline=True, 
            expand=True,
            value=initial_reasoning
        )
        self.response_field = ft.TextField(
            label="Response", 
            multiline=True, 
            expand=True,
            value=initial_response
        )
        self._original_reasoning = initial_reasoning
        self._original_response = initial_response

    def get_current_values(self) -> tuple[str, str]:
        """Get current field values."""
        return self.reasoning_field.value or "", self.response_field.value or ""

    def reset_to_original(self) -> None:
        """Reset fields to original values."""
        self.reasoning_field.value = self._original_reasoning
        self.response_field.value = self._original_response

    def update_values(self, reasoning: str, response: str) -> None:
        """Update field values and store as new originals."""
        self.reasoning_field.value = reasoning
        self.response_field.value = response
        self._original_reasoning = reasoning
        self._original_response = response


class NavigationControls:
    """Creates navigation controls for sibling nodes."""

    @staticmethod
    def create_sibling_navigation(
        parent_node: TreeNode, 
        service: TreeService
    ) -> List[ft.Control]:
        """Create navigation controls if parent has multiple children."""
        if not parent_node or not parent_node.has_siblings:
            return []

        current_pos, total_count = parent_node.sibling_info

        return [
            ft.IconButton(
                icon=ft.Icons.CHEVRON_LEFT,
                on_click=lambda _: service.navigate_to_prev_sibling(parent_node),
                disabled=not parent_node.can_navigate_prev(),
                tooltip="前の兄弟ノードへ",
            ),
            ft.Text(
                f"{current_pos}/{total_count}",
                style=ft.TextThemeStyle.BODY_SMALL,
            ),
            ft.IconButton(
                icon=ft.Icons.CHEVRON_RIGHT,
                on_click=lambda _: service.navigate_to_next_sibling(parent_node),
                disabled=not parent_node.can_navigate_next(),
                tooltip="次の兄弟ノードへ",
            ),
        ]


class ChatCard(ft.Card):
    """
    Editable card component for displaying and editing TreeNode content.
    """

    def __init__(
        self,
        node: TreeNode,
        parent_node: Optional[TreeNode],
        service: TreeService,
        *args,
        **kwargs,
    ):
        self._node = node
        self._parent_node = parent_node
        self._service = service
        self._is_editing = False
        self._editable_content = EditableContent(node.reasoning, node.response)

        super().__init__(
            content=self._create_padded_content(),
            *args,
            **kwargs
        )

    def _create_padded_content(self) -> ft.Container:
        """Create main content with padding."""
        return ft.Container(
            content=self._build_card_content(),
            padding=ft.padding.all(16)
        )

    def _build_card_content(self) -> ft.Column:
        """Build the main card content based on current mode."""
        header = self._create_header()

        if self._is_editing:
            return self._create_edit_mode_content(header)
        else:
            return self._create_display_mode_content(header)

    def _create_header(self) -> ft.Row:
        """Create the card header with role, edit button, and navigation."""
        controls = [
            ft.Text(value=self._node.role, style=ft.TextThemeStyle.TITLE_SMALL),
            ft.Container(expand=True),  # Spacer
            self._create_edit_toggle_button(),
        ]

        # Add navigation controls if applicable
        nav_controls = NavigationControls.create_sibling_navigation(
            self._parent_node, self._service
        )
        controls.extend(nav_controls)

        return ft.Row(controls, alignment=ft.MainAxisAlignment.START)

    def _create_edit_toggle_button(self) -> ft.IconButton:
        """Create edit/cancel toggle button."""
        if self._is_editing:
            return ft.IconButton(
                icon=ft.Icons.EDIT,
                icon_color=ft.Colors.RED,
                on_click=self._handle_cancel_edit,
                tooltip="編集をキャンセル",
            )
        else:
            return ft.IconButton(
                icon=ft.Icons.EDIT,
                on_click=self._handle_enter_edit,
                tooltip="編集モード",
            )

    def _create_edit_mode_content(self, header: ft.Row) -> ft.Column:
        """Create content for edit mode."""
        action_buttons = ft.Row([
            ft.Container(expand=True),  # Spacer
            ft.OutlinedButton(
                text="キャンセル",
                on_click=self._handle_cancel_edit,
            ),
            ft.FilledButton(
                text="更新",
                on_click=self._handle_save_edit,
            ),
        ], spacing=8)

        return ft.Column([
            header,
            self._editable_content.reasoning_field,
            self._editable_content.response_field,
            action_buttons
        ], spacing=8)

    def _create_display_mode_content(self, header: ft.Row) -> ft.Column:
        """Create content for display mode."""
        content_controls = [header]

        # Add reasoning section if present
        if self._node.reasoning:
            content_controls.append(
                ft.ExpansionTile(
                    title=ft.Text(
                        value="Reasoning", 
                        style=ft.TextThemeStyle.LABEL_MEDIUM
                    ),
                    controls=[ft.Text(
                        value=self._node.reasoning,
                        style=ft.TextThemeStyle.BODY_MEDIUM,
                        selectable=True,
                    )]
                )
            )

        # Add response section if present
        if self._node.response:
            content_controls.append(
                ft.Text(
                    value=self._node.response,
                    style=ft.TextThemeStyle.BODY_MEDIUM,
                    selectable=True,
                )
            )

        return ft.Column(content_controls, spacing=4)

    def _handle_enter_edit(self, _) -> None:
        """Enter edit mode."""
        self._is_editing = True
        self._editable_content.update_values(self._node.reasoning, self._node.response)
        self._rebuild_content()

    def _handle_save_edit(self, _) -> None:
        """Save changes and exit edit mode."""
        reasoning, response = self._editable_content.get_current_values()
        self._service.update_node_content(self._node, reasoning, response)
        self._is_editing = False

    def _handle_cancel_edit(self, _) -> None:
        """Cancel editing and exit edit mode."""
        self._is_editing = False
        self._editable_content.reset_to_original()
        self._rebuild_content()

    def _rebuild_content(self) -> None:
        """Rebuild the card content and update display."""
        self.content = self._create_padded_content()
        self.update()


