            background: white;
            border-left: 1px solid var(--border);
            display: flex;
            flex-direction: column;
            transition: margin-right 0.3s;
        }

        .codex-sidebar.hidden {
            margin-right: -300px;
        }

        .codex-header {
            padding: 1rem;
            border-bottom: 1px solid var(--border);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .codex-search {
            padding: 0.5rem 1rem;
            border-bottom: 1px solid var(--border);
        }

        .codex-search input {
            width: 100%;
            padding: 0.5rem;
            border: 1px solid var(--border);
            border-radius: 4px;
            outline: none;
        }

        .codex-content {
            flex: 1;
            overflow-y: auto;
            padding: 1rem;
        }

        .codex-entry {
            padding: 0.75rem;
            border-radius: 4px;
            cursor: pointer;
            margin-bottom: 0.5rem;
            transition: background 0.2s;
        }

        .codex-entry:hover {
            background: var(--bg-light);
        }

        .codex-entry-title {
            font-weight: 600;
            margin-bottom: 0.25rem;
        }

        .codex-entry-type {
            font-size: 0.75rem;
            color: var(--text-secondary);
        }

        /* Plan View */
        .plan-container {
            padding: 2rem;
            overflow: auto;
            background: var(--bg-light);
        }

        .storyboard {
            display: grid;
            grid-template-columns: repeat(6, 1fr);
            gap: 1rem;
            min-width: 1200px;
        }

        .act-column {
            background: white;
            border-radius: 8px;
            padding: 1rem;
            min-height: 600px;
        }

        .act-header {
            font-weight: 600;
            margin-bottom: 1rem;
            text-align: center;
            color: var(--primary);
        }

        .chapter-card {
            background: var(--bg-light);
            border: 1px solid var(--border);
            border-radius: 4px;
            padding: 1rem;
            margin-bottom: 0.5rem;
            cursor: move;
            transition: all 0.2s;
