        .add-chapter-btn:hover {
            border-color: var(--primary);
            color: var(--primary);
        }

        /* Chat View */
        .chat-container {
            display: flex;
            height: 100%;
            background: var(--bg-light);
        }

        .chat-threads {
            width: 250px;
            background: white;
            border-right: 1px solid var(--border);
