                                <span>Total Words</span>
                                <strong>24,532</strong>
                            </div>
                            <div class="stat-item">
                                <span>Daily Average</span>
                                <strong>1,247</strong>
                            </div>
                            <div class="progress-bar">
                                <div class="progress-fill" style="width: 65%;"></div>
                            </div>
                            <p class="text-secondary">65% to goal (40,000 words)</p>
