//!HEIGHT HOOKED.h 1.5 *
//!COMPONENTS 2

vec2 hermite_vec2(vec2 t) {
    return t * t * (3.0 - 2.0 * t);
}

vec2 sample_hermite_vec2(vec2 pos, vec2 pt) {
    vec2 base_pos = pos * (1.0 / 1.5);
    vec2 base_pixel = floor(base_pos / pt) * pt;
    vec2 frac = (base_pos - base_pixel) / pt;

    vec2 p00 = HOOKED_tex(base_pixel + vec2(-pt.x, -pt.y)).xy;
    vec2 p01 = HOOKED_tex(base_pixel + vec2(-pt.x,  pt.y)).xy;
    vec2 p10 = HOOKED_tex(base_pixel + vec2( pt.x, -pt.y)).xy;
    vec2 p11 = HOOKED_tex(base_pixel + vec2( pt.x,  pt.y)).xy;

    vec2 w = hermite_vec2(frac);
    vec2 top = mix(p00, p10, w.x);
    vec2 bottom = mix(p01, p11, w.x);
    return mix(top, bottom, w.y);
}

vec4 hook() {
    vec2 upscaled = sample_hermite_vec2(HOOKED_pos, HOOKED_pt);
    return vec4(upscaled, 0.0, 1.0);
}

//!HOOK LUMA
//!BIND UPSCALED_LUMA
//!SAVE UPSCALED_LUMA_DENOISED
//!DESC Denoise Upscaled Luma (Small Noise with Guide, 2x Resolution)
//!WIDTH UPSCALED_LUMA.w
//!HEIGHT UPSCALED_LUMA.h
//!COMPONENTS 2

#define val float
#define val_guide float
#define unval(x, noise) vec4(x, noise, 0.0, 1.0)
#define val_swizz(v) (v.x)
#define GET(off) val_swizz(UPSCALED_LUMA_tex(UPSCALED_LUMA_pos + UPSCALED_LUMA_pt * (off).xy))
#define GET_GUIDE_(off) val_swizz(UPSCALED_LUMA_tex(UPSCALED_LUMA_pos + UPSCALED_LUMA_pt * (off).xy))

#define DENOISE_STRENGTH 0.74
#define S2 (DENOISE_STRENGTH * DENOISE_STRENGTH)
#define SW 1.0
#define SS_BASE 0.36
#define P 1
#define R 3
#define hr (float(R/2))
#define hp (float(P/2))

float range(float pdiff, float intensity) {
    float base_weight = exp(-pdiff / (S2 * 1.2));
    float dark_boost = intensity > 0.7 ? 1.0 : (1.5 + pow(1.0 - intensity, 5.0) * 8.7);
    return base_weight * dark_boost;
}

float spatial_r(vec3 r, float intensity) {
    float ss = SS_BASE + (1.0 - intensity) * 0.6;
    float ss2 = ss * ss;
    return exp(-dot(r.xy, r.xy) / ss2);
}

float patch_comparison(vec3 r, val base_val, float intensity) {
    float pdiff_sum = 0.0;
    float threshold = 0.5 + (1.0 - intensity) * 0.2;

    // Fixed loop using integer indices
    for (int px = -0; px <= 0; px++) {
        for (int py = -0; py <= 0; py++) {
            vec3 p = vec3(float(px), float(py), 0.0);
            val_guide poi_p = GET_GUIDE_(p + r);
            val_guide diff = poi_p - base_val;
            float diff_sq = diff * diff;
            if (diff_sq < threshold) {
                pdiff_sum += diff_sq;
            }
        }
    }
    return pdiff_sum;
}

vec4 hook() {
    vec3 r = vec3(0);
    val poi = GET(vec3(0));
    float intensity = poi;
    val original = poi;

    val total_weight = 0.0;
    val sum = 0.0;
    float sw = SW * spatial_r(vec3(0), intensity);

    // Fixed research loop using integer indices
    for (int dx = -1; dx <= 1; dx++) {
        for (int dy = -int(abs(float(abs(dx)) - hr)); dy <= int(abs(float(abs(dx)) - hr)); dy++) {
            vec3 offset = vec3(float(dx), float(dy), 0.0);
            float pdiff = patch_comparison(offset, poi, intensity);
            float weight = range(pdiff, intensity) * spatial_r(offset, intensity);
            val px = GET(offset);
            sum += px * weight;
            total_weight += weight;
        }
    }

    total_weight += sw;
    sum += poi * sw;

    val denoised = (total_weight > 0.0) ? sum / total_weight : poi;
    float blend = 0.9 + intensity * 0.06;
    val result = mix(denoised, original, blend);

    float noise_factor = clamp(abs(poi - result) * 3.0, 0.0, 1.0);
    if (intensity > 0.71 && noise_factor < 0.09) {
        return unval(original, noise_factor);
    }

    return unval(result, noise_factor);
}

