#define BASE_DENOISE_STRENGTH 0.20
#define SW 1.0
#define SS2 8.0
#define HR 2.0

float get_luma(vec2 offset) {
    return HOOKED_texOff(offset).x;
}

float local_variance(vec2 pos) {
    float mean = 0.0;
    float mean2 = 0.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            float v = HOOKED_texOff(vec2(x,y)).x;
            mean += v;
            mean2 += v*v;
        }
    }
    mean /= 9.0;
    mean2 /= 9.0;
    return max(0.0, mean2 - mean*mean);
}

float gradient_mag(vec2 pos) {
    float gx = -HOOKED_texOff(vec2(-1,-1)).x - 2.0*HOOKED_texOff(vec2(-1,0)).x - HOOKED_texOff(vec2(-1,1)).x
               + HOOKED_texOff(vec2( 1,-1)).x + 2.0*HOOKED_texOff(vec2( 1,0)).x + HOOKED_texOff(vec2( 1,1)).x;
    float gy = -HOOKED_texOff(vec2(-1,-1)).x - 2.0*HOOKED_texOff(vec2(0,-1)).x - HOOKED_texOff(vec2(1,-1)).x
               + HOOKED_texOff(vec2(-1, 1)).x + 2.0*HOOKED_texOff(vec2(0, 1)).x + HOOKED_texOff(vec2(1, 1)).x;
    return sqrt(gx*gx + gy*gy);
}

vec4 hook() {
    float poi = HOOKED_tex(HOOKED_pos).x;
    float intensity = poi;
    float original = poi;

    float before = UPSCALED_LUMA_tex(HOOKED_pos / 1.5).x;
    float after  = UPSCALED_LUMA_DENOISED_tex(HOOKED_pos / 1.5).x;
    float noise_factor = clamp(abs(before - after) * 1.5, 0.0, 1.0);
    float guide_noise  = UPSCALED_LUMA_DENOISED_tex(HOOKED_pos / 1.5).y;
    float combined_noise = max(noise_factor, guide_noise);

    float var = local_variance(HOOKED_pos);
    float grad = gradient_mag(HOOKED_pos);
    float structure = max(smoothstep(0.02, 0.08, grad),
                          smoothstep(0.01, 0.04, var));

    float base_strength = BASE_DENOISE_STRENGTH * (1.0 - intensity * 0.15);
    float adjusted_s2 = max(1e-5, base_strength * base_strength * (1.0 + combined_noise));

    float total_weight = 0.0;
    float sum = 0.0;
    for (int y = -int(HR); y <= int(HR); y++) {
        for (int x = -int(HR); x <= int(HR); x++) {
            float pdiff = 0.0;
            for (int py = -1; py <= 1; py++) {
                for (int px = -1; px <= 1; px++) {
                    float diff = HOOKED_texOff(vec2(px,py)+vec2(x,y)).x - poi;
                    pdiff += diff*diff;
                }
            }
            float w = exp(-pdiff / (adjusted_s2 * 1.5));
            w *= exp(-dot(vec2(x,y), vec2(x,y)) / SS2);
            sum += HOOKED_texOff(vec2(x,y)).x * w;
            total_weight += w;
        }
    }
    sum += poi * SW;
    total_weight += SW;

    float denoised = (total_weight > 0.0) ? sum / total_weight : poi;

    float blur_sum = 0.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            blur_sum += HOOKED_texOff(vec2(x,y)).x;
        }
    }
    float blurred = blur_sum / 9.0;
    float detail = poi - blurred;
    float detail_gain = clamp(0.5 * structure * (1.0 - combined_noise), 0.0, 0.6);

    float with_detail = denoised + detail * detail_gain;
    float blend = 0.75 + intensity * 0.05;
    float result = mix(with_detail, original, blend);

    return vec4(clamp(result, 0.0, 1.0));
}

