#define C_BASE_DENOISE 0.12
#define C_SW 1.0
#define C_SS2 6.0
#define C_HR 1

vec4 hook() {
    vec2 poi = HOOKED_tex(HOOKED_pos).xy;
    float luma = LUMA_DENOISED_tex(HOOKED_pos).x;

    vec2 sum = vec2(0.0);
