            // … other callbacks …
        })
    }
}
```

* **Pros**  
  * Works for dialogs that are attached to the same window (because they share the decor view).  
  * No need to replace `Window.Callback`.  

* **Cons**  
  * Still only catches touch events; you’d need a separate `OnKeyListener` for keyboards.  

