        sector.celestialBodies.forEach { body ->
            body.renderPosition.set(body.position).add(offset)
        }
    }
}

private fun getSectorForPosition(pos: Vector3): Vector3 {
    return Vector3(
        floor(pos.x / SECTOR_SIZE).toInt() * SECTOR_SIZE,
        floor(pos.y / SECTOR_SIZE).toInt() * SECTOR_SIZE,
        floor(pos.z / SECTOR_SIZE).toInt() * SECTOR_SIZE
    )
}

private fun manageSectorsAround(center: Vector3) {
    val keepSectors = mutableSetOf<Vector3>()

    for (x in -1..1) {
        for (y in -1..1) {
            for (z in -1..1) {
                val sectorPos = Vector3(center).add(x * SECTOR_SIZE, y * SECTOR_SIZE, z * SECTOR_SIZE)
                keepSectors.add(sectorPos)

                if (!loadedSectors.containsKey(sectorPos)) {
                    loadedSectors[sectorPos] = generateSectorWithGalaxies(sectorPos)
                }
            }
        }
    }

    loadedSectors.keys.removeAll { !keepSectors.contains(it) }
}

private fun generateSectorWithGalaxies(pos: Vector3): Sector {
