// ------------------ ROTASHADER (WITH INFINITE LOGARITHMIC DEPTH) ------------------
class RotaShader(
private val directionalLights: List<DirectionalLight>,
private val environment: Environment,
private val realCameraPosition: Vector3
) : BaseShader() {
private var initialized = false
private var timeAccumulator = 0f
private val tmpLightDir = Vector3()

text

companion object {
    const val sunVertexShader = """
#version 130
precision highp float;

in vec3 a_position;
in vec3 a_normal;
in vec2 a_texCoord0;

uniform mat4 u_projViewTrans;
uniform mat4 u_worldTrans;
uniform vec3 u_lightDirection;
uniform vec3 u_ambientLight;
uniform float u_time;
uniform float u_lightIntensity;
uniform mat4 u_shadowMatrix;

out vec3 v_normal_out;
out vec3 v_lightDir_out;
out vec2 v_texCoord0_out;
out vec3 v_ambient_out;
out float v_time_out;
out float v_lightIntensity_out;
out vec4 v_shadowCoord_out;
out vec3 v_worldPos_out;
out float v_log_w;
out float v_linearDepth;

void main() {
vec4 worldPos = u_worldTrans * vec4(a_position, 1.0);
gl_Position = u_projViewTrans * worldPos;

text

v_log_w = max(1e-10, gl_Position.w);
v_linearDepth = gl_Position.z / gl_Position.w;

v_normal_out = normalize((u_worldTrans * vec4(a_normal, 0.0)).xyz);
v_lightDir_out = normalize(u_lightDirection);
v_texCoord0_out = a_texCoord0;
v_ambient_out = u_ambientLight;
v_time_out = u_time;
v_lightIntensity_out = u_lightIntensity;

v_shadowCoord_out = u_shadowMatrix * worldPos;
v_shadowCoord_out = v_shadowCoord_out * 0.5 + 0.5;

v_worldPos_out = worldPos.xyz;
}
"""
const val sunFragmentShader = """
#version 130
precision highp float;
#extension GL_EXT_frag_depth : enable

in vec3 v_normal_out;
in vec3 v_lightDir_out;
in vec2 v_texCoord0_out;
in vec3 v_ambient_out;
in float v_time_out;
in float v_lightIntensity_out;
in vec4 v_shadowCoord_out;
in vec3 v_worldPos_out;
in float v_log_w;
in float v_linearDepth;

uniform sampler2D u_diffuseTexture;
uniform sampler2D u_emissiveTexture;
uniform float u_sunTransparency;
uniform float u_shininess;
uniform vec4 u_specularColor;
uniform float u_coronaStrength;
uniform float u_eruptionStrength;
uniform float u_eruptionHeight;
uniform sampler2D u_heightmapTexture;
uniform sampler2D u_shadowMap;
uniform float u_shadowIntensity;
uniform vec3 u_cameraPosition;
uniform float u_cameraFarPlane;
uniform float u_cameraNear; // <-- FEHLENDE DEKLARATION HINZUGEFÜGT
uniform float u_parallaxScale;
uniform float u_aoStrength;
uniform float u_shadowBias;
uniform float u_shadowSoftness;
uniform vec4 u_shadowColor;
uniform float u_contactHardening;
uniform int u_pcfSize;
uniform float u_depthScale;
uniform float u_depthOffset;

out vec4 fragColor;

// --- Noise & FBM ---
float rand(vec2 n) {
return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}
float noise(vec2 p) {
vec2 ip = floor(p);
vec2 u_fract = fract(p);
u_fract = u_fract * u_fract * (3.0 - 2.0 * u_fract);
float res = mix(
mix(rand(ip), rand(ip + vec2(1.0, 0.0)), u_fract.x),
mix(rand(ip + vec2(0.0, 1.0)), rand(ip + vec2(1.0, 1.0)), u_fract.x),
u_fract.y);
return res * res;
}
float fbm(vec2 p, int octaves) {
float value = 0.0;
float amplitude = 0.5;
for (int i = 0; i < octaves; i++) {
value += amplitude * noise(p);
p *= 2.0;
amplitude *= 0.5;
}
return value;
}

// --- Parallax Occlusion Mapping ---
vec2 parallaxOcclusionMapping(vec2 texCoords, vec3 viewDir) {
const float minLayers = 8.0;
const float maxLayers = 32.0;
float numLayers = mix(maxLayers, minLayers, abs(dot(vec3(0.0, 0.0, 1.0), viewDir)));
float layerDepth = 1.0 / numLayers;
float currentLayerDepth = 0.0;
vec2 P = viewDir.xy * u_parallaxScale;
vec2 deltaTexCoords = P / numLayers;
vec2 currentTexCoords = texCoords;
float currentDepthMapValue = texture(u_heightmapTexture, currentTexCoords).r;
while(currentLayerDepth < currentDepthMapValue) {
currentTexCoords -= deltaTexCoords;
currentDepthMapValue = texture(u_heightmapTexture, currentTexCoords).r;
currentLayerDepth += layerDepth;
}
vec2 prevTexCoords = currentTexCoords + deltaTexCoords;
float afterDepth = currentDepthMapValue - currentLayerDepth;
float beforeDepth = texture(u_heightmapTexture, prevTexCoords).r - currentLayerDepth + layerDepth;
float weight = afterDepth / (afterDepth - beforeDepth);
vec2 finalTexCoords = prevTexCoords * weight + currentTexCoords * (1.0 - weight);
return finalTexCoords;
}

// --- Ambient Occlusion ---
float calculateAmbientOcclusion(vec2 uv, float centerHeight) {
const int samples = 8;
const float radius = 0.05;
float occlusion = 0.00001;
for(int i = 0; i < samples; i++) {
float angle = 6.28318530718 * float(i) / float(samples);
vec2 sampleOffset = vec2(cos(angle), sin(angle)) * radius;
vec2 sampleUV = uv + sampleOffset;
float sampleHeight = texture(u_heightmapTexture, sampleUV).r;
float heightDiff = centerHeight - sampleHeight;
occlusion += max(0.0, heightDiff) * u_aoStrength;
}
return 1.0 - (occlusion / float(samples));
}

// --- Shadow Calculation ---
float calculateShadow(vec4 shadowCoord, float softness) {
float bias = u_shadowBias;
vec3 projCoords = shadowCoord.xyz;

text

if(projCoords.z > 1.0 || projCoords.x < 0.0 || projCoords.x > 1.0 
   || projCoords.y < 0.0 || projCoords.y > 1.0) {
    return 1.0;
}

// PCF für weichere Schatten
float shadow = 0.0;
vec2 texelSize = 1.0 / vec2(textureSize(u_shadowMap, 0));

for(int x = -u_pcfSize; x <= u_pcfSize; ++x) {
    for(int y = -u_pcfSize; y <= u_pcfSize; ++y) {
        float pcfDepth = texture(u_shadowMap, projCoords.xy + vec2(x, y) * texelSize).r;
        shadow += projCoords.z - bias > pcfDepth ? 0.0 : 1.0;
    }
}
shadow /= float((u_pcfSize * 2 + 1) * (u_pcfSize * 2 + 1));

// Contact Hardening (Schatten werden weicher mit Distanz)
if (u_contactHardening > 0.5) {
    float dist = length(v_worldPos_out - u_cameraPosition);
    float hardness = clamp(dist / 100.0, 0.1, 1.0);
    shadow = mix(shadow, 1.0, hardness * 0.3);
}

return shadow;
}

// --- Heightmap Self-Shadowing (korrigiert und stabilisiert) ---
float calculateHeightmapSelfShadow(vec2 uv, vec3 lightDir) {
// Frühe Rückkehr wenn Licht von unten kommt
if (lightDir.y <= 0.01) return 1.0;

text

float currentHeight = texture(u_heightmapTexture, uv).r;

// Adaptive Schrittweite
vec2 texelSize = 1.0 / vec2(textureSize(u_heightmapTexture, 0));
float baseStepSize = max(texelSize.x, texelSize.y) * 1.5;

// Schatten-Akkumulator - startet bei 1.0 (kein Schatten)
float shadow = 1.0;

// Berechne Steigung für Höhenprojektion
float tanLightAngle = length(lightDir.xz) / max(lightDir.y, 0.01);

// Richtungsvektor für das Sampling
vec2 stepDir = normalize(lightDir.xz);

// Adaptive Anzahl von Schritten
const int maxSteps = 16;
const float maxDistance = 0.08;

for (int i = 1; i <= maxSteps; i++) {
    float t = float(i) / float(maxSteps);
    float dist = t * maxDistance; // Lineare Distanz für weichere Übergänge

    vec2 sampleUV = uv - stepDir * dist * baseStepSize;

    // Boundary check
    if (sampleUV.x < 0.001 || sampleUV.y < 0.001 || sampleUV.x > 0.999 || sampleUV.y > 0.999) {
        continue;
    }

    sampleUV = clamp(sampleUV, 0.001, 0.999);
    float sampledHeight = texture(u_heightmapTexture, sampleUV).r;
    float projectedHeight = currentHeight + dist * tanLightAngle; // POSITIVE Richtung!

    // Weiche Schatten basierend auf Höhendifferenz
    float heightDiff = sampledHeight - projectedHeight;
    if (heightDiff > 0.0) {
        // Sanftere Okklusion
        float occlusion = smoothstep(0.0, 0.05, heightDiff);
        shadow = min(shadow, 1.0 - occlusion * 0.5); // Reduzierte Schattenstärke

        // Early termination bei starkem Schatten
        if (shadow < 0.3) break;
    }
}

// Schatten-Bias basierend auf Oberflächenneigung - reduziert
vec2 heightGradient = vec2(
    texture(u_heightmapTexture, uv + vec2(texelSize.x, 0.0)).r - 
    texture(u_heightmapTexture, uv - vec2(texelSize.x, 0.0)).r,
    texture(u_heightmapTexture, uv + vec2(0.0, texelSize.y)).r - 
    texture(u_heightmapTexture, uv - vec2(0.0, texelSize.y)).r
);

float slopeFactor = clamp(length(heightGradient) * 1.5, 0.0, 1.0);
shadow = mix(shadow, 1.0, slopeFactor * 0.2);

return clamp(shadow, 0.6, 1.0); // Mindestens 60% Sichtbarkeit
}

void main() {
// --- STABILE LOG-TIEFENBERECHNUNG ---
float nearClip = max(u_cameraNear, 0.1); // <-- JETZT DEFINIERT
float farClip = (u_cameraFarPlane > 0.0) ? u_cameraFarPlane : 1e30;
const float c = 1.0;
float depthLog = (log(max(v_log_w, 1e-10) + c) - log(nearClip + c)) /
(log(farClip + c) - log(nearClip + c));
depthLog = clamp(depthLog * 0.9995, 0.0005, 0.999999);
gl_FragDepth = depthLog;

text

if (u_sunTransparency > 0.0) {
    vec2 uv = v_texCoord0_out - 0.5;
    vec2 waveUV = v_texCoord0_out + 0.01 * vec2(
        sin(v_time_out * 3.0 + uv.y * 20.0),
        cos(v_time_out * 2.0 + uv.x * 20.0)
    );
    vec4 diffuseColor = texture(u_diffuseTexture, waveUV);
    vec4 emissiveColor = texture(u_emissiveTexture, v_texCoord0_out);
    float dist = length(uv);
    float corona = smoothstep(0.3, 0.5, dist) * u_coronaStrength;
    corona *= (1.0 + 0.2 * sin(v_time_out * 0.5 + dist * 10.0));
    vec3 sunColor = diffuseColor.rgb * (1.0 + corona);
    vec2 offset = uv * 0.03;
    vec3 aberrationColor;
    aberrationColor.r = texture(u_diffuseTexture, v_texCoord0_out + offset).r;
    aberrationColor.g = texture(u_diffuseTexture, v_texCoord0_out).g;
    aberrationColor.b = texture(u_diffuseTexture, v_texCoord0_out - offset).b;
    sunColor = mix(sunColor, aberrationColor, 0.3);
    float loop = sin((uv.x * uv.x + uv.y * uv.y) * 60.0 - v_time_out * 4.0);
    loop = smoothstep(0.4, 0.6, loop);
    sunColor += loop * vec3(1.0, 0.6, 0.2) * 0.4;
    vec2 rotatedUV = vec2(
        cos(v_time_out * 0.1) * uv.x - sin(v_time_out * 0.1) * uv.y,
        sin(v_time_out * 0.1) * uv.x + cos(v_time_out * 0.1) * uv.y
    );
    float sunspot = smoothstep(0.4, 0.6, noise(rotatedUV * 5.0));
    sunColor *= mix(1.0, 0.6, sunspot);
    float glowAlpha = smoothstep(0.45, 0.55, dist);
    sunColor = mix(sunColor, vec3(0.0), glowAlpha);
    float alpha = diffuseColor.a * u_sunTransparency * (1.0 - glowAlpha);
    vec3 viewDir = normalize(u_cameraPosition - v_worldPos_out);
    vec2 pomUV = parallaxOcclusionMapping(v_texCoord0_out, viewDir);
    float ao = calculateAmbientOcclusion(pomUV, texture(u_heightmapTexture, pomUV).r);
    vec3 reflectDir = reflect(-v_lightDir_out, v_normal_out);
    float specularTerm = max(dot(viewDir, reflectDir), 0.0);
    float spec = pow(specularTerm, u_shininess);
    vec3 specular = u_specularColor.rgb * spec;
    fragColor = vec4(sunColor + specular + emissiveColor.rgb * 2.0, alpha);
    return;
}

vec3 normal = normalize(v_normal_out);
vec3 lightDir = normalize(v_lightDir_out);
float lighting = max(dot(normal, lightDir), 0.0) * v_lightIntensity_out;
vec3 viewDir = normalize(u_cameraPosition - v_worldPos_out);
vec2 pomUV = parallaxOcclusionMapping(v_texCoord0_out, viewDir);
float heightValue = texture(u_heightmapTexture, pomUV).r;
float ao = calculateAmbientOcclusion(pomUV, heightValue);
float selfShadow = calculateHeightmapSelfShadow(pomUV, lightDir);
float shadowMapShadow = calculateShadow(v_shadowCoord_out, u_shadowSoftness);

// Kombiniere alle Schatteneffekte
float totalShadow = min(1.0, selfShadow * shadowMapShadow);
totalShadow = max(totalShadow, ao); // AO hat Vorrang

vec4 diffuseColor = texture(u_diffuseTexture, pomUV);
vec3 finalColor = diffuseColor.rgb * (v_ambient_out + lighting * totalShadow);
fragColor = vec4(finalColor, diffuseColor.a);
}
"""
}

text

protected val u_projViewTrans = register("u_projViewTrans")
protected val u_worldTrans = register("u_worldTrans")
protected val u_lightDirection = register("u_lightDirection")
protected val u_diffuseTexture = register("u_diffuseTexture")
protected val u_emissiveTexture = register("u_emissiveTexture")
protected val u_sunTransparency = register("u_sunTransparency")
protected val u_ambientLight = register("u_ambientLight")
protected val u_shininess = register("u_shininess")
protected val u_specularColor = register("u_specularColor")
protected val u_coronaStrength = register("u_coronaStrength")
protected val u_eruptionStrength = register("u_eruptionStrength")
protected val u_eruptionHeight = register("u_eruptionHeight")
protected val u_time = register("u_time")
protected val u_lightIntensity = register("u_lightIntensity")
protected val u_heightmapTexture = register("u_heightmapTexture")
protected val u_shadowIntensity = register("u_shadowIntensity")
protected val u_shadowMap = register("u_shadowMap")
protected val u_shadowMatrix = register("u_shadowMatrix")
protected val u_cameraPosition = register("u_cameraPosition")
protected val u_cameraFarPlane = register("u_cameraFarPlane")
protected val u_cameraNear = register("u_cameraNear") // <-- REGISTRIERUNG HINZUGEFÜGT
protected val u_shadowBias = register("u_shadowBias")
protected val u_shadowSoftness = register("u_shadowSoftness")
protected val u_shadowColor = register("u_shadowColor")
protected val u_contactHardening = register("u_contactHardening")
protected val u_pcfSize = register("u_pcfSize")
protected val u_depthScale = register("u_depthScale")
protected val u_depthOffset = register("u_depthOffset")

override fun init() {
    if (!initialized) {
        program = ShaderProgram(sunVertexShader, sunFragmentShader)
        if (!program.isCompiled) throw GdxRuntimeException("Shader compilation failed: ${program.log}")
        super.init(program, null)
        initialized = true
        Gdx.gl.glEnable(GL20.GL_DEPTH_TEST)
        Gdx.gl.glDepthFunc(GL20.GL_LESS)
    }
}

override fun canRender(renderable: Renderable): Boolean = renderable.material.has(TextureAttribute.Diffuse)
override fun compareTo(other: Shader): Int = 0

override fun begin(camera: Camera, context: RenderContext) {
    timeAccumulator += Gdx.graphics.deltaTime
    program.bind()
    set(u_projViewTrans, camera.combined)
    set(u_time, timeAccumulator)
    set(u_cameraPosition, realCameraPosition)

    // Kamera-Far-Plane korrekt setzen
    val farPlane = if (camera.far > 0f) camera.far else 1e30f
    set(u_cameraFarPlane, farPlane)
    set(u_cameraNear, camera.near) // <-- SETZEN DES NEUEN UNIFORMS

    set(u_depthScale, 0.9995f)
    set(u_depthOffset, 0.0005f)

    val ambient = environment[ColorAttribute.AmbientLight] as? ColorAttribute
    ambient?.let { set(u_ambientLight, it.color.r, it.color.g, it.color.b) } ?: set(u_ambientLight, 0.1f, 0.1f, 0.1f)

    val shininess = environment[FloatAttribute.Shininess] as? FloatAttribute
    shininess?.let { set(u_shininess, it.value) } ?: set(u_shininess, 32f)

    val specular = environment[ColorAttribute.Specular] as? ColorAttribute
    specular?.let { set(u_specularColor, it.color) } ?: set(u_specularColor, 0.8f, 0.8f, 0.8f, 1f)

    if (directionalLights.isNotEmpty()) {
        val dir = directionalLights[0].direction
        tmpLightDir.set(-dir.x, -dir.y, -dir.z).nor()
        set(u_lightDirection, tmpLightDir)
        set(u_lightIntensity, directionalLights[0].color.a)
    }

    context.setDepthTest(GL20.GL_LESS)
    context.setDepthMask(true)
}

override fun render(renderable: Renderable) {
    set(u_worldTrans, renderable.worldTransform)

    val sunTransparency = if (renderable.userData is Float && renderable.userData as Float > 0) 1.0f else 0.0f
    set(u_sunTransparency, sunTransparency)

    if (renderable.userData == "COMET") set(u_sunTransparency, 1.0f)

    renderable.material.get(CustomAttributes.SunCoronaStrengthAttribute.ID)?.let { attr ->
        set(u_coronaStrength, (attr as CustomAttributes.SunCoronaStrengthAttribute).value)
    } ?: set(u_coronaStrength, 20f)

    renderable.material.get(CustomAttributes.SunEruptionStrengthAttribute.ID)?.let { attr ->
        set(u_eruptionStrength, (attr as CustomAttributes.SunEruptionStrengthAttribute).value)
    } ?: set(u_eruptionStrength, 1f)

    renderable.material.get(CustomAttributes.SunEruptionHeightAttribute.ID)?.let { attr ->
        set(u_eruptionHeight, (attr as CustomAttributes.SunEruptionHeightAttribute).value)
    } ?: set(u_eruptionHeight, 1.0f)

    renderable.material.get(ShadowIntensityAttribute.ID)?.let { attr ->
        set(u_shadowIntensity, (attr as ShadowIntensityAttribute).value)
    } ?: set(u_shadowIntensity, 0.5f)

    renderable.material.get(TextureAttribute.Diffuse)?.let { texAttr ->
        val texture = (texAttr as TextureAttribute).textureDescription.texture
        texture?.bind(0)
        set(u_diffuseTexture, 0)
    }

    renderable.material.get(TextureAttribute.Emissive)?.let { texAttr ->
        val texture = (texAttr as TextureAttribute).textureDescription.texture
        texture?.bind(1)
        set(u_emissiveTexture, 1)
    }

    renderable.material.get(ShadowMapAttribute.ID)?.let { attr ->
        val shadowAttr = attr as ShadowMapAttribute
        shadowAttr.textureDescription.textureDescription.texture?.bind(3)
        set(u_shadowMap, 3)
        set(u_shadowMatrix, shadowAttr.matrix)
    }

    val heightmap = renderable.userData as? String
    if (heightmap != null) {
        val heightTexture = try {
            Texture(Gdx.files.internal(heightmap.replace(".png", "_height.png")))
        } catch (e: Exception) {
            null
        }
        heightTexture?.let {
            it.bind(2)
            set(u_heightmapTexture, 2)
        }
    }

    renderable.meshPart.render(program)
}
}

// ------------------ SHADOW INTENSITY ATTRIBUTE ------------------
class ShadowIntensityAttribute(value: Float) : FloatAttribute(Attribute.register("u_shadowIntensity"), value) {
companion object {
val ID: Long = register("u_shadowIntensity")
}

text

override fun copy(): ShadowIntensityAttribute {
    return ShadowIntensityAttribute(value)
}
}

// ------------------ SHADOW MAP ATTRIBUTE ------------------
class ShadowMapAttribute : Attribute {
val textureDescription: TextureAttribute
val matrix: Matrix4

text

constructor(texture: Texture, matrix: Matrix4) : super(ID) {
    textureDescription = TextureAttribute(TextureAttribute.Diffuse, texture)
    this.matrix = Matrix4(matrix)
}

override fun copy(): Attribute {
    return ShadowMapAttribute(textureDescription.textureDescription.texture, matrix)
}

override fun compareTo(other: Attribute): Int {
    if (other !is ShadowMapAttribute) {
        return (ID - other.type).toInt()
    }

    val tex1 = textureDescription.textureDescription.texture
    val tex2 = other.textureDescription.textureDescription.texture
    if (tex1 !== tex2) {
        return when {
            tex1 == null -> -1
            tex2 == null -> 1
            else -> tex1.hashCode() - tex2.hashCode()
        }
    }

    return compareMatrices(matrix, other.matrix)
}

private fun compareMatrices(a: Matrix4, b: Matrix4): Int {
    val epsilon = 0.0001f
    for (i in 0 until 16) {
        val diff: Float = a.`val`[i] - b.`val`[i]
        if (abs(diff) > epsilon) {
            return if (diff > 0) 1 else -1
        }
    }
    return 0
}

companion object {
    val ID: Long = register("ShadowMap")
}
}

// ------------------ SHADOW MAP GENERATOR (WITH INFINITE DEPTH) ------------------
class ShadowMapGenerator(val size: Int = 16384, private val scaleFactors: FloatArray) : Disposable {
val frameBuffer: FrameBuffer
val camera: OrthographicCamera
val renderer: ModelBatch
private val depthShaderProvider: DepthShaderProvider
val depthTexture: Texture

text

private val sceneBounds = BoundingBox()
private var boundsDirty = true

init {
    val fbb = com.badlogic.gdx.graphics.glutils.GLFrameBuffer.FrameBufferBuilder(size, size)
        .addColorTextureAttachment(GL30.GL_RGBA8, GL30.GL_RGBA, GL30.GL_UNSIGNED_BYTE)
        .addDepthTextureAttachment(GL30.GL_DEPTH_COMPONENT32F, GL30.GL_FLOAT)

    frameBuffer = fbb.build()
    depthTexture = frameBuffer.textureAttachments[1]

    camera = OrthographicCamera(500000000f, 500000000f).apply {
        near = 0.1f
        far = 1e30f
    }

    depthShaderProvider = DepthShaderProvider(scaleFactors)
    renderer = ModelBatch(depthShaderProvider)

    Gdx.app.log("ShadowMapGenerator", "Initialized with size $size")
}

fun invalidateBounds() {
    boundsDirty = true
}

fun render(directionalLight: DirectionalLight, instances: List<ModelInstance>, sunWorldPos: Vector3) {
    if (instances.isEmpty()) return

    frameBuffer.begin()
    Gdx.gl.glClearColor(1f, 1f, 1f, 1f)
    Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT or GL20.GL_DEPTH_BUFFER_BIT)
    Gdx.gl.glEnable(GL20.GL_DEPTH_TEST)
    Gdx.gl.glDepthFunc(GL20.GL_LESS)
    Gdx.gl.glDisable(GL20.GL_CULL_FACE)

    val lightDir = directionalLight.direction.nor()

    val lightDistance = 1e30f

    camera.position.set(sunWorldPos)
    camera.direction.set(lightDir)
    camera.up.set(Vector3.Y)

    val viewportSize = 2e18f
    camera.viewportWidth = viewportSize
    camera.viewportHeight = viewportSize
    camera.near = 0.1f
    camera.far = lightDistance
    camera.update()

    renderer.begin(camera)
    instances.forEach { renderer.render(it) }
    renderer.end()

    frameBuffer.end()
}

private fun calculateSceneBounds(instances: List<ModelInstance>, out: BoundingBox): BoundingBox {
    out.inf()
    val instanceBounds = BoundingBox()
    instances.forEach { instance ->
        instance.calculateBoundingBox(instanceBounds)
        out.ext(instanceBounds)
    }
    return out
}

override fun dispose() {
    depthTexture.dispose()
    frameBuffer.dispose()
    renderer.dispose()
    depthShaderProvider.dispose()
    Gdx.app.log("ShadowMapGenerator", "Disposed resources")
}

private class DepthShaderProvider(scaleFactors: FloatArray) : ShaderProvider {
    private val depthShader = DepthShader(scaleFactors)
