// ------------------ DEPTH SHADER (WITH STABLE LOG DEPTH) ------------------
class DepthShader(private val scaleFactors: FloatArray) : Shader {
private val program: ShaderProgram
private var u_projViewTransLoc: Int = -1
private var u_worldTransLoc: Int = -1
private var u_cameraFarLoc: Int = -1
private var u_cameraNearLoc: Int = -1
private var u_cameraPositionLoc: Int = -1
private var u_scaleFactorsLoc: Int = -1
private var u_infiniteDepthScaleLoc: Int = -1

text

companion object {
    const val vertexShader = """
        attribute vec4 a_position;
        attribute vec2 a_texCoord0;
        uniform mat4 u_projViewTrans;
        uniform mat4 u_worldTrans;
        uniform vec3 u_cameraPosition;
        varying vec3 v_worldPos;
        varying float v_cameraDistance;
        varying float v_logDistance;
        varying vec2 v_texCoords;

        void main() {
            vec4 worldPos = u_worldTrans * a_position;
            v_worldPos = worldPos.xyz;

            v_cameraDistance = length(worldPos.xyz - u_cameraPosition);
            v_logDistance = log(max(1.0, v_cameraDistance));

            v_texCoords = a_texCoord0;
            gl_Position = u_projViewTrans * worldPos;
        }
    """

    const val fragmentShader = """
        #extension GL_EXT_frag_depth : enable
        #ifdef GL_ES
        precision highp float;
        #endif

        varying vec3 v_worldPos;
        varying float v_cameraDistance;
        varying float v_logDistance;
        uniform float u_cameraFar;
        uniform float u_cameraNear;
        uniform float u_scaleFactors[4];
        uniform float u_infiniteDepthScale;

        void main() {
            float nearClip = max(u_cameraNear, 0.1);
            float farClip = max(u_cameraFar, 1e30);
            const float c = 1.0;
            float depthLog = (log(v_cameraDistance + c) - log(nearClip + c)) /
                             (log(farClip + c) - log(nearClip + c));
            depthLog = clamp(depthLog * 0.9995, 0.0005, 0.999999);

            vec3 encoded;
            encoded.r = fract(depthLog * 1024.0);
            encoded.g = fract(depthLog * 1048576.0);
            encoded.b = fract(depthLog * 1073741824.0);

            gl_FragDepth = depthLog;
            gl_FragColor = vec4(encoded, 1.0);
        }
    """
}

init {
    program = ShaderProgram(vertexShader, fragmentShader)
    if (!program.isCompiled) {
        Gdx.app.error("DepthShader", "Compilation failed: ${program.log}")
    } else {
        Gdx.app.log("DepthShader", "Multi-Scale Depth Shader compiled successfully")
    }

    u_projViewTransLoc = program.getUniformLocation("u_projViewTrans")
    u_worldTransLoc = program.getUniformLocation("u_worldTrans")
    u_cameraFarLoc = program.getUniformLocation("u_cameraFar")
    u_cameraNearLoc = program.getUniformLocation("u_cameraNear")
    u_cameraPositionLoc = program.getUniformLocation("u_cameraPosition")
    u_scaleFactorsLoc = program.getUniformLocation("u_scaleFactors")
    u_infiniteDepthScaleLoc = program.getUniformLocation("u_infiniteDepthScale")
}

override fun init() {}

override fun begin(camera: Camera?, context: RenderContext?) {
    program.begin()
    camera?.let {
        program.setUniformMatrix(u_projViewTransLoc, it.combined)
        val farVal = if (it.far > 0f) it.far else 1e30f
        program.setUniformf(u_cameraFarLoc, farVal)
        program.setUniformf(u_cameraNearLoc, maxOf(it.near, 0.1f))
        program.setUniformf(u_cameraPositionLoc, it.position.x, it.position.y, it.position.z)
        program.setUniform4fv(u_scaleFactorsLoc, scaleFactors, 0, 4)
        program.setUniformf(u_infiniteDepthScaleLoc, 1e-25f)
    }
}

override fun render(renderable: Renderable) {
    program.setUniformMatrix(u_worldTransLoc, renderable.worldTransform)
    renderable.meshPart.render(program)
}

override fun end() = program.end()
override fun compareTo(other: Shader) = 0
override fun canRender(renderable: Renderable) = true
override fun dispose() = program.dispose()
}

