// ------------------ PLANET (OPTIMIZED WITH HIGH PRECISION) ------------------
class Planet(
val radius: Double,
val orbitRadius: Double,
val orbitSpeed: Double,
val rotationSpeed: Double,
val textureData: PlanetTextureData,
initialOrbitAngle: Float = Random.nextFloat() * MathUtils.PI2
) {
val position_d = Vector3d()
var orbitAngle_d: Double = initialOrbitAngle.toDouble()
var selfRotation_d: Double = 0.1

text

val faceTransforms = mutableListOf<Matrix4>()
private val faces = mutableListOf<Mesh>()
val material = Material()
val renderables = mutableListOf<Renderable>()

init {
    createCubemap()
    setupMaterial()
    createRenderables()
}

private fun setupMaterial() {
    material.apply {
        set(TextureAttribute.createDiffuse(textureData.diffuse))
        textureData.blendTexture?.let {
            set(TextureAttribute(TextureAttribute.Bump, it))
            set(CustomAttributes.createBlendFactorAttribute(textureData.blendFactor))
        }
        textureData.emissiveTexture?.let {
            set(TextureAttribute.createEmissive(it))
            set(CustomAttributes.createEmissiveFactorAttribute(textureData.emissiveFactor))
        }
        set(ColorAttribute.createSpecular(0.8f, 0.8f, 0.8f, 1f))
        set(FloatAttribute.createShininess(32f))
        set(ShadowIntensityAttribute(0.5f))
    }
}

private fun createRenderables() {
    faces.forEachIndexed { index, mesh ->
        val renderable = Renderable().apply {
            meshPart.run {
                this.mesh = mesh
                offset = 0
                size = mesh.getNumIndices()
                primitiveType = GL20.GL_TRIANGLES
                update()
            }
            material = this@Planet.material
            worldTransform.set(faceTransforms[index])
            this.environment = null
            userData = CelestialInfo("PLANET", textureData.diffuseFile,
                textureData.diffuseFile.replace(".png", "_height.png"))
        }
        renderables.add(renderable)
    }
}

private fun createCubemap() {
    faces.clear()
    faceTransforms.clear()

    val size = 256
    val heightIntensity = 0.04f

    val faceNormals = listOf(
        Vector3(0f, 0f, 1f), Vector3(0f, 0f, -1f),
        Vector3(1f, 0f, 0f), Vector3(-1f, 0f, 0f),
        Vector3(0f, 1f, 0f), Vector3(0f, -1f, 0f)
    )

    faceNormals.forEach { normal ->
        faces.add(createCubemapFace(size, heightIntensity, normal))
        faceTransforms.add(Matrix4())
    }
}

private fun createCubemapFace(size: Int, heightIntensity: Float, normal: Vector3): Mesh {
    val vertices = ArrayList<Float>()
    val indices = ArrayList<Short>()

    val halfSize = size / 2
    val step = 1f / halfSize

    for (y in -halfSize..halfSize) {
        for (x in -halfSize..halfSize) {
            val u = ((x + halfSize) / size.toFloat()).coerceIn(0.001f, 0.999f)
            val v = ((y + halfSize) / size.toFloat()).coerceIn(0.001f, 0.999f)

            val localPos = Vector3(x * step, y * step, 1f)
            val worldPos = when {
                normal.z > 0 -> localPos
                normal.z < 0 -> localPos.rotate(Vector3.Y, 180f)
                normal.x > 0 -> localPos.rotate(Vector3.Y, 90f)
                normal.x < 0 -> localPos.rotate(Vector3.Y, -90f)
                normal.y > 0 -> localPos.rotate(Vector3.X, -90f)
                else -> localPos.rotate(Vector3.X, 90f)
            }

            worldPos.nor()
            val heightValue = getHeightFromTexture(worldPos)

            val finalPos = worldPos.cpy().scl(1.0f + heightIntensity * (heightValue - 0.5f))

            vertices.addAll(listOf(
                finalPos.x, finalPos.y, finalPos.z,
                worldPos.x, worldPos.y, worldPos.z,
                u, v
            ))
        }
    }

    for (y in 0 until size) {
        for (x in 0 until size) {
            val first = (y * (size + 1)) + x
            val second = first + size + 1

            indices.addAll(listOf(
                first.toShort(), second.toShort(), (first + 1).toShort(),
                (first + 1).toShort(), second.toShort(), (second + 1).toShort()
            ))
        }
    }

    return Mesh(true, vertices.size / 8, indices.size,
        VertexAttribute.Position(),
        VertexAttribute.Normal(),
        VertexAttribute.TexCoords(0)).apply {
        setVertices(vertices.toFloatArray())
        setIndices(indices.toShortArray())
    }
}

private fun getHeightFromTexture(position: Vector3): Float {
    val absX = abs(position.x)
    val absY = abs(position.y)
    val absZ = abs(position.z)

    val u: Float
    val v: Float

    when {
        absX >= absY && absX >= absZ -> {
            u = if (position.x > 0) -position.z else position.z
            v = position.y
        }
        absY >= absX && absY >= absZ -> {
            u = position.x
            v = if (position.y > 0) position.z else -position.z
        }
        else -> {
            u = if (position.z > 0) position.x else -position.x
            v = position.y
        }
    }

    val texU = (u / 2f) + 0.5f
    val texV = (v / 2f) + 0.5f

    return textureData.heightmap?.let { heightmap ->
        val x = (texU * (heightmap.width - 1)).toInt().coerceIn(0, heightmap.width - 1)
        val y = ((1 - texV) * (heightmap.height - 1)).toInt().coerceIn(0, heightmap.height - 1)
        (heightmap.getPixel(x, y) and 0xFF) / 255f
    } ?: 0.5f
}

fun update(delta: Double, sunPosition_d: Vector3d, worldOffset_d: Vector3d) {
    orbitAngle_d += orbitSpeed * delta
    selfRotation_d += rotationSpeed * delta

    position_d.set(
        sunPosition_d.x + cos(orbitAngle_d) * orbitRadius,
        sunPosition_d.y,
        sunPosition_d.z + sin(orbitAngle_d) * orbitRadius
    )

    position_d.add(worldOffset_d)
}

fun dispose() {
    faces.forEach { it.dispose() }
    faceTransforms.clear()
}
}

