private fun updateShadowMatrix() {
    val light = lightManager.get("BossLight") ?: return
    val lightDirection = light.direction.cpy().nor()
    val sunWorldPos = sunPosition_d.toVector3().add(totalWorldOffset_d.toVector3())
    shadowMapGenerator.camera.apply {
        position.set(sunWorldPos)
        direction.set(lightDirection)
        up.set(Vector3.Y)
        val viewRadius = 2e18f // A huge radius for the entire scene
        viewportWidth = viewRadius * 2f
        viewportHeight = viewRadius * 2f
        near = shadowNearPlane
        far = shadowFarPlane
        update()
    }
    shadowMatrix.set(shadowMapGenerator.camera.combined)
    shadowMatrix.translate(totalWorldOffset_d.toVector3().scl(-1f))
}

private fun updateCameras() {
    cameraFar.apply {
        position.set(camera.position)
        direction.set(camera.direction)
        up.set(camera.up)
        update()
    }
}

private fun updateRenderPositions() {
    shadowMatrix.translate(totalWorldOffset_d.toVector3())

    relativePosition_v3.set(
        (sunPosition_d.x - cameraPosition_d.x).toFloat(),
        (sunPosition_d.y - cameraPosition_d.y).toFloat(),
        (sunPosition_d.z - cameraPosition_d.z).toFloat()
    )
    sunInstance.transform.setToTranslation(relativePosition_v3)
    sunInstance.transform.rotate(Vector3.Y, (sunSelfRotation_d * MathUtils.radiansToDegrees).toFloat())
    sunInstance.transform.scale(sunRadius, sunRadius, sunRadius)

    planets.forEach { planet ->
        relativePosition_v3.set(
            (planet.position_d.x - cameraPosition_d.x).toFloat(),
            (planet.position_d.y - cameraPosition_d.y).toFloat(),
            (planet.position_d.z - cameraPosition_d.z).toFloat()
        )

        val radiusF = planet.radius.toFloat()
        planet.faceTransforms.forEach { transform ->
            transform.setToTranslation(relativePosition_v3)
            transform.rotate(Vector3.Y, (planet.selfRotation_d * MathUtils.radiansToDegrees).toFloat())
            transform.scale(radiusF, radiusF, radiusF)
        }

        planet.renderables.forEachIndexed { index, renderable ->
            renderable.worldTransform.set(planet.faceTransforms[index])
        }
    }

    val cometX = sunPosition_d.x + cos(cometOrbitAngle_d) * cometOrbitRadius_d
    val cometZ = sunPosition_d.z + sin(cometOrbitAngle_d) * cometOrbitRadius_d
    relativePosition_v3.set(
        (cometX - cameraPosition_d.x).toFloat(),
        (sunPosition_d.y - cameraPosition_d.y).toFloat(),
        (cometZ - cameraPosition_d.z).toFloat()
    )
    cometInstance.transform.setToTranslation(relativePosition_v3)
    cometInstance.transform.rotate(Vector3.Y, (cometSelfRotation_d * MathUtils.radiansToDegrees).toFloat())

    val moonX = sunPosition_d.x + cos(sunMoonOrbitAngle_d) * sunMoonOrbitRadius_d
    val moonZ = sunPosition_d.z + sin(sunMoonOrbitAngle_d) * sunMoonOrbitRadius_d
    relativePosition_v3.set(
        (moonX - cameraPosition_d.x).toFloat(),
        (sunPosition_d.y - cameraPosition_d.y).toFloat(),
        (moonZ - cameraPosition_d.z).toFloat()
    )
    sunMoonInstance.transform.setToTranslation(relativePosition_v3)
    sunMoonInstance.transform.rotate(Vector3.Y, (sunMoonSelfRotation_d * MathUtils.radiansToDegrees).toFloat())
}

