override fun create() {
    Gdx.gl.glDepthRangef(0.1f, 1.0f)
    Gdx.gl.glClearDepthf(1.0f)
    if (Gdx.gl30 == null) {
        Gdx.app.error("ShadowMapping", "OpenGL 3.0 wird nicht unterstützt!")
        Gdx.app.exit()
        return
    }

    Gdx.gl.glEnable(GL20.GL_CULL_FACE)
    Gdx.gl.glCullFace(GL20.GL_BACK)
    Gdx.gl.glDepthFunc(GL20.GL_LESS)

    if (Gdx.graphics.supportsExtension("GL_EXT_frag_depth")) {
        Gdx.app.log("DepthShader", "GL_EXT_frag_depth wird unterstützt")
    } else {
        Gdx.app.log("DepthShader", "GL_EXT_frag_depth wird NICHT unterstützt - wir verwenden trotzdem stabilisierte gl_FragDepth")
    }

    debugBatch = SpriteBatch()
    debugFont = BitmapFont()

    applyDepthMapQuality(depthMapQuality)

    loadTextures()
    createModels()

    galaxieManager = GalaxieManager().apply { generiereGalaxien(GalaxieAnzahl) }
    dynamicUniverse = DynamicUniverse(galaxieManager)

    environment = Environment().apply {
        set(ColorAttribute(ColorAttribute.AmbientLight, ambientLightIntensity, ambientLightIntensity, ambientLightIntensity, 1f))
        set(FloatAttribute.createShininess(glassShieldShininess))
        set(ColorAttribute.createSpecular(glassShieldSpecular.r, glassShieldSpecular.g, glassShieldSpecular.b, glassShieldSpecular.a))
    }

    lightManager.apply {
        add("BossLight", NamedDirectionalLight("BossLight", Color(1f, 1f, 1f, directionalLightIntensity), Vector3(-1f, -0.5f, -0.5f).nor()))
        add("BossLight2", NamedDirectionalLight("BossLight2", Color(1f, 0.8f, 0.5f, directionalLightIntensity * 0.8f), Vector3(0f, -1f, -0.5f).nor()))
        add("BossLight3", NamedDirectionalLight("BossLight3", Color(0.5f, 0.5f, 1f, directionalLightIntensity * 0.7f), Vector3(1f, -0.3f, -0.7f).nor()))
        addToEnvironment(environment)
    }

    shadowMapGenerator = ShadowMapGenerator(shadowMapSize, depthScaleFactors).apply {
        camera.near = shadowNearPlane
        camera.far = shadowFarPlane
    }

    rotaShaderProvider = RotaShaderProvider(lightManager.lights.values.toList(), environment, realCameraPositionForShader)
    modelBatch = ModelBatch(rotaShaderProvider)

    ladeAktuelleGalaxie()

    noiseGenerator = NoiseTextureGenerator().setSize(2048, 2048).setNoiseType(NoiseTextureGenerator.NoiseType.SIMPLEX).setOctaves(6).setPersistence(0.5f).setSeamlessTiling(true)

    if (generateNoiseTexture) generateAndSaveNoiseTextures()

    initGlassShield()

    osd = OSD().apply {
        minSafeDistance = 50000f
        maxHeatDistance = 200000f
        maxHullTemperature = 2000f
    }
    navCircleRenderer = ShapeRenderer()
    fogBatch = SpriteBatch()

    camera = PerspectiveCamera(cameraFOV, Gdx.graphics.width.toFloat(), Gdx.graphics.height.toFloat()).apply {
        position.set(Vector3.Zero)
        lookAt(0f, 0f, -1f)
        near = 0.1f
        far = nearFarSplitDistance
        update()
    }

    cameraFar = PerspectiveCamera(cameraFOV, Gdx.graphics.width.toFloat(), Gdx.graphics.height.toFloat()).apply {
        position.set(Vector3.Zero)
        lookAt(0f, 0f, -1f)
        near = nearFarSplitDistance
        far = 1e30f
        update()
    }

    fogSettings.forEach { setting ->
        val fog = FogEffect(fogColor, fogParticleCount, fogWindForce, fogParticleLifetimeMin, fogParticleLifetimeMax)
        fogPositions.add(setting.position)
        particleManager.addParticleSystem(fog)
    }

    inputController = GameInputController(camera, this)
    Gdx.input.inputProcessor = inputController
    lastTime = System.currentTimeMillis()

    if (debugEnabled) {
        lightManager.debugPrint()
    }
}

private fun applyDepthMapQuality(quality: Int) {
    val config = depthMapQualities[quality] ?: return
    shadowMapSize = config.size
    shadowBias = config.bias
    shadowIntensity = config.intensity
    shadowBlurEnabled = config.blurEnabled
    shadowBlurRadius = config.blurRadius
}

fun setShadowQuality(quality: Int) {
    depthMapQuality = quality.coerceIn(0, 3)
    applyDepthMapQuality(depthMapQuality)
    recreateShadowMap()
}

fun setShadowIntensity(intensity: Float) {
    shadowIntensity = intensity.coerceIn(0f, 1f)
    updateAllMaterials()
}

fun setShadowSoftness(softness: Float) {
    shadowSoftness = softness.coerceIn(0.1f, 5f)
}

fun setShadowBias(bias: Float) {
    shadowBias = bias.coerceIn(0.001f, 0.1f)
}

fun toggleShadowBlur(enabled: Boolean) {
    shadowBlurEnabled = enabled
