    sunModel = modelBuilder.createSphere(sunRadius, sunRadius, sunRadius, 64, 64, Material().apply {
        set(TextureAttribute.createDiffuse(sunTextureData.diffuse))
        sunTextureData.blendTexture?.let {
            set(TextureAttribute(TextureAttribute.Bump, it))
            set(CustomAttributes.createBlendFactorAttribute(sunTextureData.blendFactor))
        }
        sunTextureData.emissiveTexture?.let {
            set(TextureAttribute.createEmissive(it))
            set(CustomAttributes.createEmissiveFactorAttribute(sunTextureData.emissiveFactor))
        }
        set(CustomAttributes.createSunTransparencyAttribute(1.0f))
        set(CustomAttributes.createSunCoronaStrengthAttribute(coronaStrength))
        set(CustomAttributes.createSunEruptionStrengthAttribute(eruptionStrength))
        set(CustomAttributes.createSunEruptionHeightAttribute(eruptionHeight))
        set(ColorAttribute.createSpecular(1f, 0.8f, 0.5f, 1f))
        set(FloatAttribute.createShininess(128f))
    }, (VertexAttributes.Usage.Position or VertexAttributes.Usage.Normal or VertexAttributes.Usage.TextureCoordinates).toLong())

    cometModel = modelBuilder.createSphere(cometRadius, cometRadius, cometRadius, 32, 32, Material().apply {
        set(TextureAttribute.createDiffuse(cometTextureData.diffuse))
        set(ColorAttribute.createSpecular(0.3f, 0.3f, 0.3f, 1f))
        set(FloatAttribute.createShininess(16f))
    }, (VertexAttributes.Usage.Position or VertexAttributes.Usage.Normal or VertexAttributes.Usage.TextureCoordinates).toLong())

    sunMoonModel = modelBuilder.createSphere(moonRadius, moonRadius, moonRadius, 32, 32, Material().apply {
        set(TextureAttribute.createDiffuse(cometTextureData.diffuse))
        set(ColorAttribute.createSpecular(0.3f, 0.3f, 0.3f, 1f))
        set(FloatAttribute.createShininess(16f))
    }, (VertexAttributes.Usage.Position or VertexAttributes.Usage.Normal or VertexAttributes.Usage.TextureCoordinates).toLong())

    groundModel = modelBuilder.createBox(2000f, 1f, 2000f, Material().apply {
        set(TextureAttribute.createDiffuse(groundTexture))
        set(ColorAttribute.createSpecular(0.2f, 0.2f, 0.2f, 1f))
        set(FloatAttribute.createShininess(8f))
    }, (VertexAttributes.Usage.Position or VertexAttributes.Usage.Normal or VertexAttributes.Usage.TextureCoordinates).toLong())

    sunInstance = ModelInstance(sunModel).apply {
        userData = CelestialInfo("SUN", sunTextureData.diffuseFile, null, "assets/sun_blend.png", "assets/sun_emissive.png")
    }

    cometInstance = ModelInstance(cometModel).apply {
        userData = CelestialInfo("COMET", cometTextureData.diffuseFile, null)
    }

    sunMoonInstance = ModelInstance(sunMoonModel).apply {
        userData = CelestialInfo("SUN_MOON", cometTextureData.diffuseFile, null)
    }

    groundInstance = ModelInstance(groundModel, 0f, -5f, 0f)
