private fun ladeAktuelleGalaxie() {
    sternensysteme.clear()
    val galaxie = galaxieManager.getGalaxie(aktuelleGalaxieIndex) ?: return
    for (i in 0 until galaxie.sonnenAnzahl) {
        galaxieManager.generiereSternensystem(aktuelleGalaxieIndex, i)?.let { sternensysteme.add(it) }
    }
    if (sternensysteme.isNotEmpty()) ladeSternensystem(0)
}

private fun ladeSternensystem(index: Int) {
    val sternensystem = sternensysteme.getOrNull(index) ?: return
    println("Lade Sternensystem $index mit ${sternensystem.planeten.size} Planeten")

    sunPosition_d.set(sternensystem.position)
    sunRadius = sternensystem.sonnenRadius

    planets.forEach { it.dispose() }
    planets.clear()

    val specificTexture: PlanetTextureData? = if (startPlanet.equals("planet_x", ignoreCase = true)) {
        null
    } else {
        planetTextures.find { it.diffuseFile.contains(startPlanet, ignoreCase = true) }
    }

    sternensystem.planeten.forEach { planetDaten ->
        val textureToUse = specificTexture ?: planetTextures.random()

        val planet = Planet(
            radius = planetDaten.radius.toDouble(),
            orbitRadius = planetDaten.orbitRadius.toDouble(),
            orbitSpeed = planetDaten.orbitSpeed.toDouble(),
            rotationSpeed = planetDaten.rotationSpeed.toDouble(),
            textureData = textureToUse
        )
        planets.add(planet)

        val lightName = "PlanetLight_${planet.hashCode()}"
        val tempPlanetPosV3 = planet.position_d.toVector3()
        val tempSunPosV3 = sunPosition_d.toVector3()
        val lightDirection = tempSunPosV3.sub(tempPlanetPosV3).nor()
        val planetLight = NamedDirectionalLight(lightName, Color.WHITE, lightDirection)
        planetLights.add(planetLight)
        lightManager.add(lightName, planetLight)
    }

    lightManager.addToEnvironment(environment)
    shadowMapGenerator.invalidateBounds()
}

