private fun initGlassShield() {
    val vertexShader = """
        attribute vec4 a_position;
        attribute vec4 a_color;
        attribute vec2 a_texCoord0;
        uniform mat4 u_projTrans;
        varying vec4 v_color;
        varying vec2 v_texCoords;
        void main() {
            v_color = a_color;
            v_texCoords = a_texCoord0;
            gl_Position = u_projTrans * a_position;
        }
    """
    val fragmentShader = """
        #ifdef GL_ES
        precision mediump float;
        #endif
        varying vec4 v_color;
        varying vec2 v_texCoords;
        uniform sampler2D u_texture;
        uniform float u_shininess;
        uniform vec4 u_specularColor;
        void main() {
            vec4 texColor = texture2D(u_texture, v_texCoords);
            vec2 screenPos = gl_FragCoord.xy / vec2(800.0, 600.0);
            float spec = pow(max(0.0, dot(normalize(vec3(screenPos - 0.5, 1.0)), normalize(vec3(0.0, 0.0, 1.0)))), u_shininess);
            vec3 specular = u_specularColor.rgb * spec;
            gl_FragColor = vec4(texColor.rgb + specular, texColor.a * v_color.a);
        }
    """
    glassBatch = SpriteBatch()
    glassBatch.shader = ShaderProgram(vertexShader, fragmentShader)

    glassTexture = try {
        Texture(Gdx.files.internal(glassShieldTextureName)).apply {
            setFilter(Texture.TextureFilter.Linear, Texture.TextureFilter.Linear)
            setWrap(Texture.TextureWrap.ClampToEdge, Texture.TextureWrap.ClampToEdge)
        }
    } catch (e: Exception) {
        Gdx.app.error("GLASSHIELD", "Error loading texture, creating debug texture", e)
        val pixmap = Pixmap(512, 512, Pixmap.Format.RGBA8888).apply {
            setColor(Color.WHITE); fill()
            setColor(Color.LIGHT_GRAY)
            for (y in 0 until 512 step 64) for (x in 0 until 512 step 64) if ((x + y) % 128 == 0) fillRectangle(x, y, 64, 64)
            setColor(Color.RED)
            drawLine(0, 0, 512, 512)
            drawLine(512, 0, 0, 512)
        }
        Texture(pixmap).also { pixmap.dispose() }.apply { setFilter(Texture.TextureFilter.Linear, Texture.TextureFilter.Linear) }
    }

    glassSprite = Sprite(glassTexture).apply {
        setColor(1f, 1f, 1f, calculateCurrentTransparency())
        setSize(Gdx.graphics.width.toFloat(), Gdx.graphics.height.toFloat())
        setPosition(0f, 0f)
    }
}

private fun calculateCurrentTransparency(): Float {
    val stepSize = (glassShieldMaxVisibility - glassShieldMinVisibility) / (glassShieldSteps - 1)
    return glassShieldMinVisibility + (glassShieldCurrentStep * stepSize)
}

private fun updateGlassShieldTransparency() {
    glassSprite.setColor(1f, 1f, 1f, calculateCurrentTransparency())
}

private fun updateFogEffects(delta: Float) {
    fogPositions.forEachIndexed { index, pos ->
        pos.y += MathUtils.random(-0.05f, 0.05f)
        pos.x += MathUtils.random(-0.1f, 0.1f)
        pos.z += MathUtils.random(-0.1f, 0.1f)
    }
    particleManager.updateAll(delta)
}

private fun calculateSunVisibility(): Float {
    val sunDirection = sunPosition_d.toVector3(tempVec3).sub(cameraPosition_d.toVector3()).nor()
    val dotProduct = sunDirection.dot(camera.direction)
    return when {
        dotProduct > 0.9f -> 1.0f
        dotProduct > 0.7f -> 0.8f
        dotProduct > 0.5f -> 0.6f
        dotProduct > 0.3f -> 0.4f
        dotProduct > 0.1f -> 0.2f
        else -> 0f
    }
}

private fun updateEinstrahlung() {
    val visibility = calculateSunVisibility()
    einstrahlung = visibility
    val targetStep = (visibility * (glassShieldSteps - 1)).toInt()
    if (glassShieldCurrentStep < targetStep) glassShieldCurrentStep = minOf(glassShieldCurrentStep + 1, targetStep)
    else if (glassShieldCurrentStep > targetStep) glassShieldCurrentStep = maxOf(glassShieldCurrentStep - 1, targetStep)
    updateGlassShieldTransparency()
}

private fun renderGlassShield() {
    Gdx.gl.glEnable(GL20.GL_BLEND)
    Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA)
    Gdx.gl.glDepthMask(false)
    glassBatch.projectionMatrix = Matrix4().setToOrtho2D(0f, 0f, Gdx.graphics.width.toFloat(), Gdx.graphics.height.toFloat())
    glassBatch.begin()
    glassSprite.draw(glassBatch)
    glassBatch.end()
    Gdx.gl.glDepthMask(true)
    Gdx.gl.glDisable(GL20.GL_BLEND)
}

