private fun updateSunEffects() {
    coronaStrength = 0.7f + 0.1f * MathUtils.sin(timeAccumulator * 0.3f)
    eruptionStrength = 0.5f + 0.2f * MathUtils.sin(timeAccumulator * 0.7f)
    eruptionHeight = 0.5f + 0.5f * MathUtils.sin(timeAccumulator * 0.2f)
}

private fun updateCelestialBodies(delta: Float) {
    val delta_d = delta.toDouble()

    sunSelfRotation_d += sunRotationSpeed_d * delta_d * sunRotationDirection
    sunMoonSelfRotation_d += sunMoonRotationSpeed_d * delta_d * sunMoonRotationDirection
    cometSelfRotation_d += 0.1 * delta_d
    cometOrbitAngle_d += cometOrbitSpeed_d * delta_d
    sunMoonOrbitAngle_d += sunMoonOrbitSpeed_d * delta_d

    planets.forEach { it.update(delta_d, sunPosition_d, totalWorldOffset_d) }
}

override fun render() {
    frames++
    if (System.currentTimeMillis() - lastTime >= 1000) {
        fps = frames
        frames = 0
        lastTime = System.currentTimeMillis()
    }

    val rawDelta = Gdx.graphics.deltaTime
    val delta = Math.min(rawDelta, 1/30f) * deltaTimeMultiplier
    timeAccumulator += delta

    inputController.update(delta)
    updateFloatingOrigin()
    updateCelestialBodies(delta)
    updateCameras()
    updateShadowMatrix()
    updateRenderPositions()
    updateLightDirection()
    dynamicUniverse.update(cameraPosition_d.toVector3(tempVec3))
    updateEinstrahlung()
    environment.set(ColorAttribute(ColorAttribute.AmbientLight, ambientLightIntensity, ambientLightIntensity, ambientLightIntensity, 1f))

    val firstPlanetPos = if (planets.isNotEmpty()) planets.first().position_d.toVector3(tempVec3) else Vector3.Zero
    val celestialBodies = listOf(
        OSD.CelestialBody(firstPlanetPos, "PLANET", planetRadius_d.toFloat()),
        OSD.CelestialBody(cometInstance.transform.getTranslation(Vector3()), "COMET", cometRadius),
        OSD.CelestialBody(sunMoonInstance.transform.getTranslation(Vector3()), "MOON", moonRadius),
        OSD.CelestialBody(sunPosition_d.toVector3(), "STAR", sunRadius)
    )
    osd.update(delta, cameraPosition_d.toVector3(), celestialBodies, osd.currentSpeed)

    ScreenUtils.clear(0f, 0f, 0f, 1f, true)

    renderSceneFar()
    renderSceneNear()

    Gdx.gl.glEnable(GL20.GL_BLEND)
    Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA)
    fogBatch.begin()
    updateFogEffects(delta)
    particleManager.renderAll(fogBatch)
    fogBatch.end()
    Gdx.gl.glDisable(GL20.GL_BLEND)

    renderGlassShield()
    renderUI()
    renderShadowMapDebug()

    if (debugEnabled) {
        renderDebugInfo()
    }
}

private fun renderSceneFar() {
    realCameraPositionForShader.set(cameraPosition_d.toVector3())
    cameraFar.position.set(0f, 0f, 0f)
    cameraFar.update()

    modelBatch.begin(cameraFar)

    sunInstance.userData = 1.0f
    modelBatch.render(sunInstance, environment)

    planets.forEach { planet ->
        val distance = getPlanetRenderDistance(planet)
        val farBoundary = nearFarSplitDistance + planet.radius.toFloat()
        if (distance > farBoundary) {
            planet.renderables.forEach { renderable ->
                modelBatch.render(renderable)
            }
        }
    }
    modelBatch.end()
}

private fun renderSceneNear() {
    Gdx.gl.glClear(GL20.GL_DEPTH_BUFFER_BIT)
    realCameraPositionForShader.set(cameraPosition_d.toVector3())
    camera.position.set(0f, 0f, 0f)
    camera.update()

    modelBatch.begin(camera)

    planets.forEach { planet ->
        val distance = getPlanetRenderDistance(planet)
        val nearBoundary = nearFarSplitDistance + planet.radius.toFloat()
        if (distance <= nearBoundary) {
            planet.renderables.forEach { renderable ->
                val oldRadius = renderable.meshPart.radius
                renderable.meshPart.radius = -1f

                modelBatch.render(renderable)

                renderable.meshPart.radius = oldRadius
            }
        }
    }

    cometInstance.userData = CelestialInfo("COMET", cometTextureData.diffuseFile, null)
    modelBatch.render(cometInstance, environment)
    sunMoonInstance.userData = 0.0f
    modelBatch.render(sunMoonInstance, environment)

    modelBatch.end()
}

