        return
    }

    Gdx.gl.glEnable(GL20.GL_CULL_FACE)
    Gdx.gl.glCullFace(GL20.GL_BACK)
    Gdx.gl.glDepthFunc(GL20.GL_LESS)

    if (Gdx.graphics.supportsExtension("GL_EXT_frag_depth")) {
        Gdx.app.log("DepthShader", "GL_EXT_frag_depth wird unterstützt")
    } else {
        Gdx.app.log("DepthShader", "GL_EXT_frag_depth wird NICHT unterstützt - wir verwenden trotzdem stabilisierte gl_FragDepth")
