        set(ColorAttribute.createSpecular(glassShieldSpecular.r, glassShieldSpecular.g, glassShieldSpecular.b, glassShieldSpecular.a))
    }

    lightManager.apply {
        add("BossLight", NamedDirectionalLight("BossLight", Color(1f, 1f, 1f, directionalLightIntensity), Vector3(-1f, -0.5f, -0.5f).nor()))
        add("BossLight2", NamedDirectionalLight("BossLight2", Color(1f, 0.8f, 0.5f, directionalLightIntensity * 0.8f), Vector3(0f, -1f, -0.5f).nor()))
        add("BossLight3", NamedDirectionalLight("BossLight3", Color(0.5f, 0.5f, 1f, directionalLightIntensity * 0.7f), Vector3(1f, -0.3f, -0.7f).nor()))
        addToEnvironment(environment)
