private fun loadTextures() {
    fun createFallbackTexture(color: Color, name: String): PlanetTextureData {
        val pixmap = Pixmap(128, 128, Pixmap.Format.RGBA8888).apply { setColor(color); fill() }
        val texture = Texture(pixmap).also { pixmap.dispose() }.apply { setFilter(Texture.TextureFilter.Linear, Texture.TextureFilter.Linear) }
        return PlanetTextureData(texture, "fallback_$name", null)
    }

    try {
        val planetFiles = Gdx.files.internal("assets").list().filter { it.nameWithoutExtension().matches(Regex("planet_\\d+")) }
        planetTextures = planetFiles.map { file ->
            val planetFile = "assets/${file.name()}"
            val planetTexture = Texture(Gdx.files.internal(planetFile), true).apply {
                setFilter(Texture.TextureFilter.MipMapLinearLinear, Texture.TextureFilter.Linear)
                setWrap(Texture.TextureWrap.Repeat, Texture.TextureWrap.Repeat)
            }
            val planetHeightmap = try { Pixmap(Gdx.files.internal(planetFile.replace(".png", "_height.png"))) } catch (e: Exception) { null }
            PlanetTextureData(
                planetTexture,
                planetFile,
                planetHeightmap,
                emissiveTexture = Texture(Gdx.files.internal("assets/planet_emissive.png")),
                emissiveFactor = 0.5f
            )
        }
        if(planetTextures.isEmpty()){
            Gdx.app.error("TEXTURE", "No planet textures found! Using fallback.")
            planetTextures = listOf(createFallbackTexture(Color.BLUE, "planet"))
        }

        fun getRandomTextureFile(baseName: String): String {
            val files = Gdx.files.internal("assets").list().filter { it.nameWithoutExtension().matches(Regex("${baseName}_\\d+")) }
            return if (files.isNotEmpty()) "assets/${files.random().name()}" else "assets/${baseName}_1.png"
        }

        cometTextureData = PlanetTextureData(
            Texture(Gdx.files.internal(getRandomTextureFile("comet")), true).apply {
                setFilter(Texture.TextureFilter.MipMapLinearLinear, Texture.TextureFilter.Linear)
                setWrap(Texture.TextureWrap.Repeat, Texture.TextureWrap.Repeat)
            },
            "comet",
            null
        )

        sunTextureData = PlanetTextureData(
            Texture(Gdx.files.internal(getRandomTextureFile("sun")), true).apply {
                setFilter(Texture.TextureFilter.MipMapLinearLinear, Texture.TextureFilter.Linear)
                setWrap(Texture.TextureWrap.Repeat, Texture.TextureWrap.Repeat)
            },
            "sun",
            null,
            blendTexture = Texture(Gdx.files.internal("assets/sun_blend.png")).apply {
                setFilter(Texture.TextureFilter.MipMapLinearLinear, Texture.TextureFilter.Linear)
                setWrap(Texture.TextureWrap.Repeat, Texture.TextureWrap.Repeat)
            },
            blendFactor = blend,
            emissiveTexture = Texture(Gdx.files.internal("assets/sun_emissive.png")),
            emissiveFactor = emissive
        )

        groundTexture = Texture(Gdx.files.internal("assets/ground.png"), true).apply {
            setFilter(Texture.TextureFilter.MipMapLinearLinear, Texture.TextureFilter.Linear)
            setWrap(Texture.TextureWrap.Repeat, Texture.TextureWrap.Repeat)
        }
    } catch (e: Exception) {
        Gdx.app.error("TEXTURE", "Fehler beim Laden von Texturen", e)
        if (!::planetTextures.isInitialized || planetTextures.isEmpty()) {
            planetTextures = listOf(createFallbackTexture(Color.BLUE, "planet"))
        }
        cometTextureData = createFallbackTexture(Color.GRAY, "comet")
        sunTextureData = createFallbackTexture(Color.YELLOW, "sun")
        groundTexture = createFallbackTexture(Color.GRAY, "ground").diffuse
    }
}

