            set(TextureAttribute(TextureAttribute.Bump, it))
            set(CustomAttributes.createBlendFactorAttribute(sunTextureData.blendFactor))
        }
        sunTextureData.emissiveTexture?.let {
            set(TextureAttribute.createEmissive(it))
            set(CustomAttributes.createEmissiveFactorAttribute(sunTextureData.emissiveFactor))
