        set(CustomAttributes.createSunTransparencyAttribute(1.0f))
        set(CustomAttributes.createSunCoronaStrengthAttribute(coronaStrength))
        set(CustomAttributes.createSunEruptionStrengthAttribute(eruptionStrength))
        set(CustomAttributes.createSunEruptionHeightAttribute(eruptionHeight))
        set(ColorAttribute.createSpecular(1f, 0.8f, 0.5f, 1f))
