private fun updateFloatingOrigin() {
    val distanceFromOrigin = cameraPosition_d.len()
    if (distanceFromOrigin > floatingOriginThreshold_d && !isTransitioning) {
        isTransitioning = true
        floatingOriginTransition_d.set(cameraPosition_d)
        previousWorldOffset_d.set(totalWorldOffset_d)
    }

    if (isTransitioning) {
        val shiftX = floatingOriginTransition_d.x * -transitionSpeed_d
        val shiftY = floatingOriginTransition_d.y * -transitionSpeed_d
        val shiftZ = floatingOriginTransition_d.z * -transitionSpeed_d

        cameraPosition_d.x += shiftX
        cameraPosition_d.y += shiftY
        cameraPosition_d.z += shiftZ

        shiftWorldObjectsRelative_d(shiftX, shiftY, shiftZ)

        floatingOriginTransition_d.x += shiftX
        floatingOriginTransition_d.y += shiftY
        floatingOriginTransition_d.z += shiftZ

        if (floatingOriginTransition_d.len() < floatingOriginThreshold_d * 0.1) {
            isTransitioning = false
            totalWorldOffset_d.add(previousWorldOffset_d)
            floatingOriginTransition_d.set(0.0, 0.0, 0.0)
        }
    }
}

fun shiftWorldObjects_d(offsetX: Double, offsetY: Double, offsetZ: Double) {
    sunPosition_d.x += offsetX
    sunPosition_d.y += offsetY
    sunPosition_d.z += offsetZ

    planets.forEach { planet ->
        planet.position_d.x += offsetX
        planet.position_d.y += offsetY
        planet.position_d.z += offsetZ
    }
}

private fun shiftWorldObjectsRelative_d(offsetX: Double, offsetY: Double, offsetZ: Double) {
    sunPosition_d.x += offsetX
    sunPosition_d.y += offsetY
    sunPosition_d.z += offsetZ

    planets.forEach { planet ->
        planet.position_d.x += offsetX
        planet.position_d.y += offsetY
        planet.position_d.z += offsetZ
    }
}

