        if score >= MIN_SCORE_THRESHOLD {
            self.filtered.push((i, score));
        }
    }
}
```

## 4. Incremental Filtering

If users type character by character, you can optimize by filtering the previous results:

```rust
fn filter_incremental(&mut self, previous_query: &str) {
    if self.query.starts_with(previous_query) && !previous_query.is_empty() {
        // Filter existing results instead of all entries
        self.filtered.retain(|(i, _)| {
            self.matcher.fuzzy_match(&self.names_lower[*i], &self.query).is_some()
        });

        // Update scores
        for (i, score) in &mut self.filtered {
            if let Some(new_score) = self.matcher.fuzzy_match(&self.names_lower[*i], &self.query) {
                *score = new_score;
            }
        }

        self.filtered.sort_unstable_by(|a, b| {
            b.1.cmp(&a.1)
                .then_with(|| self.names_lower[a.0].cmp(&self.names_lower[b.0]))
        });
    } else {
        self.filter(); // Full filter for other cases
    }
}
```

## 5. Lazy Evaluation

Only compute what's needed for display:

```rust
struct LazyFilterIterator<'a> {
    names_lower: &'a [String],
    matcher: &'a Matcher,
    query: &'a str,
    current_index: usize,
}

impl<'a> Iterator for LazyFilterIterator<'a> {
    type Item = (usize, i64);

    fn next(&mut self) -> Option<Self::Item> {
        while self.current_index < self.names_lower.len() {
            let i = self.current_index;
            self.current_index += 1;

            if let Some(score) = self.matcher.fuzzy_match(&self.names_lower[i], self.query) {
                return Some((i, score));
            }
        }
        None
    }
}
```

