private List<StorageContainer> FindEligibleTargetsForRouting(Vector3 origin, float radius, Item item = null)
{
    List<StorageContainer> targets = new List<StorageContainer>();

    // Reuse the same logic as "Send Near" command
    foreach (var entity in BaseNetworkable.serverEntities)
    {
        var container = entity as StorageContainer;
        if (container == null || container.IsDestroyed) continue;

        // Check distance
        if (Vector3.Distance(container.transform.position, origin) > radius) continue;

        // Check if container is allowed for routing
        if (!IsAllowedContainer(container)) continue;

        // Check LOS if configured
        if (config.PreventLootThroughWalls && !HasLineOfSight(origin, container.transform.position)) continue;

        // For vending machines, check if they accept the specific item type
        if (container.ShortPrefabName.Contains("vending"))
        {
            var vending = container as VendingMachine;
            if (vending != null && item != null)
            {
                // Check if vending machine accepts this item type via its filters
                if (!VendingAcceptsItem(vending, item))
                    continue;
            }
        }

        targets.Add(container);
    }

    return targets.OrderBy(t => Vector3.Distance(t.transform.position, origin)).ToList();
}

private bool VendingAcceptsItem(VendingMachine vending, Item item)
{
    // Check vending machine's buy orders to see if it accepts this item
    foreach (var order in vending.buyOrders)
    {
        if (order.itemToBuySell.itemid == item.info.itemid)
            return true;
    }
    return false;
}
```

