# SmartSorter Vending Machine Auto-Sort Fix

## Analysis

The issue stems from divergent code paths between automatic drop box sorting and the manual "Send Near" operation. The key differences are:

1. `SortDropBoxItems` uses a different target discovery mechanism that may exclude vending machines
2. The filter validation logic isn't fully shared between the two paths
3. Debug logging is inconsistent between the paths

## Solution

I'll centralize the target selection and routing logic into a shared method that both paths can use. Here's the implementation:

```csharp
// New shared method to handle target selection and routing
private bool RouteFromSourceToEligibleTargets(ItemContainer source, Vector3 origin, float radius, Predicate<StorageContainer> filter = null)
{
    bool movedAny = false;
    var eligibleTargets = new List<StorageContainer>();

    // Find all potential targets within radius
    var potentialTargets = FindEntitiesInRange<StorageContainer>(origin, radius);
    foreach (var target in potentialTargets)
    {
        if (target == null || target.IsDestroyed || !target.IsValidTarget())
            continue;

        if (filter != null && !filter(target))
            continue;

        if (config.PreventLootThroughWalls && !HasLineOfSight(origin, target.transform.position))
        {
            if (config.DebugLogging)
                PrintWarning($"Excluded {target.ShortPrefabName}: No line of sight");
            continue;
        }

        if (!IsAllowedContainerType(target))
        {
            if (config.DebugLogging)
                PrintWarning($"Excluded {target.ShortPrefabName}: Not allowed container type");
            continue;
        }

        eligibleTargets.Add(target);
    }

    // Sort targets by distance (closest first)
    eligibleTargets.Sort((a, b) => Vector3.Distance(origin, a.transform.position)
        .CompareTo(Vector3.Distance(origin, b.transform.position)));

    // Try to route items to each eligible target
    foreach (var target in eligibleTargets)
    {
        if (TryRouteItems(source, target))
        {
            movedAny = true;
            // If we moved items, we might want to break or continue based on requirements
            // For now, we'll try all targets to maximize item movement
        }
    }

    return movedAny;
}

// Modified SortDropBoxItems to use the shared method
private void SortDropBoxItems(StorageContainer sc)
{
    if (sc == null || sc.IsDestroyed || !sc.IsValidTarget())
        return;

    if (config.DebugLogging)
        PrintWarning($"Starting auto-sort for drop box {sc.ShortPrefabName}");

    RouteFromSourceToEligibleTargets(
        sc.inventory,
        sc.transform.position,
        config.DefaultRadiusDistance,
        container => IsContainerEligibleForAutoSort(container)
    );
}

// Modified "Send Near" handler to use the shared method
[ConsoleCommand("SmartSorterUI.to_radius")]
private void cmdSendNear(ConsoleSystem.Arg arg)
{
    var player = arg.Player();
    if (player == null) return;

    var container = GetLookingAtContainer(player);
    if (container == null)
    {
        SendReply(arg, "Not looking at a valid container");
        return;
    }

    if (config.DebugLogging)
        PrintWarning($"Manual 'Send Near' for container {container.ShortPrefabName}");

    bool moved = RouteFromSourceToEligibleTargets(
        container.inventory,
        container.transform.position,
        config.DefaultRadiusDistance
    );

    SendReply(arg, moved ? "Items sent to nearby containers" : "No items were moved");
}

