void StartNewCycle()
{
    // Check market state before proceeding
    if(!marketInitialized)
    {
        Print("Cannot start new cycle - market not ready");
        return;
    }

    // Refresh symbol rates
    symbolInfo.RefreshRates();
    double price = symbolInfo.Bid();
    if(price <= 0.0)
    {
        Print("Invalid price for new cycle");
        return;
    }

    double point = symbolInfo.Point();
    int digits = (int)symbolInfo.Digits();

    // Reset counters and extension when starting new cycle
    hedgeCount = 0;
    tradesThisCycle = 0;
    currentExtension = 0; // Reset extension for new cycle
    currentLot = LotSize;

    // Calculate order levels - convert points to price
    double buyStop = NormalizeDouble(price + HedgeDistance * point, digits);
    double sellStop = NormalizeDouble(price - HedgeDistance * point, digits);

    // Submit pending orders with retry logic
    if(SubmitPendingOrderWithRetry(ORDER_TYPE_BUY_STOP, buyStop, 0) &&
       SubmitPendingOrderWithRetry(ORDER_TYPE_SELL_STOP, sellStop, 0))
    {
        currentLevelA = buyStop;
        currentLevelB = sellStop;
        currentTP = 0;
        currentDirection = 0;
        hedgeActive = AllowHedging;
        totalCycles++;
        Print("New cycle started successfully: BuyStop @ ", buyStop, ", SellStop @ ", sellStop);
        lastCycleTime = TimeCurrent();
        orderPlaced = true;
    }
    else
    {
        Print("Failed to start new cycle - order placement failed");
        // Reset timing to try again next tick
        lastCycleTime = TimeCurrent() - (WaitMinutes * 60) + 1;
    }
}

//+------------------------------------------------------------------+
//| Submit a pending order with retry logic                          |
//+------------------------------------------------------------------+
bool SubmitPendingOrderWithRetry(const ENUM_ORDER_TYPE type, const double price, const double tp)
{
    MqlTradeRequest request = {};
    MqlTradeResult result = {};
    int retryCount = 0;

    request.action = TRADE_ACTION_PENDING;
    request.symbol = Symbol();
    request.volume = LotSize;
    request.type = type;
    request.price = price;
    request.tp = tp;
    request.deviation = 10;
    request.type_filling = ORDER_FILLING_FOK;
    request.magic = 123456;

    while(retryCount < MaxRetryCount)
    {
        if(OrderSend(request, result))
        {
            Print("Pending order placed: ", EnumToString(type), " @ ", price);
            return true;
        }

        Print("OrderSend failed (attempt ", retryCount+1, " of ", MaxRetryCount, "): ",
              result.retcode, " - ", GetRetcodeDescription(result.retcode));

        retryCount++;
        if(retryCount < MaxRetryCount)
        {
            Sleep(RetryDelayMs);
            symbolInfo.RefreshRates();
        }
    }
    return false;
}

