void OpenTrade(const ENUM_ORDER_TYPE type, const double lot, const double tp)
{
    MqlTradeRequest request = {};
    MqlTradeResult result = {};
    int retryCount = 0;

    request.action = TRADE_ACTION_DEAL;
    request.symbol = Symbol();
    request.volume = lot;
    request.type = type;
    request.price = (type == ORDER_TYPE_BUY) ? symbolInfo.Ask() : symbolInfo.Bid();
    request.tp = tp;
    request.deviation = 10;
    request.type_filling = ORDER_FILLING_FOK;
    request.magic = 123456;

    while(retryCount < MaxRetryCount)
    {
        if(OrderSend(request, result))
        {
            Print("Hedge trade opened: ", EnumToString(type), " Lot: ", lot, " → TP: ", tp);
            return;
        }

        Print("Hedge OrderSend failed (attempt ", retryCount+1, " of ", MaxRetryCount, "): ",
              result.retcode, " - ", GetRetcodeDescription(result.retcode));

        retryCount++;
        if(retryCount < MaxRetryCount)
        {
            Sleep(RetryDelayMs);
            symbolInfo.RefreshRates();
        }
    }
