            }
        }

        if(totalFloatingProfit >= EarlyExitProfit)
        {
            Print("Early exit condition met! Positions: ", totalPositions,
                  " | Floating P/L: $", DoubleToString(totalFloatingProfit, 2));

            // Draw yellow "E" on chart at current price
