void CheckPreciseDrawdownElimination()
{
    if(!UseDrawdownElimination) return;

    int totalPositions = PositionsTotal();
    if(totalPositions < 2) return; // Need at least 2 positions

    // Get all positions for our symbol
    int count = 0;
    ulong tickets[];
    datetime openTimes[];
    double profits[];

    for(int i = 0; i < totalPositions; i++)
    {
        if(PositionGetSymbol(i) == Symbol())
        {
            ArrayResize(tickets, count+1);
            ArrayResize(openTimes, count+1);
            ArrayResize(profits, count+1);

            tickets[count] = PositionGetTicket(i);
            PositionSelectByTicket(tickets[count]);
            openTimes[count] = (datetime)PositionGetInteger(POSITION_TIME);
            profits[count] = PositionGetDouble(POSITION_PROFIT);
            count++;
        }
    }

    // Sort positions by open time (oldest first)
    for(int i = 0; i < count-1; i++)
    {
        for(int j = i+1; j < count; j++)
        {
            if(openTimes[j] < openTimes[i])
            {
                // Swap tickets
                ulong tempTicket = tickets[i];
                tickets[i] = tickets[j];
                tickets[j] = tempTicket;

                // Swap times
                datetime tempTime = openTimes[i];
                openTimes[i] = openTimes[j];
                openTimes[j] = tempTime;

                // Swap profits
                double tempProfit = profits[i];
                profits[i] = profits[j];
                profits[j] = tempProfit;
            }
        }
    }

    // Calculate total profit of all positions
    double totalProfit = 0;
    for(int i = 0; i < count; i++)
    {
        totalProfit += profits[i];
    }

    // Check oldest position for break-even
    if(count > 0)
    {
        PositionSelectByTicket(tickets[0]);
        double positionVolume = PositionGetDouble(POSITION_VOLUME);
        double spreadCost = (symbolInfo.Ask() - symbolInfo.Bid()) * positionVolume * symbolInfo.TickValue() / symbolInfo.TickSize();

        // If oldest position is at break-even (including spread) and closing it won't reduce total profit
        if(profits[0] >= -spreadCost && (totalProfit - profits[0]) >= totalProfit)
        {
            Print("Closing break-even position #", tickets[0], 
                  " (Profit: ", profits[0], ", Spread Cost: ", spreadCost, 
                  ", Total Profit Before: ", totalProfit, ")");

            if(!trade.PositionClose(tickets[0]))
            {
                Print("Failed to close position #", tickets[0], ": ", GetLastError());
            }
        }
    }
}

//+------------------------------------------------------------------+
//| Extend grid spacing based on trade count                         |
//+------------------------------------------------------------------+
void ExtendGridSpacing()
{
    if(!UseGridExtension) return;

    // Calculate new extension amount
    int extensionTrades = tradesThisCycle - ExtensionStartTrade + 1;
    int newExtension = MathMin(extensionTrades * ExtensionIncrement, MaxExtension);

    // Only proceed if extension has changed
    if(newExtension <= currentExtension) return;

    currentExtension = newExtension;

    Print("Extending grid spacing by ", currentExtension, " points. Trade #", tradesThisCycle);

    // Refresh current price
    symbolInfo.RefreshRates();
    double price = symbolInfo.Bid();
    double point = symbolInfo.Point();
    int digits = (int)symbolInfo.Digits();

    // Calculate new levels with extended spacing
    double totalDistance = HedgeDistance + currentExtension;
    double newBuyStop = NormalizeDouble(price + totalDistance * point, digits);
    double newSellStop = NormalizeDouble(price - totalDistance * point, digits);

    // Delete existing pending orders
    DeleteAllPendingOrders();

    // Place new orders with extended spacing
    if(SubmitPendingOrderWithRetry(ORDER_TYPE_BUY_STOP, newBuyStop, 0) &&
       SubmitPendingOrderWithRetry(ORDER_TYPE_SELL_STOP, newSellStop, 0))
    {
        currentLevelA = newBuyStop;
        currentLevelB = newSellStop;
        Print("Grid extended successfully. New levels: Buy @ ", newBuyStop, ", Sell @ ", newSellStop);
    }
    else
    {
        Print("Failed to extend grid - order placement failed");
        // Revert extension on failure
        currentExtension = MathMax(0, currentExtension - ExtensionIncrement);
    }
}

