void OnTradeTransaction(const MqlTradeTransaction &trans,
                       const MqlTradeRequest &request,
                       const MqlTradeResult &result)
{
    if(trans.type == TRADE_TRANSACTION_DEAL_ADD)
    {
        ulong deal = trans.deal;
        if(HistoryDealSelect(deal))
        {
            string dealSymbol = HistoryDealGetString(deal, DEAL_SYMBOL);
            if(dealSymbol != Symbol()) return;

            int entry = (int)HistoryDealGetInteger(deal, DEAL_ENTRY);
            double profit = HistoryDealGetDouble(deal, DEAL_PROFIT);
            ENUM_DEAL_TYPE deal_type = (ENUM_DEAL_TYPE)HistoryDealGetInteger(deal, DEAL_TYPE);
            ENUM_POSITION_TYPE pos_type = (deal_type == DEAL_TYPE_BUY) ? POSITION_TYPE_BUY : POSITION_TYPE_SELL;

            double point = symbolInfo.Point();
            int digits = (int)symbolInfo.Digits();
            double open_price = HistoryDealGetDouble(deal, DEAL_PRICE);

            if(entry == DEAL_ENTRY_IN)
            {
                // Increment the trade counter for this cycle
                tradesThisCycle++;
                Print("Trade opened. Total trades this cycle: ", tradesThisCycle);

                // Apply grid extension if enabled and conditions met
                if(UseGridExtension && tradesThisCycle >= ExtensionStartTrade)
                {
                    ExtendGridSpacing();
                }

                // Check if it's time to reset the grid
                if(UseGridReset && tradesThisCycle >= GridResetAtTrade)
                {
                    ExecuteGridReset();
                    return; // Exit the function early after reset
                }

                if(pos_type == POSITION_TYPE_BUY)
                {
                    currentDirection = 1;
                    // Convert points to price for TP
                    currentTP = NormalizeDouble(open_price + TakeProfitDistance * point, digits);
                    DeleteLevelOrder(currentLevelB);
                }
                else if(pos_type == POSITION_TYPE_SELL)
                {
                    currentDirection = -1;
                    // Convert points to price for TP
                    currentTP = NormalizeDouble(open_price - TakeProfitDistance * point, digits);
                    DeleteLevelOrder(currentLevelA);
                }

                if(PositionSelect(Symbol()))
                {
                    ulong ticket = PositionGetInteger(POSITION_TICKET);
                    if(!trade.PositionModify(ticket, 0.0, currentTP))
                    {
                        Print("Failed to modify position TP: ", GetLastError());
                    }
                }
                Print("TP set for position: ", currentTP);
            }

            if(entry == DEAL_ENTRY_OUT && profit > 0)
            {
                successfulTrades++;
                Print("TP hit detected from deal #", deal, " | Profit: ", profit);
                // Use the new reset function to clean up
                ExecuteGridReset();
            }
        }
    }
}
