        // Convert points to price for TP
        double tp = NormalizeDouble(price - TakeProfitDistance * point, digits);
        OpenTrade(ORDER_TYPE_SELL, newLot, tp);
        currentLot = newLot;
        currentDirection = -1;
        hedgeCount++;
        DeleteLevelOrder(currentLevelB);
