    else if(currentDirection == -1 && price >= currentLevelA)
    {
        double newLot = NormalizeLotSize(currentLot * HedgeMultiplier);
        // Convert points to price for TP
        double tp = NormalizeDouble(price + TakeProfitDistance * point, digits);
        OpenTrade(ORDER_TYPE_BUY, newLot, tp);
        currentLot = newLot;
        currentDirection = 1;
        hedgeCount++;
        DeleteLevelOrder(currentLevelA);
    }
}

//+------------------------------------------------------------------+
//| Normalize lot size to valid increments                           |
//+------------------------------------------------------------------+
double NormalizeLotSize(const double lots)
{
    double minLot = SymbolInfoDouble(Symbol(), SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(Symbol(), SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(Symbol(), SYMBOL_VOLUME_STEP);

    double normalized = MathFloor(lots / lotStep) * lotStep;
    normalized = MathMax(normalized, minLot);
    normalized = MathMin(normalized, maxLot);

    return normalized;
}

