### Improved version of `CheckPreciseDrawdownElimination()`

```mql5
void CheckPreciseDrawdownElimination()
{
    if(!UseDrawdownElimination) return;

    int totalPositions = PositionsTotal();
    if(totalPositions < 2) return; // Need at least 2 positions

    // Arrays to hold position info
    ulong tickets[];
    datetime openTimes[];
    double profits[];
    double volumes[];

    int count = 0;

    // Collect positions for current symbol
    for(int i = 0; i < totalPositions; i++)
    {
        if(PositionGetSymbol(i) == Symbol())
        {
            ulong ticket = PositionGetTicket(i);
            if(PositionSelectByTicket(ticket))
            {
                ArrayResize(tickets, count + 1);
                ArrayResize(openTimes, count + 1);
                ArrayResize(profits, count + 1);
                ArrayResize(volumes, count + 1);

                tickets[count] = ticket;
                openTimes[count] = (datetime)PositionGetInteger(POSITION_TIME);
                profits[count] = PositionGetDouble(POSITION_PROFIT);
                volumes[count] = PositionGetDouble(POSITION_VOLUME);
                count++;
            }
        }
    }

    if(count < 2) return;

    // Sort positions by open time ascending (oldest first)
    for(int i = 0; i < count - 1; i++)
    {
        for(int j = i + 1; j < count; j++)
        {
            if(openTimes[j] < openTimes[i])
            {
                // Swap tickets
                ulong tempTicket = tickets[i];
                tickets[i] = tickets[j];
                tickets[j] = tempTicket;

                // Swap times
                datetime tempTime = openTimes[i];
                openTimes[i] = openTimes[j];
                openTimes[j] = tempTime;

                // Swap profits
                double tempProfit = profits[i];
                profits[i] = profits[j];
                profits[j] = tempProfit;

                // Swap volumes
                double tempVolume = volumes[i];
                volumes[i] = volumes[j];
                volumes[j] = tempVolume;
            }
        }
    }

    // Calculate total profit of all positions
    double totalProfit = 0.0;
    for(int i = 0; i < count; i++)
        totalProfit += profits[i];

    // Define a small tolerance for floating point comparison
    const double epsilon = 0.01;

    // Calculate spread cost for each position (approximate)
    double spread = symbolInfo.Ask() - symbolInfo.Bid();
    double tickValue = symbolInfo.TickValue();
    double tickSize = symbolInfo.TickSize();

    // Iterate over positions from oldest to newest
    for(int i = 0; i < count; i++)
    {
        double spreadCost = spread * volumes[i] * tickValue / tickSize;

        // Check if position is break-even or slightly profitable (including spread)
        bool isBreakEvenOrBetter = (profits[i] >= -spreadCost - epsilon);

        // Check if closing this position won't reduce total profit significantly
        double profitIfClosed = totalProfit - profits[i];

        if(isBreakEvenOrBetter && profitIfClosed + epsilon >= totalProfit)
        {
            PrintFormat("Closing break-even position #%I64u | Profit: %.5f | Spread Cost: %.5f | Total Profit Before: %.5f",
                        tickets[i], profits[i], spreadCost, totalProfit);

            if(!trade.PositionClose(tickets[i]))
            {
                PrintFormat("Failed to close position #%I64u: Error %d", tickets[i], GetLastError());
            }
            else
            {
                // Update totalProfit after closing this position
                totalProfit = profitIfClosed;
                // Remove this position from arrays to avoid double closing
                // Shift arrays left
                for(int k = i; k < count - 1; k++)
                {
                    tickets[k] = tickets[k+1];
                    openTimes[k] = openTimes[k+1];
                    profits[k] = profits[k+1];
                    volumes[k] = volumes[k+1];
                }
                count--;
                i--; // Adjust index to check next position correctly
            }
        }
    }
}
