// Handle a single QUIC bidirectional stream
async fn handle_quic_stream(mut send: SendStream, mut recv: RecvStream, runtime: Arc<OtpRuntime>) {
    // Read length-prefixed Cap'n Proto message
    let len_bytes = recv.read_exact(&mut [0u8; 4]).await.unwrap();  // Read u32 length
    let len = u32::from_be_bytes(len_bytes.try_into().unwrap()) as usize;
    let mut msg_bytes = vec![0u8; len];
    recv.read_exact(&mut msg_bytes).await.unwrap();

    // Deserialize Cap'n Proto message
    let message_reader = capnp::serialize_packed::read_message(&mut std::io::Cursor::new(msg_bytes), ::capnp::message::ReaderOptions::new()).unwrap();
    let network_msg: message_capnp::network_message::Reader = message_reader.get_root().unwrap();

    let target_actor_id_str = network_msg.get_target_actor_id()?.to_string().unwrap();
    let payload = network_msg.get_payload()?.to_vec();

    // Parse actor ID (assume UUID string)
    let actor_id = Uuid::parse_str(&target_actor_id_str).unwrap();  // Handle parsing errors in production

    // Look up actor in registry and send payload
    let registry = runtime.registry.lock().await;
    if let Some(sender) = registry.get(&actor_id) {
        sender.send(payload).await.unwrap();  // Ignore errors for simplicity
    } else {
        eprintln!("Actor not found: {}", actor_id);
    }
}

// Handle send requests from WASM host function
async fn handle_send_requests(rx: CrossbeamReceiver<(Vec<u8>, Vec<u8>)>, runtime: Arc<OtpRuntime>, actor_id: ActorId) {
    while let Ok((target_bytes, payload_bytes)) = rx.recv() {  // Blocking recv in sync context
        let target_str = String::from_utf8(target_bytes).unwrap();  // Assume UTF-8 string
        let parts: Vec<&str> = target_str.split(':').collect();
        if parts.len() != 2 {
            eprintln!("Invalid target string: {}", target_str);
            continue;
        }
        let node = parts[0].to_string();
        let actor_id_str = parts[1];
        let actor_id = Uuid::parse_str(actor_id_str).unwrap();  // Handle errors

        if node == runtime.local_node_addr {
            // Local actor, send directly
            let registry = runtime.registry.lock().await;
            if let Some(sender) = registry.get(&actor_id) {
                sender.send(payload_bytes.clone()).await.ok();
            }
        } else {
            // Remote actor, send over QUIC with Cap'n Proto
            send_remote(&runtime, &node, &actor_id, &payload_bytes).await;
        }
    }
}

