## 4. 代码示例优化

```cpp
// 1. newGroup 同步数据库，返回新节点指针
TreeNode* newGroup(int parentID, const QString& groupName)
{
    TreeNode* parentNode = (parentID == -1) ? m_rootNode : findGroupByID(parentID);
    if (!parentNode) return nullptr;

    // 插入数据库
    QSqlQuery query;
    query.prepare("INSERT INTO T_Group (GroupName, ParentID) VALUES (:name, :parentID)");
    query.bindValue(":name", groupName);
    query.bindValue(":parentID", parentID);
    if (!query.exec()) {
        qWarning() << "Insert group failed:" << query.lastError().text();
        return nullptr;
    }
    int newID = query.lastInsertId().toInt();

    int row = parentNode->childCount();
    QModelIndex parentIndex = (parentNode == m_rootNode) ? QModelIndex() : createIndex(parentNode->row(), 0, parentNode);

    beginInsertRows(parentIndex, row, row);
    QList<QVariant> groupNodeData{groupName, true, newID};
    TreeNode* newGroup = new TreeNode(groupNodeData, parentNode);
    parentNode->appendChild(newGroup);
    endInsertRows();

    return newGroup;
}

// 2. newName 同步数据库
void newName(const QModelIndex& index, const QString& newName)
{
    if (!index.isValid()) return;
    TreeNode* node = nodeFromIndex(index);
    int id = node->rawData().value(2).toInt();

    QSqlQuery query;
    query.prepare("UPDATE T_Group SET GroupName = :name WHERE ID = :id");
    query.bindValue(":name", newName);
    query.bindValue(":id", id);
    if (!query.exec()) {
        qWarning() << "Update group name failed:" << query.lastError().text();
        return;
    }

    node->m_nodeData[0] = newName;
    emit dataChanged(index, index);
}

// 3. delGroupAndArticle 使用事务递归删除
void delGroupAndArticle(TreeNode* node)
{
    QSqlDatabase::database().transaction();

    std::function<void(TreeNode*)> recursiveDelete = [&](TreeNode* n) {
        for (auto child : n->m_children) {
            if (child->m_nodeData[1].toBool()) { // 分组
                recursiveDelete(child);
                QSqlQuery query;
                query.prepare("DELETE FROM T_Group WHERE ID = :id");
                query.bindValue(":id", child->m_nodeData[2].toInt());
                if (!query.exec()) {
                    qWarning() << "Delete group failed:" << query.lastError().text();
                }
            } else { // 文章
                QSqlQuery query;
                query.prepare("DELETE FROM T_Article WHERE ID = :id");
                query.bindValue(":id", child->m_nodeData[2].toInt());
                if (!query.exec()) {
                    qWarning() << "Delete article failed:" << query.lastError().text();
                }
            }
            delete child;
        }
        n->m_children.clear();
    };

    recursiveDelete(node);

    QSqlQuery query;
    query.prepare("DELETE FROM T_Group WHERE ID = :id");
    query.bindValue(":id", node->m_nodeData[2].toInt());
    if (!query.exec()) {
        qWarning() << "Delete group failed:" << query.lastError().text();
    }

    QSqlDatabase::database().commit();
}

// 4. nodeFromIndex 增加断言
TreeNode* nodeFromIndex(const QModelIndex& index) const {
    if (!index.isValid()) {
        return m_rootNode;
    }
    TreeNode* node = static_cast<TreeNode*>(index.internalPointer());
    Q_ASSERT(node != nullptr);
    return node;
}
