### 📄 `content.js` (Behavioral Detection)
```javascript
// Detect hidden iframes
function detectHiddenIframes() {
  const iframes = document.querySelectorAll('iframe');
  let hiddenCount = 0;
  iframes.forEach(iframe => {
    const style = window.getComputedStyle(iframe);
    if (style.display === 'none' || style.visibility === 'hidden' || iframe.offsetWidth === 0 || iframe.offsetHeight === 0) {
      hiddenCount++;
    }
  });
  if (hiddenCount > 0) {
    console.warn(`⚠️ ${hiddenCount} hidden iframes detected`);
    sendBehaviorEvent('hidden_iframes', hiddenCount);
  }
}

// Detect external forms (login forms pointing to other domains)
function detectExternalForms() {
  const forms = document.querySelectorAll('form');
  forms.forEach(form => {
    const action = form.getAttribute('action');
    if (action && !action.startsWith(window.location.origin)) {
      console.warn(`⚠️ External form action: ${action}`);
      sendBehaviorEvent('external_form', action);
    }
  });
}

// Detect keystroke/clipboard listeners
function detectKeystrokeListeners() {
  const events = ['keydown', 'keypress', 'keyup', 'paste', 'copy'];
  let riskyEvents = 0;

  events.forEach(event => {
    document.addEventListener(event, () => {
      riskyEvents++;
      if (riskyEvents >= 2) {
        console.warn('⚠️ Multiple clipboard/keystroke listeners detected');
        sendBehaviorEvent('keystroke_capture', riskyEvents);
      }
    }, { capture: true, once: false });
  });
}

// Send behavior data to background script
function sendBehaviorEvent(type, value) {
  chrome.runtime.sendMessage({
    type: 'BEHAVIOR_DETECTED',
    payload: { type, value, timestamp: Date.now(), url: window.location.href }
  });
}

// Run all checks
detectHiddenIframes();
detectExternalForms();
detectKeystrokeListeners();

// Re-check if page changes (SPA)
const observer = new MutationObserver(() => {
  detectHiddenIframes();
  detectExternalForms();
});
observer.observe(document.body, { childList: true, subtree: true });
```

