### Refactored `DeserializeAssetsMetadata` Function

```cpp
AssetType AssetManager::DeserializeAssetsMetadata(std::filesystem::path _path, std::unique_ptr<BaseAsset>& _asset)
{
    // Read .meta file
    std::ifstream metafile(_path);
    if (!metafile.is_open()) {
        return UNKNOWN;
    }

    std::string line;
    while (std::getline(metafile, line)) {
        if (line.empty()) continue; // Skip empty lines

        size_t equalsPos = line.find('=');
        if (equalsPos == std::string::npos) continue; // Skip malformed lines

        std::string key = line.substr(0, equalsPos);
        std::string value = line.substr(equalsPos + 1);

        // Trim whitespace from key and value
        key.erase(0, key.find_first_not_of(" \t"));
        key.erase(key.find_last_not_of(" \t") + 1);
        value.erase(0, value.find_first_not_of(" \t"));
        value.erase(value.find_last_not_of(" \t") + 1);

        // Handle GUID
        if (key == entt::resolve<xresource::full_guid>().name()) {
            size_t typePos = value.find("Type=");
            size_t instancePos = value.find("Instance=");

            if (typePos != std::string::npos && instancePos != std::string::npos) {
                xresource::type_guid type;
                xresource::instance_guid instance;

                type.m_Value = std::stoull(value.substr(typePos + 5, instancePos - typePos - 5));
                instance.m_Value = std::stoull(value.substr(instancePos + 9));

                _asset->guid = { instance, type };
            }
        }
        // Handle file time
        else if (key == entt::resolve<fs::file_time_type>().name()) {
            std::istringstream iss(value);
            std::chrono::system_clock::time_point sys_tp;
            iss >> std::chrono::parse("%F %T", sys_tp);

            if (!iss.fail()) {
                _asset->lastModified = std::chrono::clock_cast<std::chrono::file_clock>(sys_tp);
            } else {
                std::cerr << "Failed to parse time string: " << value << std::endl;
            }
        }
        // Handle file path
        else if (key == entt::resolve<fs::path>().name()) {
            _asset->sourceFilePath = value;
        }
        // Handle TextureAsset specific fields
        else if (auto textureAsset = dynamic_cast<TextureAsset*>(_asset.get())) {
            if (key == "compressionFormats") {
                textureAsset->compressionFormats = StringToEnum<TextureAsset::TextureCompression>(value);
            }
            else if (key == "mipmapsLevel") {
                textureAsset->mipmapsLevel = std::stoi(value);
            }
            else if (key == "filterMode") {
                textureAsset->filterMode = StringToEnum<TextureAsset::TextureFilter>(value);
            }
            else if (key == "wrapMode") {
                textureAsset->wrapMode = StringToEnum<TextureAsset::TextureWrap>(value);
            }
        }
    }

    // Determine asset type based on GUID
    if (TextureAsset::typeGUID.m_Value == _asset->guid.m_Type.m_Value) {
        return TEXTURE;
    }

    return UNKNOWN;
}
