                    </div>
                {% elif field[1].type == pydantic.BaseModel %}
                    {{ render_model(data[field[0]] if data else None, field[1].type) }}
                {% else %}
                    <input type="text" id="{{ field[0] }}" name="{{ field[0] }}" value="{% if data and field[0] in data %}{{ data[field[0]] }}{% endif %}">
                {% endif %}
            </div>
        {% endfor %}
