                alert(`Adding item to ${list_id} of type ${model_name}.  Implementation needed.`);
            }
        </script>
        """
    )

    def render_model(data: Optional[BaseModel], model: type[BaseModel]) -> str:
        """Recursively renders nested models."""
        if not data:
            return ""  # Handle cases where nested model is optional and not provided

        form_fields = []
        for field_name, field in model.__fields__.items():
            label = field_name.replace('_', ' ').title()
            if field.type == list:
                list_items = ""
                if data and field_name in data:
                    for item in data[field_name]:
                        list_items += render_model(item, field.element_type)
                list_items += f'<button type="button" onclick="add_item(\'{field_name}\', \'{field.element_type.__name__}\')">Add {label}</button>'
                form_fields.append(f'<div id="{field_name}">{list_items}</div>')
            elif field.type == BaseModel:
                form_fields.append(render_model(getattr(data, field_name) if data else None, field.type))
            else:
                form_fields.append(f'<div class="form-group"><label for="{field_name}">{label}:</label><input type="text" id="{field_name}" name="{field_name}" value="{getattr(data, field_name) if data else ""}"></div>')

        return f'<div class="nested-model">\n{"".join(form_fields)}\n</div>'

    return template.render(model=model, data=data, render_model=render_model)


