   SetIndexStyle(1, DRAW_LINE);
   SetIndexLabel(0, "Volume Oscillator");
   SetIndexLabel(1, "Standard Volume Oscillator");
   SetIndexBuffer(0, VolumeOsc);
   SetIndexBuffer(1, StandardVolumeOsc);

   return(INIT_SUCCEEDED);
  }
