int OnCalculate(const int rates_total,
                const int prev_calculated,
                const datetime &time[],
                const double &open[],
                const double &high[],
                const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
  {
   int limit = rates_total - prev_calculated;
   if (limit < 1) return(0);

   for (int i = 0; i < limit; i++)
     {
      double buyVol = 0;
      double sellVol = 0;
      double stdBuyVol = 0;
      double stdSellVol = 0;

      // Get the current timeframe's open price
      double currentOpen = open[i];

      // Loop through M1 data to calculate buy and sell volumes
      for (int j = 0; j < 60; j++) // Assuming 60 M1 bars per higher timeframe
        {
         datetime m1Time = iTime(_Symbol, PERIOD_M1, j);
         double m1Open = iOpen(_Symbol, PERIOD_M1, j);
         double m1Volume = iVolume(_Symbol, PERIOD_M1, j);
         double m1Range = iHigh(_Symbol, PERIOD_M1, j) - iLow(_Symbol, PERIOD_M1, j);

         if (m1Open < currentOpen)
           {
            sellVol += m1Volume;
            if (UseStandardVolume)
              stdSellVol += m1Volume / m1Range;
           }
         else
           {
            buyVol += m1Volume;
            if (UseStandardVolume)
              stdBuyVol += m1Volume / m1Range;
           }
        }

      // Calculate the volume oscillator
      VolumeOsc[i] = buyVol - sellVol;
      if (UseStandardVolume)
        StandardVolumeOsc[i] = stdBuyVol - stdSellVol;
     }

   return(rates_total);
  }
