//| Custom indicator initialization function                         |
//+------------------------------------------------------------------+
int init()
{
   SetIndexBuffer(0, OscBuffer);
   SetIndexStyle(0, DRAW_HISTOGRAM);
   SetIndexLabel(0, "Volume Oscillator");
   IndicatorShortName("Volume Oscillator");
   return(0);
}

//+------------------------------------------------------------------+
//| Custom indicator iteration function                              |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,
                const int prev_calculated,
                const datetime &time[],
                const double &open[],
                const double &high[],
                const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
   int calculated = (prev_calculated > 0) ? prev_calculated - 1 : 0;

   for(int pos = calculated; pos < rates_total; pos++)
   {
      double buy = 0.0;
      double sell = 0.0;

      // Get starting M1 shift for this bar's open time
      int shift_m1_start = iBarShift(_Symbol, PERIOD_M1, time[pos], false);

      // Get ending M1 shift
      int shift_m1_end;
      if(pos < rates_total - 1)
      {
         shift_m1_end = iBarShift(_Symbol, PERIOD_M1, time[pos + 1], false) - 1;
      }
      else
      {
         shift_m1_end = iBars(_Symbol, PERIOD_M1) - 1;
      }

      // Safety checks
      if(shift_m1_start < 0 || shift_m1_end < 0 || shift_m1_end < shift_m1_start)
      {
         OscBuffer[pos] = 0.0;
         continue;
      }

      // Loop over M1 shifts from start to end (older to newer)
      for(int s = shift_m1_start; s <= shift_m1_end; s++)
      {
         double o = iOpen(_Symbol, PERIOD_M1, s);
         long vol = iVolume(_Symbol, PERIOD_M1, s);
         double vol_used = (double)vol;

         if(UseNormalized)
         {
            double h = iHigh(_Symbol, PERIOD_M1, s);
            double l = iLow(_Symbol, PERIOD_M1, s);
            double rng = h - l;
            vol_used = (rng > 0.0) ? (double)vol / rng : 0.0;
         }

         if(o > open[pos])
            buy += vol_used;
         else if(o < open[pos])
            sell += vol_used;
         // Note: If o == open[pos], it is ignored as per specification
      }

      OscBuffer[pos] = buy - sell;
   }

   return(rates_total);
}
//+------------------------------------------------------------------+
