                    this.targetSurfacePos.getX() + 0.5,
                    this.targetSurfacePos.getY() + 1.0, // Look towards the air above
                    this.targetSurfacePos.getZ() + 0.5
            );
        } else {
            // CRITICAL FALLBACK (No path found, just swim straight up)
            // This is a safety measure to prevent drowning if pathfinding fails.
            this.penguin.getMoveControl().setWantedPosition(
                    this.penguin.getX(),
                    this.penguin.getY() + 5, // Target 5 blocks up from current Y
                    this.penguin.getZ(),
                    this.speed * 1.5
            );
            this.penguin.getLookControl().setLookAt(
