    @Nullable
    private BlockPos findNearestSurface() {
        Level level = this.penguin.level();
        BlockPos currentPos = this.penguin.blockPosition();

        // Search within a reasonable radius for surface.
        // Start from current Y and go up to a certain height.
        for (int yOffset = 0; yOffset < 15; yOffset++) { // Check up to 15 blocks above
            for (int xOffset = -3; xOffset <= 3; xOffset++) {
                for (int zOffset = -3; zOffset <= 3; zOffset++) {
                    BlockPos checkPos = currentPos.offset(xOffset, yOffset, zOffset);

                    // Check if this position is water and the block above is air (or not water)
                    if (level.getFluidState(checkPos).is(FluidTags.WATER) &&
                            !level.getFluidState(checkPos.above()).is(FluidTags.WATER)) {
                        return checkPos; // Found a water block at the surface
                    }
                }
            }
        }
        return null;
    }
    // checkColumn method is no longer needed with the refined findNearestSurface.
    // This finds the water block that is directly below an air block.
    // That means the entity's head will be out of water if it swims into this block.
