package net.mattias.oceancritteria.entity.goals;

import net.mattias.oceancritteria.entity.custom.PenguinEntity;
import net.minecraft.core.BlockPos;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.entity.ai.behavior.BehaviorUtils;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.ai.util.DefaultRandomPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;

import javax.annotation.Nullable;
import java.util.EnumSet;

public class PenguinSwimGoal extends Goal {
    private final PenguinEntity penguin;
    private final double speedModifier;
    private int interval;
    private int timeToNextUpdate;
    private double wantedX;
    private double wantedY;
    private double wantedZ;
    private boolean forceTrigger;

    public PenguinSwimGoal(PenguinEntity penguin, double speedModifier) {
        this.penguin = penguin;
        this.speedModifier = speedModifier;
        this.interval = 80; // Slightly increased interval for less frequent new pathing,
        // allows existing path to complete more often.
        this.setFlags(EnumSet.of(Goal.Flag.MOVE));
    }

    @Override
    public boolean canUse() {
        if (!this.penguin.isInWater()) {
            return false;
        }

        if (this.forceTrigger) { // If explicitly told to find a new path
            Vec3 targetPos = this.getRandomSwimPosition();
            if (targetPos == null) {
                return false;
            }
            this.wantedX = targetPos.x;
            this.wantedY = targetPos.y;
            this.wantedZ = targetPos.z;
            this.forceTrigger = false;
            return true;
        }

        // If not forced, use a random tick delay
        if (this.penguin.getRandom().nextInt(reducedTickDelay(this.interval)) != 0) {
            return false;
        }

        // If current navigation is done, try to find a new path
        if (this.penguin.getNavigation().isDone()) {
            Vec3 targetPos = this.getRandomSwimPosition();
            if (targetPos == null) {
                return false;
            }
            this.wantedX = targetPos.x;
            this.wantedY = targetPos.y;
            this.wantedZ = targetPos.z;
            return true;
        }
        return false;
    }

    @Override
    public boolean canContinueToUse() {
        // Continue if in water AND path is not done.
        // Adding a timeout to prevent endless spinning/stuck paths.
        return this.penguin.isInWater() && !this.penguin.getNavigation().isDone() && this.timeToNextUpdate > 0;
    }

    @Override
    public void start() {
        this.penguin.getNavigation().moveTo(this.wantedX, this.wantedY, this.wantedZ, this.speedModifier * 1.2D); // Slightly boost speed when starting a new path
        this.timeToNextUpdate = this.adjustedTickDelay(120 + this.penguin.getRandom().nextInt(100)); // Give it more time to reach target
    }

    @Override
    public void tick() {
        // Decrement timeToNextUpdate
        --this.timeToNextUpdate;

        // If target reached or time is up, force a new path calculation in canUse next tick
        if (this.penguin.getNavigation().isDone() || this.timeToNextUpdate <= 0) {
            this.forceTrigger = true;
        }
    }

    @Override
    public void stop() {
        this.penguin.getNavigation().stop();
    }

    public void trigger() {
        this.forceTrigger = true;
    }

    public void setInterval(int interval) {
        this.interval = interval;
    }

    @Nullable
    private Vec3 getRandomSwimPosition() {
        // Prefer vanilla method first
        Vec3 vanillaPos = BehaviorUtils.getRandomSwimmablePos(this.penguin, 15, 10); // Increased range
        if (vanillaPos != null && isValidSwimTarget(BlockPos.containing(vanillaPos))) {
            return vanillaPos;
        }

        // Fallback to custom position finding if vanilla fails or provides a bad spot
        return this.findCustomSwimPosition();
    }

    @Nullable
    private Vec3 findCustomSwimPosition() {
        Vec3 currentPos = this.penguin.position();
        int attempts = 0;

        while (attempts < 20) {
            attempts++;

            // Use larger ranges for better exploration, especially vertical
            double offsetX = (this.penguin.getRandom().nextDouble() * 20 - 10); // ±10 blocks
            double offsetZ = (this.penguin.getRandom().nextDouble() * 20 - 10);
            double offsetY = (this.penguin.getRandom().nextDouble() * 10 - 5); // ±5 blocks for vertical movement

            Vec3 targetPos = currentPos.add(offsetX, offsetY, offsetZ);
            BlockPos targetBlock = BlockPos.containing(targetPos);

            if (isValidSwimTarget(targetBlock)) {
                return targetPos;
            }
        }

        // Final fallback (might not be ideal for 3D swimming, but prevents null)
        return DefaultRandomPos.getPos(this.penguin, 10, 7);
    }

    private boolean isValidSwimTarget(BlockPos pos) {
        Level level = this.penguin.level();
        // Must be in water at the target location.
        // Check current block and maybe one block above for swimming space.
        return level.getFluidState(pos).is(FluidTags.WATER) &&
                level.getFluidState(pos.above()).is(FluidTags.WATER) &&
                !level.getBlockState(pos).isSolidRender(level, pos) && // Not a solid block
                !level.getBlockState(pos.above()).isSolidRender(level, pos.above()) && // Not a solid block above
                pos.getY() >= level.getMinBuildHeight() && // Not below world
                pos.getY() < level.getMaxBuildHeight(); // Not above world
        // Removed getSeaLevel check to allow swimming deeper if needed.
    }
}
