public class PenguinGoToSurfaceGoal extends Goal {
    private final PenguinEntity penguin;
    private final double speed;
    private BlockPos targetSurfacePos;

    private static final int AIR_THRESHOLD = 300; // 15 seconds = 300 ticks

    public PenguinGoToSurfaceGoal(PenguinEntity penguin, double speed) {
        this.penguin = penguin;
        this.speed = speed;
        this.setFlags(EnumSet.of(Goal.Flag.MOVE, Goal.Flag.LOOK));
    }

    // Use EYE POSITION for checking breath - much more accurate!
    private boolean canBreathe() {
        // isEyeInFluid(FluidTags.WATER) is a more direct way to check
        return !this.penguin.isEyeInFluid(FluidTags.WATER);
    }

    @Override
    public boolean canUse() {
        // Only use if underwater AND air is low AND can't breathe
        return this.penguin.isUnderWater() &&
                this.penguin.getAirSupply() < AIR_THRESHOLD &&
                !canBreathe();
    }

    @Override
    public boolean canContinueToUse() {
        // Continue until the head is actually out of the water.
        return this.penguin.isUnderWater() && !canBreathe();
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true; // Emergency goal, needs constant updates
    }

    @Override
    public void start() {
        this.targetSurfacePos = findNearestSurface();
    }

    @Override
    public void tick() {
        // Re-evaluate target frequently, or if no target is set
        if (this.targetSurfacePos == null || this.penguin.tickCount % 20 == 0) {
            this.targetSurfacePos = findNearestSurface();
        }

        if (this.targetSurfacePos != null) {
            // Force movement using MoveControl to aim for the surface.
            // MoveControl will tell the entity's movement system where to go.
            this.penguin.getMoveControl().setWantedPosition(
                    this.targetSurfacePos.getX() + 0.5,
                    this.targetSurfacePos.getY() + 0.5, // Aim for the middle of the target block
                    this.targetSurfacePos.getZ() + 0.5,
                    this.speed * 1.5 // Swim fast!
            );
            // Force look direction
            this.penguin.getLookControl().setLookAt(
                    this.targetSurfacePos.getX() + 0.5,
                    this.targetSurfacePos.getY() + 1.0, // Look towards the air above
                    this.targetSurfacePos.getZ() + 0.5
            );
        } else {
            // CRITICAL FALLBACK (No path found, just swim straight up)
            // This is a safety measure to prevent drowning if pathfinding fails.
            this.penguin.getMoveControl().setWantedPosition(
                    this.penguin.getX(),
                    this.penguin.getY() + 5, // Target 5 blocks up from current Y
                    this.penguin.getZ(),
                    this.speed * 1.5
            );
            this.penguin.getLookControl().setLookAt(
                    this.penguin.getX(),
                    this.penguin.getY() + 10, // Look 10 blocks up
                    this.penguin.getZ()
            );
        }

        // FIX: Removed direct velocity injection.
        // The MoveControl combined with the adjusted travel method should handle vertical movement.
        // Direct injection can cause overshooting and conflict with navigation/movecontrol.
        /*
        Vec3 motion = this.penguin.getDeltaMovement();
        if (motion.y < 0.3D) {
            this.penguin.setDeltaMovement(motion.x, motion.y + 0.1D, motion.z);
        }
        */
    }

    @Override
    public void stop() {
        this.penguin.getNavigation().stop();
        this.targetSurfacePos = null;
    }

    @Nullable
    private BlockPos findNearestSurface() {
        Level level = this.penguin.level();
        BlockPos currentPos = this.penguin.blockPosition();

        // Search within a reasonable radius for surface.
        // Start from current Y and go up to a certain height.
        for (int yOffset = 0; yOffset < 15; yOffset++) { // Check up to 15 blocks above
            for (int xOffset = -3; xOffset <= 3; xOffset++) {
                for (int zOffset = -3; zOffset <= 3; zOffset++) {
                    BlockPos checkPos = currentPos.offset(xOffset, yOffset, zOffset);

                    // Check if this position is water and the block above is air (or not water)
                    if (level.getFluidState(checkPos).is(FluidTags.WATER) &&
                            !level.getFluidState(checkPos.above()).is(FluidTags.WATER)) {
                        return checkPos; // Found a water block at the surface
                    }
                }
            }
        }
        return null;
    }
    // checkColumn method is no longer needed with the refined findNearestSurface.
    // This finds the water block that is directly below an air block.
    // That means the entity's head will be out of water if it swims into this block.
}

