```java
package net.mattias.oceancritteria.entity.goals;

import net.mattias.oceancritteria.entity.custom.PenguinEntity;
import net.minecraft.core.BlockPos;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.entity.ai.goal.RandomSwimmingGoal;
import net.minecraft.world.entity.ai.util.DefaultRandomPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;

import javax.annotation.Nullable;

public class PenguinSwimAroundGoal extends RandomSwimmingGoal {
    private final PenguinEntity penguin;

    public PenguinSwimAroundGoal(PenguinEntity penguin, double speedModifier, int interval) {
        super(penguin, speedModifier, interval);
        this.penguin = penguin;
    }

    @Override
    public boolean canUse() {
        if (!this.penguin.isInWater()) {
            return false;
        }
        return super.canUse();
    }

    @Override
    @Nullable
    protected Vec3 getPosition() {
        Vec3 vec3 = DefaultRandomPos.getPos(this.mob, 10, 7);

        // Try multiple times to find a good water position
        for(int i = 0; i < 10; ++i) {
            if (vec3 != null && this.isValidPosition(vec3)) {
                return vec3;
            }
            vec3 = this.generateRandomPos();
        }

        return vec3;
    }

    private Vec3 generateRandomPos() {
        double x = this.penguin.getX() + (this.penguin.getRandom().nextDouble() - 0.5D) * 16.0D;
        double y = this.penguin.getY() + (this.penguin.getRandom().nextDouble() - 0.5D) * 8.0D;
        double z = this.penguin.getZ() + (this.penguin.getRandom().nextDouble() - 0.5D) * 16.0D;

        return new Vec3(x, y, z);
    }

    private boolean isValidPosition(Vec3 pos) {
        BlockPos blockPos = BlockPos.containing(pos);
        Level level = this.penguin.level();

        return level.getFluidState(blockPos).is(FluidTags.WATER) &&
               level.getBlockState(blockPos).isPathfindable(level, blockPos, PathComputationType.WATER);
    }
}
