**PenguinBreatheAirGoal.java** (replaces PenguinGoToSurfaceGoal):
```java
package net.mattias.oceancritteria.entity.goals;

import net.mattias.oceancritteria.entity.custom.PenguinEntity;
import net.minecraft.core.BlockPos;
import net.minecraft.tags.FluidTags;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.pathfinder.Path;
import net.minecraft.world.phys.Vec3;

import java.util.EnumSet;

public class PenguinBreatheAirGoal extends Goal {
    private final PenguinEntity penguin;
    private boolean targetingAir;
    private int ticksSinceStart;
    private BlockPos targetPos;

    public PenguinBreatheAirGoal(PenguinEntity penguin) {
        this.penguin = penguin;
        this.setFlags(EnumSet.of(Goal.Flag.MOVE, Goal.Flag.LOOK, Goal.Flag.JUMP));
    }

    @Override
    public boolean canUse() {
        return this.penguin.getAirSupply() < 600 && this.penguin.isEyeInFluid(FluidTags.WATER);
    }

    @Override
    public boolean canContinueToUse() {
        return this.canUse() && this.ticksSinceStart < 400; // Timeout after 20 seconds
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void start() {
        this.targetingAir = false;
        this.ticksSinceStart = 0;
        this.findAirPosition();
    }

    @Override
    public void stop() {
        this.targetPos = null;
    }

    @Override
    public void tick() {
        this.ticksSinceStart++;

        // Every second, recalculate if needed
        if (this.ticksSinceStart % 20 == 0) {
            this.findAirPosition();
        }

        if (this.targetPos != null) {
            double distance = this.penguin.position().distanceTo(Vec3.atCenterOf(this.targetPos));

            // Use move control for smooth movement
            this.penguin.getMoveControl().setWantedPosition(
                this.targetPos.getX() + 0.5D,
                this.targetPos.getY() + 0.5D,
                this.targetPos.getZ() + 0.5D,
                1.3D
            );

            // If close to target and still underwater, apply upward boost
            if (distance < 3.0D && this.penguin.isEyeInFluid(FluidTags.WATER)) {
                Vec3 motion = this.penguin.getDeltaMovement();
                this.penguin.setDeltaMovement(motion.x, Math.min(0.4D, motion.y + 0.1D), motion.z);
            }
        } else {
            // Emergency: Just swim up
            Vec3 motion = this.penguin.getDeltaMovement();
            this.penguin.setDeltaMovement(motion.x, Math.min(0.4D, motion.y + 0.15D), motion.z);
        }
    }

    private void findAirPosition() {
        Level level = this.penguin.level();
        BlockPos currentPos = this.penguin.blockPosition();

        // Search upward first
        for (int y = 1; y < 20; y++) {
            BlockPos checkPos = currentPos.above(y);
            if (!level.getFluidState(checkPos).is(FluidTags.WATER)) {
                this.targetPos = checkPos.below();
                return;
            }
        }

        // Search in a radius
        for (int xz = 1; xz <= 8; xz++) {
            for (int y = -5; y <= 15; y++) {
                for (int x = -xz; x <= xz; x++) {
                    for (int z = -xz; z <= xz; z++) {
                        if (Math.abs(x) == xz || Math.abs(z) == xz) {
                            BlockPos checkPos = currentPos.offset(x, y, z);
                            if (level.getFluidState(checkPos).is(FluidTags.WATER) &&
                                !level.getFluidState(checkPos.above()).is(FluidTags.WATER)) {
                                this.targetPos = checkPos;
                                return;
                            }
                        }
                    }
                }
            }
        }
    }
}
