package com.example.areartp;

import com.example.areartp.commands.ForceTeleportCommand;
import com.example.areartp.commands.ReloadCommand;
import com.example.areartp.placeholder.TeleportPlaceholderExpansion;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;

@Slf4j
@Getter
public final class AreaRTPPlugin extends JavaPlugin {

    private RTPManager rtpManager;
    private static final MiniMessage MM = MiniMessage.miniMessage();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        reloadEverything();

        // Register commands
        getCommand("areartpreload").setExecutor(new ReloadCommand(this));
        getCommand("areartpnow").setExecutor(new ForceTeleportCommand(this));

        // PlaceholderAPI hook
        if (Bukkit.getPluginManager().isPluginEnabled("PlaceholderAPI")) {
            new TeleportPlaceholderExpansion(this).register();
            log.info("[AreaRTP] PlaceholderAPI detected, hook enabled.");
        }

        log.info("[AreaRTP] Enabled v" + getDescription().getVersion());
    }

    public void reloadEverything() {
        reloadConfig();
        // Cancel previous manager task if live-reloading
        if (rtpManager != null) rtpManager.stop();

        rtpManager = new RTPManager(this);
        rtpManager.start();
    }

    @Override
    public void onDisable() {
        if (rtpManager != null) rtpManager.stop();
        log.info("[AreaRTP] Disabled.");
    }

    public static MiniMessage mm() {
        return MM;
    }
}
