package com.example.areartp;

import com.example.areartp.model.RTPRegion;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.kyori.adventure.text.Component;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.entity.Player;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.scheduler.BukkitTask;

import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.stream.Collectors;

@Slf4j
@RequiredArgsConstructor
public class RTPManager {

    private final AreaRTPPlugin plugin;
    private BukkitTask task;
    private long nextTeleportMillis = 0L;

    private final Random random = ThreadLocalRandom.current();

    // ========= PUBLIC API =========
    public void start() {
        long periodTicks = 1L; // run every tick for accurate same-tick retries
        task = Bukkit.getScheduler().runTaskTimer(plugin, this::tick, 0L, periodTicks);
        nextTeleportMillis = System.currentTimeMillis() + cooldownMillis();
    }

    public void stop() {
        if (task != null) task.cancel();
    }

    public void forceNow() {
        nextTeleportMillis = 0L;
    }

    public long millisUntilTeleport() {
        return Math.max(0L, nextTeleportMillis - System.currentTimeMillis());
    }

    // ========= TICK LOOP =========
    private void tick() {
        if (System.currentTimeMillis() < nextTeleportMillis) return;

        List<Player> inPool = playersInPool();
        if (inPool.isEmpty()) {
            // nobody around, postpone
            nextTeleportMillis = System.currentTimeMillis() + cooldownMillis();
            return;
        }

        attemptGroupTeleport(inPool);
        nextTeleportMillis = System.currentTimeMillis() + cooldownMillis();
    }

    // ========= CORE TELEPORT LOGIC =========
    private void attemptGroupTeleport(final List<Player> group) {
        final World world = Bukkit.getWorld(plugin.getConfig().getString("world"));
        final RTPRegion teleportRegion = toRegion("teleportRegion");
        final int maxY = plugin.getConfig().getInt("maxY", world.getMaxHeight());

        final int minDist = Math.max(1, plugin.getConfig().getInt("minDistance", 3));
        final int maxDist = Math.max(minDist + 1, plugin.getConfig().getInt("maxDistance", 15));

        final Location base = group.get(0).getLocation();

        // Try up to 3 candidate positions **this tick**
        for (int attempt = 0; attempt < 3; attempt++) {

            // Random offset inside [minDist,maxDist]
            double angle = random.nextDouble() * Math.PI * 2D;
            double dist = minDist + random.nextDouble() * (maxDist - minDist);
            int cx = (int) Math.round(base.getX() + dist * Math.cos(angle));
            int cz = (int) Math.round(base.getZ() + dist * Math.sin(angle));

            // Ensure inside global teleport region
            if (cx < teleportRegion.getMinX() || cx > teleportRegion.getMaxX()
             || cz < teleportRegion.getMinZ() || cz > teleportRegion.getMaxZ()) {
                continue;
            }

            // Surface Y
            int y = world.getHighestBlockYAt(cx, cz);
            if (y > maxY) continue;

            Location candidate = new Location(world, cx + 0.5, y + 1, cz + 0.5, base.getYaw(), base.getPitch());

            // ✓ block-event claim test
            List<Player> failed = claimTest(candidate, group);
            if (failed.size() == 0) {
                teleport(group, candidate);
                return;
            }

            if (failed.size() == 1) {
                // Retry that single player (same tick) up to 2 extra random positions
                Player unlucky = failed.get(0);
                for (int tries = 0; tries < 2; tries++) {
                    Location single = randomLocationInside(world, teleportRegion, maxY);
                    if (single == null) break;
                    if (claimTest(single, Collections.singletonList(unlucky)).isEmpty()) {
                        unlucky.teleportAsync(single);
                        unlucky.sendMessage(Component.text("You were teleported separately due to land claims."));
                        break;
                    }
                }
                // others were already teleported
                group.stream().filter(p -> p != unlucky).forEach(p -> p.teleportAsync(candidate));
                return;
            }
            // >1 failed → pick a completely new group position inside loop
        }
    }

    // Makes sure events are **not** cancelled for ANY player
    private List<Player> claimTest(final Location loc, final List<Player> testers) {

        final Block surface = loc.getBlock();
        final BlockData beforePlaceData = surface.getBlockData();
        final Block replaced = surface;

        List<Player> failed = new ArrayList<>();

        for (Player p : testers) {

            BlockBreakEvent breakEv = new BlockBreakEvent(replaced, p);
            Bukkit.getPluginManager().callEvent(breakEv);

            BlockPlaceEvent placeEv = new BlockPlaceEvent(
                    replaced,
                    replaced.getState(),
                    replaced,
                    new ItemStack(Material.AIR),
                    p,
                    true,
                    EquipmentSlot.HAND);
            Bukkit.getPluginManager().callEvent(placeEv);

            if (breakEv.isCancelled() || placeEv.isCancelled()) {
                failed.add(p);
            }
        }

        // restore any blockdata we might have touched (we did not actually change it, but safe)
        surface.setBlockData(beforePlaceData, false);
        return failed;
    }

    private void teleport(final List<Player> players, final Location target) {
        Component msg = AreaRTPPlugin.mm().deserialize("<green>Whoosh!</green>");
        players.forEach(p -> {
            p.teleportAsync(target);
            p.sendMessage(msg);
        });
    }

    private List<Player> playersInPool() {
        RTPRegion pool = toRegion("poolRegion");
        World world = Bukkit.getWorld(plugin.getConfig().getString("world"));
        return world.getPlayers().stream()
                .filter(p -> pool.contains(p.getLocation()))
                .collect(Collectors.toList());
    }

    private RTPRegion toRegion(final String path) {
        return new RTPRegion(
                plugin.getConfig().getInt(path + ".minX"),
                plugin.getConfig().getInt(path + ".minZ"),
                plugin.getConfig().getInt(path + ".maxX"),
                plugin.getConfig().getInt(path + ".maxZ")
        );
    }

    private long cooldownMillis() {
        return plugin.getConfig().getLong("cooldownSeconds", 300L) * 1000L;
    }

    private Location randomLocationInside(final World world, final RTPRegion region, final int maxY) {
        for (int tries = 0; tries < 16; tries++) {
            int x = region.randomX(random);
            int z = region.randomZ(random);
            int y = world.getHighestBlockYAt(x, z);
            if (y > maxY) continue;
            return new Location(world, x + 0.5, y + 1, z + 0.5);
        }
        return null;
    }
}
