    }

    @Override
    public @NotNull String getAuthor() {
        return "YourName";
    }

    @Override
    public @NotNull String getVersion() {
        return plugin.getDescription().getVersion();
    }

    // %areartp_time%  ▸ time until next teleport
    // %areartp_players% ▸ players currently in pool
    @Override
    public String onPlaceholderRequest(Player p, @NotNull String params) {

        switch (params.toLowerCase()) {
            case "time": {
                long ms = plugin.getRtpManager().millisUntilTeleport();
                long s = TimeUnit.MILLISECONDS.toSeconds(ms);
                long m = s / 60;
                long r = s % 60;
                return "&a" + String.format("%02d:%02d", m, r);
            }
            case "players": {
                return plugin.getRtpManager().playersInPool().stream()
                        .map(Player::getName)
                        .collect(Collectors.joining(", "));
            }
            default:
                return "";
        }
    }
}
