package com.example.areartp;

import com.example.areartp.commands.ReloadCommand;
import com.example.areartp.commands.RTPNowCommand;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.kyori.adventure.platform.bukkit.BukkitAudiences;
import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;

@Getter
@Slf4j
public final class AreaRTP extends JavaPlugin {

    private static AreaRTP instance;
    private BukkitAudiences adventure;
    private AreaRTPConfig configData;
    private AreaRTPManager manager;

    @Override
    public void onEnable() {
        instance = this;
        saveDefaultConfig();
        reloadConfigData();

        adventure = BukkitAudiences.create(this);

        manager = new AreaRTPManager(this);
        manager.start();

        // Register commands
        getCommand("areartp-reload").setExecutor(new ReloadCommand(this));
        getCommand("areartp-now").setExecutor(new RTPNowCommand(this));

        // Register PlaceholderAPI expansion
        if (Bukkit.getPluginManager().isPluginEnabled("PlaceholderAPI")) {
            new AreaRTPPlaceholderExpansion(this).register();
            log.info("PlaceholderAPI expansion registered.");
        }

        log.info("AreaRTP enabled.");
    }

    @Override
    public void onDisable() {
        if (adventure != null) {
            adventure.close();
        }
        if (manager != null) {
            manager.stop();
        }
        log.info("AreaRTP disabled.");
    }

    public void reloadConfigData() {
        reloadConfig();
        configData = new AreaRTPConfig(getConfig());
        if (manager != null) {
            manager.reload();
        }
    }

    public static AreaRTP getInstance() {
        return instance;
    }
}
