### 5.3 `AreaRTPManager.java` (Core Logic)

```java
package com.example.areartp;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.entity.Player;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.scheduler.BukkitRunnable;
import org.jetbrains.annotations.NotNull;

import java.util.*;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.stream.Collectors;

@Slf4j
@RequiredArgsConstructor
public class AreaRTPManager {

    private final AreaRTP plugin;
    @Getter
    private final Set<UUID> areaPlayers = new CopyOnWriteArraySet<>();
    private BukkitRunnable task;
    private long nextTeleportTime = 0L;

    public void start() {
        stop();
        task = new BukkitRunnable() {
            @Override
            public void run() {
                try {
                    tick();
                } catch (Exception e) {
                    log.error("Error in AreaRTPManager tick", e);
                }
            }
        };
        task.runTaskTimer(plugin, 0L, 20L); // every second
        nextTeleportTime = System.currentTimeMillis() + plugin.getConfigData().getRtpIntervalSeconds() * 1000L;
    }

    public void stop() {
        if (task != null) {
            task.cancel();
            task = null;
        }
    }

    public void reload() {
        stop();
        start();
    }

    public long getTimeUntilNextTeleportMillis() {
        return Math.max(0, nextTeleportTime - System.currentTimeMillis());
    }

    public List<Player> getPlayersInArea() {
        final World world = Bukkit.getWorld(plugin.getConfigData().getWorld());
        if (world == null) return Collections.emptyList();
        return Bukkit.getOnlinePlayers().stream()
                .filter(p -> p.getWorld().equals(world))
                .filter(this::isInArea)
                .collect(Collectors.toList());
    }

    public boolean isInArea(@NotNull Player player) {
        final AreaRTPConfig cfg = plugin.getConfigData();
        final Location loc = player.getLocation();
        return loc.getWorld().getName().equals(cfg.getWorld())
                && loc.getBlockX() >= cfg.getAreaMinX()
                && loc.getBlockX() <= cfg.getAreaMaxX()
                && loc.getBlockZ() >= cfg.getAreaMinZ()
                && loc.getBlockZ() <= cfg.getAreaMaxZ();
    }

    private void tick() {
        // Update areaPlayers
        areaPlayers.clear();
        getPlayersInArea().forEach(p -> areaPlayers.add(p.getUniqueId()));

        if (System.currentTimeMillis() >= nextTeleportTime) {
            if (!areaPlayers.isEmpty()) {
                teleportAreaPlayers();
            }
            nextTeleportTime = System.currentTimeMillis() + plugin.getConfigData().getRtpIntervalSeconds() * 1000L;
        }
    }

    public void forceTeleportNow() {
        if (!areaPlayers.isEmpty()) {
            teleportAreaPlayers();
        }
        nextTeleportTime = System.currentTimeMillis() + plugin.getConfigData().getRtpIntervalSeconds() * 1000L;
    }

    private void teleportAreaPlayers() {
        final List<Player> players = getPlayersInArea();
        if (players.isEmpty()) return;

        final AreaRTPConfig cfg = plugin.getConfigData();
        final World world = Bukkit.getWorld(cfg.getWorld());
        if (world == null) return;

        // Try up to 3 positions per tick
        for (int attempt = 0; attempt < 3; attempt++) {
            final Location target = findValidRTPPosition(world, cfg, players);
            if (target == null) continue;

            // Fire block break/place events for all players
            boolean allAllowed = true;
            final List<Player> failedPlayers = new ArrayList<>();
            for (final Player player : players) {
                if (!canTeleportHere(player, target)) {
                    allAllowed = false;
                    failedPlayers.add(player);
                }
            }
            if (allAllowed) {
                // Teleport all
                for (final Player player : players) {
                    player.teleportAsync(target).thenAccept(success -> {
                        if (success) {
                            plugin.getAdventure().player(player).sendMessage(MiniMessage.miniMessage().deserialize("<green>Teleported!</green>"));
                        } else {
                            plugin.getAdventure().player(player).sendMessage(MiniMessage.miniMessage().deserialize("<red>Teleport failed!</red>"));
                        }
                    });
                }
                return;
            } else if (failedPlayers.size() == 1) {
                // Retry for that player only, others teleport
                final Player failed = failedPlayers.get(0);
                final List<Player> allowed = new ArrayList<>(players);
                allowed.remove(failed);
                for (final Player player : allowed) {
                    player.teleportAsync(target).thenAccept(success -> {
                        if (success) {
                            plugin.getAdventure().player(player).sendMessage(MiniMessage.miniMessage().deserialize("<green>Teleported!</green>"));
                        } else {
                            plugin.getAdventure().player(player).sendMessage(MiniMessage.miniMessage().deserialize("<red>Teleport failed!</red>"));
                        }
                    });
                }
                // Try to find a valid position for the failed player only
                for (int retry = 0; retry < 3; retry++) {
                    final Location retryLoc = findValidRTPPosition(world, cfg, Collections.singletonList(failed));
                    if (retryLoc != null && canTeleportHere(failed, retryLoc)) {
                        failed.teleportAsync(retryLoc).thenAccept(success -> {
                            if (success) {
                                plugin.getAdventure().player(failed).sendMessage(MiniMessage.miniMessage().deserialize("<green>Teleported!</green>"));
                            } else {
                                plugin.getAdventure().player(failed).sendMessage(MiniMessage.miniMessage().deserialize("<red>Teleport failed!</red>"));
                            }
                        });
                        break;
                    }
                }
                return;
            }
            // else, try another position for all
        }
        // If we get here, failed to find a valid position
        for (final Player player : players) {
            plugin.getAdventure().player(player).sendMessage(MiniMessage.miniMessage().deserialize("<red>Failed to find a safe RTP location!</red>"));
        }
    }

    private Location findValidRTPPosition(@NotNull World world, @NotNull AreaRTPConfig cfg, @NotNull List<Player> players) {
        for (int tries = 0; tries < 10; tries++) {
            final int x = random(cfg.getRtpMinX(), cfg.getRtpMaxX());
            final int z = random(cfg.getRtpMinZ(), cfg.getRtpMaxZ());
            final int y = world.getHighestBlockYAt(x, z);
            if (y > cfg.getMaxY()) continue;
            final Block block = world.getBlockAt(x, y - 1, z);
            if (!block.getType().isSolid()) continue;
            final Location loc = new Location(world, x + 0.5, y, z + 0.5);
            // Check min/max distance for all players
            boolean valid = true;
            for (final Player player : players) {
                final Location ploc = player.getLocation();
                final double dist = ploc.distance(loc);
                if (dist < cfg.getMinDistance() || dist > cfg.getMaxDistance()) {
                    valid = false;
                    break;
                }
            }
            if (valid) return loc;
        }
        return null;
    }

    private int random(int min, int max) {
        return min + (int) (Math.random() * (max - min + 1));
    }

    private boolean canTeleportHere(@NotNull Player player, @NotNull Location loc) {
        // Fire block break and place events at the target location
        final Block block = loc.getBlock();
        final BlockBreakEvent breakEvent = new BlockBreakEvent(block, player);
        final BlockPlaceEvent placeEvent = new BlockPlaceEvent(block, block.getState(), block, null, player, true, null);
        Bukkit.getPluginManager().callEvent(breakEvent);
        Bukkit.getPluginManager().callEvent(placeEvent);
        return !breakEvent.isCancelled() && !placeEvent.isCancelled();
    }
}
