// Function to create a tapered box (for main beams and rafters)
function createTaperedBox(length, height, thickness, overhang, taperHeight) {
    const geometry = new THREE.BoxGeometry(length, height, thickness);

    // Calculate taper
    const taperLength = overhang;
    const vertices = geometry.attributes.position.array;
    for (let i = 0; i < vertices.length; i += 3) {
