                const factor = (vertices[i] + length / 2) / taperLength;
                vertices[i + 1] = -height / 2 * (taperHeight + (1 - taperHeight) * factor);
            } else if (vertices[i] > length / 2 - taperLength) {
                // Right taper
                const factor = (length / 2 - vertices[i]) / taperLength;
                vertices[i + 1] = -height / 2 * (taperHeight + (1 - taperHeight) * factor);
            }
        }
    }
    geometry.attributes.position.needsUpdate = true;
    geometry.computeVertexNormals();

    const mesh = new THREE.Mesh(geometry, woodMaterial);
    return mesh;
