    <script>
        // --- Scene Setup ---
        const scene = new THREE.Scene();
        // A light sky blue background
        scene.background = new THREE.Color(0xcce0ff); 

        // --- Constants for Pergola Dimensions and Positions (in feet) ---
        const postHeight = 8.0;
        const postSpanX = 9.0;  // Width of the pergola along X axis (between posts)
        const postSpanZ = 6.0;  // Depth of the pergola along Z axis (between posts)
        const overhang = 1.5;   // Overhang for beams and rafters at each end

        // Nominal lumber dimensions converted to feet
        // (Actual dimensions are slightly smaller than nominal)
        const postDim = 3.5 / 12.0;       // Nominal 4x4: 3.5 inches / 12 inches/foot
        const beamHeight = 7.25 / 12.0;   // Nominal 2x8: 7.25 inches / 12
        const beamThickness = 1.5 / 12.0; // Nominal 2x8: 1.5 inches / 12 (thickness along Z for beams along X)
        const rafterHeight = 3.5 / 12.0;  // Nominal 2x4: 3.5 inches / 12
        const rafterThickness = 1.5 / 12.0; // Nominal 2x4: 1.5 inches / 12 (thickness along X for rafters along Z)
        const purlinDim = 1.5 / 12.0;     // Nominal 2x2: 1.5 inches / 12 (width/depth for purlins)

        // Calculate derived dimensions
        const beamTotalLength = postSpanX + 2 * overhang; // Total length of main beams along X
        const rafterTotalLength = postSpanZ + 2 * overhang; // Total length of rafters along Z

        // Material for all wood components
        const woodMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513 }); // SaddleBrown

        // --- Helper Function to Create Tapered Beam/Rafter Geometry ---
        // This function creates a prism with a linearly varying cross-section along a primary axis.
        // It's used for the main beams and rafters which have a decorative taper on the overhangs.
        function createTaperedBeamGeometry(length, centerSpan, overhang, yTop, yBotCenter, yBotEnd, thickness, primaryAxis, offset) {
            const geometry = new THREE.BufferGeometry();
            const points = []; // Stores vertex coordinates {x,y,z}
            const indices = [];

            // Define points along the primary axis (where cross-sections are defined)
            // These points mark the transitions: start, center-start, center-end, end
            const axisPoints = [-length / 2, -centerSpan / 2, centerSpan / 2, length / 2];

            // Define corresponding bottom Y coordinates for these cross-sections.
            // The bottom edge is flat in the center span and tapers upwards (Y increases) at the overhang ends.
            // The height is reduced to 35% of original at the overhang ends, meaning the bottom Y is higher.
            // yBotEnd = yTop - (0.35 * beamHeight) => yBotEnd = (yBotCenter + beamHeight) - 0.35*beamHeight => yBotEnd = yBotCenter + 0.65*beamHeight
            const yBottoms = [yBotEnd, yBotCenter, yBotCenter, yBotEnd];

            const verticesPerSection = 4; // Each cross-section has 4 vertices: top-front, bottom-front, top-back, bottom-back

            // Generate vertices for each of the 4 cross-sections
            for (let i = 0; i < axisPoints.length; i++) {
                const axisVal = axisPoints[i]; // The coordinate along the primary axis (X or Z)
                const yBot = yBottoms[i];      // The Y coordinate of the bottom edge at this section

                let v1, v2, v3, v4; // Define the 4 vertices of the cross-section

                if (primaryAxis === 'x') {
                    // Primary axis is X, thickness is along Z. The 'offset' is the constant Z coordinate.
                    // Vertices are defined in the YZ plane at a specific X (axisVal).
                    v1 = { x: axisVal, y: yTop, z: thickness / 2 + offset }; // Top-front
                    v2 = { x: axisVal, y: yBot, z: thickness / 2 + offset }; // Bottom-front
                    v3 = { x: axisVal, y: yTop, z: -thickness / 2 + offset };// Top-back
                    v4 = { x: axisVal, y: yBot, z: -thickness / 2 + offset };// Bottom-back
                } else { // primaryAxis === 'z'
                    // Primary axis is Z, thickness is along X. The 'offset' is the constant X coordinate.
                    // Vertices are defined in the XY plane at a specific Z (axisVal).
                    v1 = { x: offset, y: yTop, z: axisVal };                      // Top-front (relative to X-axis perspective)
                    v2 = { x: offset, y: yBot, z: axisVal };                      // Bottom-front
                    v3 = { x: offset - thickness, y: yTop, z: axisVal };         // Top-back (thickness subtracted along X)
                    v4 = { x: offset - thickness, y: yBot, z: axisVal };         // Bottom-back (thickness subtracted along X)
                }
                points.push(v1, v2, v3, v4);
            }

            // Generate indices for triangles connecting adjacent cross-sections.
            // We connect the 4 vertices of section 'i' to the 4 vertices of section 'i+1'.
            // Each quad face is split into two triangles.
            for (let i = 0; i < axisPoints.length - 1; i++) {
                const currentBase = i * verticesPerSection;       // Index of the first vertex of the current cross-section
                const nextBase = (i + 1) * verticesPerSection; // Index of the first vertex of the next cross-section

                // Connect vertices to form faces:
                // Top face (quad formed by v0, v2, next_v2, next_v0)
                indices.push(currentBase + 0, currentBase + 2, nextBase + 2); // Triangle 1
                indices.push(currentBase + 0, nextBase + 2, nextBase + 0);   // Triangle 2

                // Bottom face (quad formed by v1, v3, next_v3, next_v1)
                indices.push(currentBase + 1, nextBase + 1, nextBase + 3); // Triangle 1
                indices.push(currentBase + 1, nextBase + 3, currentBase + 3); // Triangle 2

                // Front face (quad formed by v0, v1, next_v1, next_v0) - side along the primary axis
                indices.push(currentBase + 0, currentBase + 1, nextBase + 1); // Triangle 1
                indices.push(currentBase + 0, nextBase + 1, nextBase + 0);   // Triangle 2

                // Back face (quad formed by v2, v3, next_v3, next_v2) - opposite side along the primary axis
                indices.push(currentBase + 2, nextBase + 2, nextBase + 3); // Triangle 1
                indices.push(currentBase + 2, nextBase + 3, currentBase + 3); // Triangle 2
            }

            // Convert the array of {x,y,z} objects into a Float32Array for the BufferAttribute
            const positionArray = new Float32Array(points.length * 3);
            for (let i = 0; i < points.length; i++) {
                positionArray[i * 3] = points[i].x;
                positionArray[i * 3 + 1] = points[i].y;
                positionArray[i * 3 + 2] = points[i].z;
            }

            geometry.setAttribute('position', new THREE.BufferAttribute(positionArray, 3));
            geometry.setIndex(indices);
            geometry.computeVertexNormals(); // Important for correct lighting and shading

            return geometry;
        }

        // --- Initialize Scene, Camera, Renderer, Controls ---
        function init() {
            // Camera
            const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(15, 15, 15); // Position for a good overview of the pergola
            camera.lookAt(0, 0, 0); // Look towards the center of the scene

            // Renderer
