            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.shadowMap.enabled = true; // Enable shadows for a more realistic look
            document.body.appendChild(renderer.domElement);

            // Controls for camera manipulation (orbit, zoom, pan)
