            scene.add(ambientLight);

            // Directional light simulates sunlight
            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(5, 10, 7); // Position the light source
            directionalLight.castShadow = true; // Enable shadows for this light

            // Configure shadow properties for better quality (optional but recommended)
            directionalLight.shadow.mapSize.width = 1024;
            directionalLight.shadow.mapSize.height = 1024;
            directionalLight.shadow.camera.near = 0.5;
            directionalLight.shadow.camera.far = 50;
            directionalLight.shadow.focus = 1; // Focus for soft shadows
            scene.add(directionalLight);

            // --- Add Scene Elements ---

            // Ground Plane
            const groundSize = 25; // The ground plane extends 12.5 feet in each direction from center
            const groundGeo = new THREE.PlaneGeometry(groundSize, groundSize);
            const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // ForestGreen for grass
            const groundMesh = new THREE.Mesh(groundGeo, groundMat);
            groundMesh.rotation.x = -Math.PI / 2; // Rotate the plane to be horizontal (Y-axis is up)
            groundMesh.position.y = 0; // Place it at the base of the structure
            groundMesh.receiveShadow = true; // The ground should receive shadows cast by the pergola
            scene.add(groundMesh);

            // --- Pergola Construction ---

            // 1. Posts (4 count)
            const postGeo = new THREE.BoxGeometry(postDim, postHeight, postDim); // Width, Height, Depth

            // Define the positions for the four posts to form a 9ft x 6ft rectangle
            const postPositions = [
                { x: -postSpanX / 2, z: -postSpanZ / 2 }, // Corner 1 (Front-Left)
                { x:  postSpanX / 2, z: -postSpanZ / 2 }, // Corner 2 (Front-Right)
                { x: -postSpanX / 2, z:  postSpanZ / 2 }, // Corner 3 (Back-Left)
                { x:  postSpanX / 2, z:  postSpanZ / 2 }  // Corner 4 (Back-Right)
            ];

            for (const pos of postPositions) {
                const postMesh = new THREE.Mesh(postGeo, woodMaterial);
                // Position the center of the post geometry. Since BoxGeometry is centered,
                // its center is at height/2, so we set Y to postHeight/2 to place the base at Y=0.
                postMesh.position.set(pos.x, postHeight / 2, pos.z);
                postMesh.castShadow = true; // Posts should cast shadows
                scene.add(postMesh);
            }

            // 2. Main Beams (2 count) - Run along the X-axis
            // The beams sit on top of the posts.
