            const Y_top_beam = postHeight + beamHeight;
            const Y_bot_beam_center = postHeight;
            const Y_bot_beam_end = postHeight + (1.0 - 0.35) * beamHeight;

            // Create the geometry for one main beam
            const mainBeamGeometry = createTaperedBeamGeometry(
                beamTotalLength,      // total length along primary axis (X)
                postSpanX,            // span between posts along primary axis (X)
                overhang,             // overhang length
                Y_top_beam,           // Y coordinate of the top surface
                Y_bot_beam_center,    // Y coordinate of the bottom surface in the center span
                Y_bot_beam_end,       // Y coordinate of the bottom surface at the overhang ends
                beamThickness,        // thickness of the beam (along Z axis)
                'x',                  // primary axis of extrusion is X
                0                     // offset value for the thickness axis (Z is centered at 0)
            );

            // Create two main beams, one on each side of the Z-span
            const beam1 = new THREE.Mesh(mainBeamGeometry, woodMaterial);
            // Position beam1: centered at X=0, and offset along Z to one side of the posts.
            beam1.position.set(0, 0, -postSpanZ / 2); 
            beam1.castShadow = true;
            scene.add(beam1);

            const beam2 = new THREE.Mesh(mainBeamGeometry, woodMaterial);
            // Position beam2: centered at X=0, and offset along Z to the other side of the posts.
            beam2.position.set(0, 0, postSpanZ / 2); 
            beam2.castShadow = true;
            scene.add(beam2);


            // 3. Rafters (7 count) - Run along the Z-axis
            // Rafters are spaced along the X-axis, resting on the main beams.
            // Their total length is 9ft (6ft span + 2x1.5ft overhang).

            // Calculate the X positions for the 7 rafters.
            // They are spaced evenly along the total length of the main beams (12ft from -6ft to 6ft).
            const rafter_xPositions = []; 
            for (let i = 0; i < 7; i++) {
                // The spacing is calculated based on the total span divided by the number of gaps (7 rafters = 6 gaps)
                const xPos = -beamTotalLength / 2 + i * (beamTotalLength / 6);
                rafter_xPositions.push(xPos);
            }

            // Define the Y coordinates for the rafters' top and bottom surfaces.
            // Rafters sit on top of the main beams.
            // Y_top_rafter = Y_top_beam + rafterHeight (top of beam + rafter height)
            // Y_bot_rafter_center = Y_top_beam (bottom of rafter sits on top of beam)
            // Y_bot_rafter_end = Y_top_beam + (1.0 - 0.35) * rafterHeight (tapered relief for overhangs)
            const Y_top_rafter = Y_top_beam + rafterHeight;
            const Y_bot_rafter_center = Y_top_beam;
            const Y_bot_rafter_end = Y_top_beam + (1.0 - 0.35) * rafterHeight;

            // Create each of the 7 rafters
            for (const xPos of rafter_xPositions) {
                const rafterGeo = createTaperedBeamGeometry(
                    rafterTotalLength,    // total length along primary axis (Z)
                    postSpanZ,            // span between beams along primary axis (Z)
                    overhang,             // overhang length
                    Y_top_rafter,         // Y coordinate of the top surface
                    Y_bot_rafter_center,  // Y coordinate of the bottom surface in the center span
                    Y_bot_rafter_end,     // Y coordinate of the bottom surface at the overhang ends
                    rafterThickness,      // thickness of the rafter (along X axis)
                    'z',                  // primary axis of extrusion is Z
                    xPos                  // offset value for the thickness axis (X is constant for this rafter)
                );
                const rafterMesh = new THREE.Mesh(rafterGeo, woodMaterial);
                rafterMesh.castShadow = true;
                scene.add(rafterMesh);
            }

            // 4. Purlins (7 count) - Run along the X-axis
            // Purlins are spaced along the Z-axis, resting on top of the rafters.
            // Their total length is 12ft (matching the main beams).

            // Calculate the Z positions for the 7 purlins.
            // They are spaced evenly along the total length of the rafters (9ft from -4.5ft to 4.5ft).
            const purlin_zPositions = []; 
            for (let i = 0; i < 7; i++) {
                // The spacing is calculated based on the rafter span (9ft) divided by number of gaps (6)
                const zPos = -postSpanZ / 2 + i * (postSpanZ / 6);
                purlin_zPositions.push(zPos);
            }

            // Purlins have a simple rectangular cross-section (nominal 2x2 = 1.5/12 in all directions).
            const purlinHeight = purlinDim;       // Dimension along Y
            const purlinLength = beamTotalLength; // Length along X (12.0 ft)
            const purlinThickness = purlinDim;    // Dimension along Z

            // Create a standard box geometry for the purlins
            const purlinGeo = new THREE.BoxGeometry(purlinLength, purlinHeight, purlinThickness);

            // Create each of the 7 purlins
            for (const zPos of purlin_zPositions) {
                const purlinMesh = new THREE.Mesh(purlinGeo, woodMaterial);
                // Position the purlins on top of the rafters.
                // The center Y coordinate is the top of the rafters plus half the purlin height.
                const purlinCenterY = Y_top_rafter + purlinHeight / 2;
                // Position the purlin: centered at X=0, and positioned along Z according to zPos.
                purlinMesh.position.set(0, purlinCenterY, zPos); 
                purlinMesh.castShadow = true;
                scene.add(purlinMesh);
            }

            // --- Animation Loop ---
            function animate() {
                requestAnimationFrame(animate); // Request the next frame
                controls.update(); // Update controls if damping is enabled
                renderer.render(scene, camera); // Render the scene
            }

