void Speed_Control_Loop(void) {
    uint32_t now = HAL_GetTick();
    if (now - last_speed_ctrl_tick < 10) return; // run every 10ms
    last_speed_ctrl_tick = now;

    // PI Controller
    float error = target_rpm - rpm;
    integrator += error * 0.01f; // dt = 10ms = 0.01s
    float u = Kp * error + Ki * integrator;

    // Convert to duty %
    if (u < 0) u = 0;
    if (u > 95) u = 95;
    duty_out = (uint16_t)u;
    if (motor_state != MOTOR_STATE_CLOSED_LOOP) {
     	uint32_t now = HAL_GetTick();
     	if ((now - last_current_ctrl_tick) >= I_CTRL_DT_MS) {
     	uint32_t dt = now - last_current_ctrl_tick;
     	if (last_current_ctrl_tick == 0) dt = I_CTRL_DT_MS; // first-run
     	last_current_ctrl_tick = now;
     	CurrentControl_Loop(dt);
     	}
       }
    Motor_SetDuty(duty_out);
}
void CurrentControl_Loop(uint32_t dt_ms) {
if (dt_ms == 0) return;


// Only run current control when motor is closed-loop running and no system fault
if (motor_state != MOTOR_STATE_CLOSED_LOOP || system_fault != SYS_FAULT_NONE || !motor_running) {
    // reset integrator and don't drive outputs
    i_integral = 0.0f;
    current_control_duty = 0.0f;
    return;
}

float dt_s = ((float)dt_ms) * 0.001f;
i_error = I_ref - IDC;
float p_term = I_CTRL_KP * i_error;
i_integral += (I_CTRL_KI * i_error) * dt_s;

if (i_integral > I_CTRL_INTEGRAL_MAX) i_integral = I_CTRL_INTEGRAL_MAX;
if (i_integral < I_CTRL_INTEGRAL_MIN) i_integral = I_CTRL_INTEGRAL_MIN;

float u = p_term + i_integral; // duty percent target
if (u > 95.0f) u = 95.0f;
if (u < 0.0f) u = 0.0f;
current_control_duty = u;
Motor_SetDuty((uint16_t)current_control_duty);
}
