static inline float ADC_TO_PHASE_VOLTAGE(uint16_t adc_value) {
    const float DIVIDER_RATIO = ((float)R1 + (float)R2) / (float)R2;
    return ((float)adc_value * conv / (float)(adc_cmax)) * DIVIDER_RATIO;
}
static inline float ADC_TO_DC_BUS_VOLTAGE(uint16_t adc_value) {
    const float DIVIDER_RATIO = ((float)R1 + (float)R2) / (float)R2;
    return ((float)adc_value * conv / (float)(adc_cmax)) * DIVIDER_RATIO;
}
static inline float ADC_TO_SHUNT_CURRENT(uint16_t adc_value) {
    const float SHUNT_RESISTANCE = 0.015f;
    const float GAIN = (float)Rf / (float)Rg;
    float voltage = (float)adc_value * conv / (float)(adc_cmax);
    float shunt_voltage = (voltage / GAIN) - dc_offset_opamp;
    return shunt_voltage / SHUNT_RESISTANCE;
}

static inline float ApplyEMA(float new_sample, float old_value, float alpha) {
    return alpha * new_sample + (1.0f - alpha) * old_value;
}
static inline float lpf1(float x, float y_prev, float dt_ms, float fc_hz) {
    if (dt_ms <= 0.0f) return y_prev;
    if (fc_hz <= 0.0f) return x;
    const float PI = 3.14159265358979323846f;
    float dt_s = dt_ms * 0.001f;
    float tau_s = 1.0f / (2.0f * PI * fc_hz);
    float alpha = dt_s / (tau_s + dt_s);
    if (alpha < 0.0f) alpha = 0.0f;
    if (alpha > 1.0f) alpha = 1.0f;
    return y_prev + alpha * (x - y_prev);
}

/* ---------------- Speed & Commutation ---------------- */
void UpdateSpeedOnCommutation(void) {
static uint32_t last_tick = 0;
uint32_t now = HAL_GetTick(); // ms

if (last_tick != 0) {
    uint32_t dt_ms = now - last_tick;
    if (dt_ms > 0 && dt_ms < 2000) {
        float rpm_inst = 60000.0f / ((float)dt_ms * 6.0f * (float)MOTOR_POLE_PAIRS);
        rpm = lpf1(rpm_inst, rpm, (float)dt_ms, RPM_LPF_CUTOFF_HZ);
    }
} else {
    rpm = 0.0f;
}

last_tick = now;
last_comm_tick = now;   // <<< ADDED
}

float GetRotorElectricalAngle(void) {
    uint32_t dt_ms = HAL_GetTick() - last_comm_tick;
    if (rpm <= 0.1f) return rotor_elec_angle;
    float sector_time_ms = (1000.0f * 60.0f) / (rpm * 6.0f * MOTOR_POLE_PAIRS);
    float fraction = fminf((float)dt_ms / sector_time_ms, 1.0f);
    return rotor_elec_angle + fraction * 60.0f;
}
float GetRotorMechanicalAngle(void) {
    float elec_angle = fmodf(GetRotorElectricalAngle(), 360.0f);
    return elec_angle / MOTOR_POLE_PAIRS;
}

/* ---------------- Error Detection ---------------- */
void CheckSystemAndMotorErrors(void) {
    float v = VDC;
    float i_abs_max = fmaxf(fmaxf(fabsf(ShuntI_a), fabsf(ShuntI_b)), fabsf(IDC));
    uint32_t now = HAL_GetTick();

    if (system_fault == SYS_FAULT_NONE && motor_state == MOTOR_STATE_CLOSED_LOOP) {
        if (v < sys_cfg.undervoltage_th) {
            Motor_Stop(); motor_state = MOTOR_STATE_STOPPED;
            system_fault = SYS_FAULT_UNDERVOLT; rpm = 0; fault_detect_time = now;
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_13, GPIO_PIN_SET);
        }
        else if (v > sys_cfg.overvoltage_th) {
            Motor_Stop(); motor_state = MOTOR_STATE_STOPPED;
            system_fault = SYS_FAULT_OVERVOLT; rpm = 0; fault_detect_time = now;
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_13, GPIO_PIN_SET);
        }
        else if (i_abs_max > sys_cfg.overcurrent_th) {
            Motor_Stop(); motor_state = MOTOR_STATE_STOPPED;
            system_fault = SYS_FAULT_OVERCURRENT; rpm = 0;
            HAL_GPIO_WritePin(GPIOD, GPIO_PIN_13, GPIO_PIN_SET);
        }
    }
}
void Error_Recovery(void) {
    uint32_t now = HAL_GetTick();
    if ((system_fault == SYS_FAULT_UNDERVOLT || system_fault == SYS_FAULT_OVERVOLT) && fault_detect_time > 0) {
    	if ((now - fault_detect_time) >= sys_cfg.recover_time) {
    	    if (VDC >= sys_cfg.undervoltage_th && VDC <= sys_cfg.overvoltage_th) {
                HAL_GPIO_WritePin(GPIOD, GPIO_PIN_13, GPIO_PIN_RESET);
                system_fault = SYS_FAULT_NONE; fault_detect_time = 0;
                Motor_Start(); motor_state = MOTOR_STATE_ALIGN;
                Motor_Align(30, 2000); motor_state = MOTOR_STATE_OPEN_LOOP;
                Motor_OpenLoopStartup(&myMotorParams);
            } else {
                fault_detect_time = now;
            }
        }
    }
}

/* ---------------- Button ---------------- */
void Button_Init(GPIO_TypeDef* port, uint16_t pin, uint32_t debounce_ms, ButtonCallback cb) {
    btn_port = port; btn_pin = pin; btn_debounce = debounce_ms; btn_callback = cb;
    btn_last_tick = HAL_GetTick();
}
void Button_Process(void) {
    uint32_t now = HAL_GetTick();
    if (now - btn_last_tick < btn_debounce) return;
    btn_last_tick = now;
    GPIO_PinState ps = HAL_GPIO_ReadPin(btn_port, btn_pin);
    if (btn_state == 1 && ps == GPIO_PIN_RESET) {
        btn_state = 0; HAL_GPIO_TogglePin(GPIOD, GPIO_PIN_15);
        if (btn_callback) btn_callback();
    } else if (btn_state == 0 && ps == GPIO_PIN_SET) {
        btn_state = 1;
    }
}
/* ---------------- Motor Control ---------------- */

float alpha = 0.1f;

void Motor_SetDuty(uint16_t pwm_duty) {
    if (pwm_duty > 95) pwm_duty = 95;
    pwm_val = (uint16_t)(((float)pwm_duty / 100.0f) * (float)htim8.Init.Period);
    __HAL_TIM_SET_COMPARE(&htim8, TIM_CHANNEL_1, pwm_val);
    __HAL_TIM_SET_COMPARE(&htim8, TIM_CHANNEL_2, pwm_val);
    __HAL_TIM_SET_COMPARE(&htim8, TIM_CHANNEL_3, pwm_val);
}
void Motor_Align(uint16_t align_duty, uint16_t align_time_ms) {
    Motor_SetDuty(align_duty);
    Motor_CommutationStep(1);
    HAL_Delay(align_time_ms);
    Motor_SetDuty(0);
}
void Motor_DisableOutputs(void) {
    TIM8->CCER &= ~(TIM_CCER_CC1E | TIM_CCER_CC1NE |
                    TIM_CCER_CC2E | TIM_CCER_CC2NE |
                    TIM_CCER_CC3E | TIM_CCER_CC3NE);
}
void Motor_CommutationStep(uint8_t step) {
    if (step < 1 || step > 6) return;
    __HAL_TIM_MOE_DISABLE(&htim8);
    Motor_DisableOutputs();
    switch (step) {
        case 1: TIM8->CCER |= TIM_CCER_CC1E | TIM_CCER_CC2NE; floating_phase = 3; rotor_elec_angle = 0.0f;   break;
        case 2: TIM8->CCER |= TIM_CCER_CC1E | TIM_CCER_CC3NE; floating_phase = 2; rotor_elec_angle = 60.0f;  break;
        case 3: TIM8->CCER |= TIM_CCER_CC2E | TIM_CCER_CC3NE; floating_phase = 1; rotor_elec_angle = 120.0f; break;
        case 4: TIM8->CCER |= TIM_CCER_CC2E | TIM_CCER_CC1NE; floating_phase = 3; rotor_elec_angle = 180.0f; break;
        case 5: TIM8->CCER |= TIM_CCER_CC3E | TIM_CCER_CC1NE; floating_phase = 2; rotor_elec_angle = 240.0f; break;
        case 6: TIM8->CCER |= TIM_CCER_CC3E | TIM_CCER_CC2NE; floating_phase = 1; rotor_elec_angle = 300.0f; break;
    }
    UpdateSpeedOnCommutation();
    angle_mech = GetRotorMechanicalAngle();
    __HAL_TIM_MOE_ENABLE(&htim8);
}
void Motor_Init(uint16_t pwm_duty) {
    pwm_val = pwm_duty;
    Motor_SetDuty(pwm_val);
    Motor_CommutationStep(1);
}
void Motor_Toggle(void) {
    if (motor_running) {
        Motor_SetDuty(0); Motor_DisableOutputs();
        floating_phase = 0; last_emf = 0; emf_value = 0; motor_running = false;
        Motor_Stop(); motor_state = MOTOR_STATE_STOPPED;
    } else {
        Motor_Start(); motor_state = MOTOR_STATE_ALIGN;
        Motor_Align(30, 2000); motor_state = MOTOR_STATE_OPEN_LOOP;
        Motor_OpenLoopStartup(&myMotorParams); motor_running = true;
    }
}
void Motor_Start(void) {
    Motor_SetDuty(50);
    HAL_TIM_PWM_Start(&htim8, TIM_CHANNEL_1); HAL_TIMEx_PWMN_Start(&htim8, TIM_CHANNEL_1);
    HAL_TIM_PWM_Start(&htim8, TIM_CHANNEL_2); HAL_TIMEx_PWMN_Start(&htim8, TIM_CHANNEL_2);
    HAL_TIM_PWM_Start(&htim8, TIM_CHANNEL_3); HAL_TIMEx_PWMN_Start(&htim8, TIM_CHANNEL_3);
    HAL_TIM_PWM_Start(&htim8, TIM_CHANNEL_4);
    __HAL_TIM_MOE_ENABLE(&htim8);
    HAL_ADC_Start_DMA(&hadc1, (uint32_t*)adc_values, 4);
    HAL_ADC_Start_DMA(&hadc3, (uint32_t*)adc_val, 4);
    HAL_GPIO_WritePin(GPIOD, GPIO_PIN_15, GPIO_PIN_SET);
}
void Motor_Stop(void) {
    __HAL_TIM_MOE_DISABLE(&htim8);
    HAL_TIM_PWM_Stop(&htim8, TIM_CHANNEL_1); HAL_TIMEx_PWMN_Stop(&htim8, TIM_CHANNEL_1);
    HAL_TIM_PWM_Stop(&htim8, TIM_CHANNEL_2); HAL_TIMEx_PWMN_Stop(&htim8, TIM_CHANNEL_2);
    HAL_TIM_PWM_Stop(&htim8, TIM_CHANNEL_3); HAL_TIMEx_PWMN_Stop(&htim8, TIM_CHANNEL_3);
    HAL_GPIO_WritePin(GPIOD, GPIO_PIN_15, GPIO_PIN_RESET);
    rpm = 0;
}
void Motor_OpenLoopStartup(const MotorStartupParams_t *params) {
    for (uint16_t i = 0; i < params->steps; ++i) {
        uint16_t duty = params->start_duty +
                        ((params->end_duty - params->start_duty) * i) / params->steps;
        uint16_t delay = params->start_delay_ms +
                         ((params->end_delay_ms - params->start_delay_ms) * i) / params->steps;
        Motor_SetDuty(duty);
        Motor_CommutationStep((i % 6) + 1);
        HAL_Delay(delay);
    }
    HAL_Delay(50);
    motor_state = MOTOR_STATE_CLOSED_LOOP;
}

/* ---------------- ADC Processing ---------------- */
void ProcessADCLogic(void) {
    static uint16_t last_emf = 0;
    static uint8_t comm_step = 1;
    const uint16_t V_REF = ADC_TO_PHASE_VOLTAGE(950);
    static float dcv = 0, dci = 0;
    static uint32_t last_tick = 0;
    uint32_t now = HAL_GetTick();
    uint32_t dt_ms = (last_tick > 0) ? (now - last_tick) : 1;
    last_tick = now;
    if (!adc_ready) return; adc_ready = false;

    phaseV_a = ApplyEMA(ADC_TO_PHASE_VOLTAGE(local_adc_values[0]), phaseV_a, alpha);
    phaseV_b = ApplyEMA(ADC_TO_PHASE_VOLTAGE(local_adc_values[1]), phaseV_b, alpha);
    phaseV_c = ApplyEMA(ADC_TO_PHASE_VOLTAGE(local_adc_values[2]), phaseV_c, alpha);
    ShuntI_a = ApplyEMA(ADC_TO_SHUNT_CURRENT(local_adc2_values[1]), ShuntI_a, alpha);
    ShuntI_b = ApplyEMA(ADC_TO_SHUNT_CURRENT(local_adc2_values[2]), ShuntI_b, alpha);
    ShuntI_c = -(ShuntI_a + ShuntI_b);

    dcv = lpf1(ADC_TO_DC_BUS_VOLTAGE(local_adc2_values[0]), dcv, dt_ms, 50.0f);
    VDC = fabsf(dcv);
    dci = lpf1(ADC_TO_SHUNT_CURRENT(local_adc2_values[3]), dci, dt_ms, 50.0f);
    IDC = fabsf(dci);

    IAC = fabsf(ShuntI_a); VAC = fabsf(phaseV_a);

    switch (floating_phase) {
        case 1: emf_value = (uint16_t)phaseV_a; break;
        case 2: emf_value = (uint16_t)phaseV_b; break;
        case 3: emf_value = (uint16_t)phaseV_c; break;
    }
    if (motor_state == MOTOR_STATE_CLOSED_LOOP) {
        if ((last_emf < V_REF && emf_value >= V_REF) ||
            (last_emf > V_REF && emf_value <= V_REF)) {
            if (++comm_step > 6) comm_step = 1;
            Motor_CommutationStep(comm_step);
        }
    }
    last_emf = emf_value;
}

