// Function to compute (base^exp) % mod efficiently using binary exponentiation
long long power(long long base, long long exp) {
    long long res = 1;
    base %= 998244353; // Ensure base is within modulo range
    while (exp > 0) {
        // If exponent is odd, multiply result with base
        if (exp % 2 == 1) res = (res * base) % 998244353;
        // Square the base
        base = (base * base) % 998244353;
        // Halve the exponent
        exp /= 2;
    }
    return res;
}

// Function to compute modular inverse using Fermat's Little Theorem
// For a prime modulus p, the modular inverse of a is a^(p-2) mod p.
long long modInverse(long long n) {
    // 998244353 is a prime modulus.
    return power(n, 998244353 - 2);
}

// Define the modulus
const long long MOD = 998244353;
// Precompute modular inverse of 4, as it's used frequently in the formula
const long long INV4 = modInverse(4); 
// Vector to store precomputed powers of 2 modulo MOD
std::vector<long long> pows2;
// Define the maximum possible N based on constraints + a small buffer
const int MAXN_GLOBAL = 200005; 

// Function to precompute powers of 2 up to max_n
void precompute_pows2(int max_n) {
    // Check if powers are already computed for a sufficient range
    if (!pows2.empty() && pows2.size() >= max_n + 1) return; 

    // If vector is smaller or empty, resize and compute powers
    pows2.resize(max_n + 1);
    pows2[0] = 1; // 2^0 = 1
    for (int i = 1; i <= max_n; ++i) {
        // Compute 2^i = 2^(i-1) * 2, taking modulo at each step
        pows2[i] = (pows2[i-1] * 2) % MOD; 
    }
}

// Global variables to store current string length N and count of zeros N0
// Using globals simplifies passing state between updates and calculation
long long N, N0; 

// Function to calculate the sum of scores based on current N and N0
// This function implements the derived formula.
long long calculate_sum() {
    // Base cases: If string length N is 0 or 1, the sum of scores is 0.
    // This is because there are no non-empty subsequences of length >= 2.
    // The score for length 1 subsequences is 0.
    if (N <= 1) {
        return 0;
    }

    // Use long long for intermediate calculations to prevent potential overflow
    long long N_ll = N;
    long long N0_ll = N0;

    // The derived formula for the total sum of scores T is:
    // T = INV4 * (N^2 + N - 4*N0*N + 4*N0^2 - 2) * 2^(N-2) mod MOD

    // Calculate each term of the main expression N^2 + N - 4*N0*N + 4*N0^2 - 2
    // Perform calculations modulo MOD to keep numbers manageable

    // Term N^2 mod MOD
    long long term1 = (N_ll * N_ll) % MOD;
    // Term N mod MOD
    long long term2 = N_ll % MOD; 
    // Term 4*N0*N mod MOD
    long long term3 = (4 * N0_ll) % MOD;
    term3 = (term3 * N_ll) % MOD;
    // Term 4*N0^2 mod MOD
    long long term4 = (4 * N0_ll) % MOD;
    term4 = (term4 * N0_ll) % MOD;
    // Constant term 2
    long long term5 = 2;

    // Combine the terms: (term1 + term2 - term3 + term4 - term5) mod MOD
    // Use modular arithmetic properties carefully. Adding MOD before taking modulo ensures positive result for subtraction.
    long long main_term = (term1 + term2) % MOD;       // (N^2 + N) % MOD
    main_term = (main_term - term3 + MOD) % MOD;     // (N^2 + N - 4*N0*N) % MOD
    main_term = (main_term + term4) % MOD;           // (N^2 + N - 4*N0*N + 4*N0^2) % MOD
    main_term = (main_term - term5 + MOD) % MOD;     // (N^2 + N - 4*N0*N + 4*N0^2 - 2) % MOD

    // Get the precomputed power of 2 term: 2^(N-2) mod MOD
    // This is safe because we've handled the N <= 1 case already, so N >= 2 is guaranteed.
    long long pow2_term = pows2[N - 2];

    // Final calculation: T = (main_term * INV4 * pow2_term) mod MOD
    long long total_sum = (main_term * INV4) % MOD; // Multiply by INV4 (modular inverse of 4)
    total_sum = (total_sum * pow2_term) % MOD;      // Multiply by 2^(N-2)

    return total_sum;
}


