        /// </summary>
        private decimal GetEffectiveMonthlyRate(
            LeaveType leaveType,
            int workingDaysPerWeek,
            DateTime employeeStartDate,
            DateTime calculationDate,
            List<ServiceRateIncrease> serviceRateIncreases)
        {
            // Determine base rate: Use configured rate, or default annual leave rates.
            decimal baseMonthlyRate = leaveType.MonthlyIncreaseRate;
            if (baseMonthlyRate <= 0) // If no specific rate configured, use standard annual defaults
            {
                baseMonthlyRate = (workingDaysPerWeek == 6) ? 1.5m : 1.25m;
            }

            // Apply Service Rate Increase if applicable
            if (leaveType.ServiceRateIncrease && serviceRateIncreases != null)
            {
                return GetCurrentMonthlyRateFromIncreases(employeeStartDate, calculationDate, baseMonthlyRate, serviceRateIncreases);
            }
            else
            {
                return baseMonthlyRate;
            }
        }

        /// <summary>
        /// Determines the current monthly accrual rate based on years of service.
        /// </summary>
        private decimal GetCurrentMonthlyRateFromIncreases(
         DateTime employeeStartDate,
         DateTime currentDate, // The date to check service years against
         decimal baseRate,
         List<ServiceRateIncrease> increases)
        {
            if (increases == null || !increases.Any())
            {
                return baseRate;
            }

            // Calculate years of service completed as of the current date
            double yearsOfService = (currentDate - employeeStartDate).TotalDays / 365.25;

            // Find the highest applicable rate based on completed years of service
            var applicableIncrease = increases
                .Where(i => i.YearsService <= yearsOfService) // Rate applies if service years are met or exceeded
                .OrderByDescending(i => i.YearsService)       // Get the one for the most years (highest tier met)
                .FirstOrDefault();

            return applicableIncrease?.NewRate ?? baseRate; // Use the increased rate or fallback to the base rate
        }

        /// <summary>
        /// Calculates the difference in *full* months between two dates.
        /// </summary>
        private int CalculateMonthDifference(DateTime startDate, DateTime endDate)
        {
            if (endDate < startDate) return -1; // Or 0, depending on how it should be handled

            // Original logic: ((endDate.Year - startDate.Year) * 12) + endDate.Month - startDate.Month + (endDate.Day >= startDate.Day ? 0 : -1);
            // Let's simplify for clarity, this calculates *full* months passed.
            int months = (endDate.Year - startDate.Year) * 12 + endDate.Month - startDate.Month;

            // Adjust if the end day is before the start day in the final month
            if (endDate.Day < startDate.Day)
            {
                months--;
            }
            return months;
        }

