            }
            else
            {
                return baseMonthlyRate;
            }
        }

        private decimal GetCurrentMonthlyRateFromIncreases(
         DateTime employeeStartDate,
         DateTime currentDate,
         decimal baseRate,
         List<ServiceRateIncrease> increases)
        {
            if (increases == null || !increases.Any())
            {
                return baseRate;
            }

            double yearsOfService = (currentDate - employeeStartDate).TotalDays / 365.25;

            var applicableIncrease = increases
                .Where(i => i.YearsService <= yearsOfService)
                .OrderByDescending(i => i.YearsService)
                .FirstOrDefault();

            return applicableIncrease?.NewRate ?? baseRate;
        }

        private int CalculateMonthDifference(DateTime startDate, DateTime endDate)
        {
            if (endDate < startDate) return -1;

            int months = (endDate.Year - startDate.Year) * 12 + endDate.Month - startDate.Month;

            if (endDate.Day < startDate.Day)
            {
                months--;
            }
            return months;
        }
