                case "family responsibility leave":
                    return CalculateFamilyResponsibilityLeave(leaveType, employeeStartDate, calculationDate, workingDaysPerWeek, leaveHistoryLookup);

                case "maternity leave":
                     return leaveType.ResetValue > 0 ? leaveType.ResetValue : 0;

                case "unpaid leave":
                    return 0;

                default:
                    return CalculateGenericLeave(leaveType, employeeStartDate, calculationDate, workingDaysPerWeek, serviceRateIncreases, leaveHistoryLookup);
