        private decimal CalculateAnnualLeave(
            LeaveType leaveType,
            DateTime employeeStartDate,
            DateTime calculationDate,
            int workingDaysPerWeek,
            List<ServiceRateIncrease> serviceRateIncreases,
            Dictionary<string, List<(DateTime StartDate, decimal Days)>> leaveHistoryLookup)
        {
            DateTime cycleStartDate = GetCurrentCycleStartDate(employeeStartDate, calculationDate);
            decimal monthlyAccrualRate = GetEffectiveMonthlyRate(leaveType, workingDaysPerWeek, employeeStartDate, calculationDate, serviceRateIncreases);

            int monthsInCycle = CalculateMonthDifference(cycleStartDate, calculationDate);
            if (monthsInCycle < 0) monthsInCycle = 0;

            decimal accruedInCycle = monthsInCycle * monthlyAccrualRate;

            if (calculationDate.Year == employeeStartDate.Year && calculationDate.Month == employeeStartDate.Month && monthsInCycle == 0)
            {
                 // Simplified: Grant first month's accrual if within the first month and cycle just started
                 // Let's stick to the full month calculation for consistency unless specific pro-rata needed
                 // If CalculateMonthDifference returns 0, accruedInCycle remains 0 unless adjusted here.
                 // Maybe grant if they passed a threshold like mid-month? Sticking to monthsInCycle * rate for now.
                 // Re-evaluating: If it's the start month, maybe give the first month accrual?
                 // Example: Start 15 Jan, Calc 20 Jan. monthsInCycle=0. Should they have some accrual?
                 // Let's use the pro-rata example IF it's the very first month of employment AND within that month.
                 // This diverges slightly from the pure 'monthsInCycle' logic above it.
                 if (cycleStartDate == employeeStartDate && (calculationDate - cycleStartDate).Days < DateTime.DaysInMonth(cycleStartDate.Year, cycleStartDate.Month))
                 {
                     // Maybe grant the full first month? Or pro-rata? Let's grant full month for simplicity if ANY time passed in first month.
                     // Alternative: accruedInCycle = monthlyAccrualRate * ((calculationDate - cycleStartDate).Days + 1) / (decimal)DateTime.DaysInMonth(cycleStartDate.Year, cycleStartDate.Month);
                     // Sticking with granting the full month if the calculation date is within the employee's very first month.
                     accruedInCycle = monthlyAccrualRate;
                 }
                 else if (cycleStartDate == employeeStartDate && monthsInCycle == 0) {
                     // This case handles if the start date was e.g. Jan 15, and calc date is Feb 10. monthsInCycle is 0.
                     // Here, they *have* completed part of the first month. Let's grant the first month's accrual.
                      accruedInCycle = monthlyAccrualRate;
                 }

            }
            // Recalculate monthsInCycle in case it started mid-cycle but after first month adjustment
            monthsInCycle = CalculateMonthDifference(cycleStartDate, calculationDate);
            if (monthsInCycle < 0) monthsInCycle = 0;
            accruedInCycle = monthsInCycle * monthlyAccrualRate; // Base calculation remains based on full months passed in cycle


            decimal leaveTakenThisCycle = SumLeaveTakenInPeriod(leaveType.LeaveTypeID, cycleStartDate, calculationDate, leaveHistoryLookup);

            decimal currentBalance = accruedInCycle - leaveTakenThisCycle;

            if (leaveType.HasMaximum)
            {
                currentBalance = Math.Min(currentBalance, leaveType.MaximumDays);
            }

            currentBalance = Math.Max(0, currentBalance);

            return Math.Round(currentBalance, 2);
        }

        private decimal CalculateSickLeave(
             LeaveType leaveType,
             DateTime employeeStartDate,
             DateTime calculationDate,
             int workingDaysPerWeek,
             Dictionary<string, List<(DateTime StartDate, decimal Days)>> leaveHistoryLookup)
        {

            int monthsDifference = CalculateMonthDifference(employeeStartDate, calculationDate);
            // Add small buffer to calculationDate comparison for the 6 month rule to avoid floating point issues with exact 6 month boundary
            DateTime sixMonthsAfterStart = employeeStartDate.AddMonths(6);

            if (calculationDate < sixMonthsAfterStart && calculationDate >= employeeStartDate)
            {
                int daysWorkedApproximation = (calculationDate - employeeStartDate).Days + 1;
                decimal accruedDuringPeriod = Math.Floor((decimal)daysWorkedApproximation / 26m);
                decimal leaveTakenDuringPeriod = SumLeaveTakenInPeriod(leaveType.LeaveTypeID, employeeStartDate, calculationDate, leaveHistoryLookup);
                decimal availableBalance = accruedDuringPeriod - leaveTakenDuringPeriod;
                availableBalance = Math.Max(0, availableBalance);
                return Math.Round(availableBalance, 2);
            }
            else if (calculationDate >= employeeStartDate)
            {
                decimal cycleGrant = (workingDaysPerWeek == 6) ? 36 : 30;
                if (leaveType.ResetValue > 0) // Allow override, e.g., if company policy is slightly different but configured
                {
                    cycleGrant = leaveType.ResetValue;
                }

                TimeSpan totalElapsed = calculationDate - employeeStartDate;
                // Ensure cycle index calculation doesn't lead to negative indices if calcDate is near startDate after 6 months
                 double daysSinceStart = Math.Max(0, totalElapsed.TotalDays);
                 // Calculate cycle start based on 3-year intervals from employment start date
                 int cycleIndex = (int)Math.Floor(daysSinceStart / (365.25 * 3));
                 DateTime cycleStartDate = employeeStartDate.AddYears(cycleIndex * 3);

                // Ensure cycle start date is not after calculation date, adjust if needed (edge case near start)
                 if (cycleStartDate > calculationDate && cycleIndex > 0)
                 {
                     cycleIndex--;
                     cycleStartDate = employeeStartDate.AddYears(cycleIndex * 3);
                 }
                 else if (cycleStartDate > calculationDate) // If even the 0th cycle starts after calc date (shouldn't happen if calcDate >= startDate)
                 {
                      cycleStartDate = employeeStartDate; // Default to start date if something is off
                 }


                // Ensure leave taken is summed correctly within the current cycle, respecting the cycleStartDate
                decimal leaveTakenThisCycle = SumLeaveTakenInPeriod(leaveType.LeaveTypeID, cycleStartDate, calculationDate, leaveHistoryLookup);

                decimal availableBalance = cycleGrant - leaveTakenThisCycle;
                availableBalance = Math.Max(0, availableBalance);

                if (leaveType.HasMaximum && leaveType.MaximumDays < cycleGrant) // Only apply max if specifically set lower than grant
                {
                    availableBalance = Math.Min(availableBalance, leaveType.MaximumDays);
                }
                 else if (leaveType.HasMaximum) // Apply general maximum if set
                 {
                      availableBalance = Math.Min(availableBalance, leaveType.MaximumDays);
                 }


                return Math.Round(availableBalance, 2);
            }
            else
            {
                return 0;
            }
        }


        private decimal CalculateFamilyResponsibilityLeave(
            LeaveType leaveType,
            DateTime employeeStartDate,
            DateTime calculationDate,
            int workingDaysPerWeek,
            Dictionary<string, List<(DateTime StartDate, decimal Days)>> leaveHistoryLookup)
        {
            int monthsWorked = CalculateMonthDifference(employeeStartDate, calculationDate);
            DateTime fourMonthsAfterStart = employeeStartDate.AddMonths(4);

            if (calculationDate < fourMonthsAfterStart || workingDaysPerWeek < 4 || calculationDate < employeeStartDate)
            {
                return 0;
            }

            DateTime cycleStartDate = GetCurrentCycleStartDate(employeeStartDate, calculationDate);
            decimal cycleEntitlement = leaveType.ResetValue > 0 ? leaveType.ResetValue : 3;
            decimal leaveTakenThisCycle = SumLeaveTakenInPeriod(leaveType.LeaveTypeID, cycleStartDate, calculationDate, leaveHistoryLookup);
            decimal availableBalance = cycleEntitlement - leaveTakenThisCycle;
            availableBalance = Math.Max(0, availableBalance);

            if (leaveType.HasMaximum)
            {
                availableBalance = Math.Min(availableBalance, leaveType.MaximumDays);
            }

            return Math.Round(availableBalance, 2);
        }

        private decimal CalculateGenericLeave(
            LeaveType leaveType,
            DateTime employeeStartDate,
            DateTime calculationDate,
            int workingDaysPerWeek,
            List<ServiceRateIncrease> serviceRateIncreases,
            Dictionary<string, List<(DateTime StartDate, decimal Days)>> leaveHistoryLookup)
        {
            if (calculationDate < employeeStartDate) return 0;

            DateTime cycleStartDate = GetCurrentCycleStartDate(employeeStartDate, calculationDate);
            decimal currentBalance = 0;

            if (leaveType.IncreaseMonthly)
            {
                decimal monthlyAccrualRate = GetEffectiveMonthlyRate(leaveType, workingDaysPerWeek, employeeStartDate, calculationDate, serviceRateIncreases);
                int monthsInCycle = CalculateMonthDifference(cycleStartDate, calculationDate);
                if (monthsInCycle < 0) monthsInCycle = 0;
                currentBalance = monthsInCycle * monthlyAccrualRate;
                 // Add similar first month handling as Annual Leave if required for generic types
                 if (cycleStartDate == employeeStartDate && monthsInCycle == 0 && calculationDate >= employeeStartDate) {
                     // Grant first month's accrual if calc date is within the very first month of employment for this leave type cycle
                      currentBalance = monthlyAccrualRate;
                 }

            }
            else
            {
                currentBalance = leaveType.ResetValue;
            }

            decimal leaveTakenThisCycle = SumLeaveTakenInPeriod(leaveType.LeaveTypeID, cycleStartDate, calculationDate, leaveHistoryLookup);
            currentBalance -= leaveTakenThisCycle;

            if (leaveType.HasMaximum)
            {
                currentBalance = Math.Min(currentBalance, leaveType.MaximumDays);
            }

            currentBalance = Math.Max(0, currentBalance);

            return Math.Round(currentBalance, 2);
        }

        private decimal SumLeaveTakenInPeriod(
            string leaveTypeId,
            DateTime periodStartDate,
            DateTime periodEndDate,
            Dictionary<string, List<(DateTime StartDate, decimal Days)>> leaveHistoryLookup)
        {
            decimal totalDaysTaken = 0;

            if (leaveHistoryLookup.TryGetValue(leaveTypeId, out var history) && history != null)
            {
                foreach (var record in history)
                {
                    if (record.StartDate >= periodStartDate && record.StartDate <= periodEndDate)
                    {
                        totalDaysTaken += record.Days;
                    }
                }
            }
            return totalDaysTaken;
        }

        private DateTime GetCurrentCycleStartDate(DateTime employeeStartDate, DateTime calculationDate)
        {
            int yearsPassed = calculationDate.Year - employeeStartDate.Year;

            if (calculationDate.Month < employeeStartDate.Month ||
                (calculationDate.Month == employeeStartDate.Month && calculationDate.Day < employeeStartDate.Day))
            {
                yearsPassed--;
            }

            // Ensure yearsPassed is not negative if calculationDate is slightly before start date due to time component
            if (yearsPassed < 0) yearsPassed = 0;


            return employeeStartDate.AddYears(yearsPassed);
        }

        private decimal GetEffectiveMonthlyRate(
            LeaveType leaveType,
            int workingDaysPerWeek,
            DateTime employeeStartDate,
            DateTime calculationDate,
            List<ServiceRateIncrease> serviceRateIncreases)
        {
            decimal baseMonthlyRate = leaveType.MonthlyIncreaseRate;
            if (baseMonthlyRate <= 0)
            {
                // Default Annual Leave Rates if not specified
                baseMonthlyRate = (workingDaysPerWeek == 6) ? 1.5m : 1.25m;
            }

            if (leaveType.ServiceRateIncrease && serviceRateIncreases != null && serviceRateIncreases.Any(i => i.LeaveTypeID == leaveType.LeaveTypeID))
            {
                 var relevantIncreases = serviceRateIncreases.Where(i => i.LeaveTypeID == leaveType.LeaveTypeID).ToList();
                 return GetCurrentMonthlyRateFromIncreases(employeeStartDate, calculationDate, baseMonthlyRate, relevantIncreases);

            }
            else
            {
                return baseMonthlyRate;
            }
        }

        private decimal GetCurrentMonthlyRateFromIncreases(
         DateTime employeeStartDate,
         DateTime currentDate,
         decimal baseRate,
         List<ServiceRateIncrease> increases) // Pass only relevant increases
        {
             if (increases == null || !increases.Any())
             {
                 return baseRate;
             }

            // Calculate years of service completed as of the current date more robustly
            int yearsOfService = 0;
            DateTime serviceCheckDate = employeeStartDate;
            while(serviceCheckDate.AddYears(1) <= currentDate)
            {
                yearsOfService++;
                serviceCheckDate = serviceCheckDate.AddYears(1);
            }


            var applicableIncrease = increases
                .Where(i => i.YearsService <= yearsOfService)
                .OrderByDescending(i => i.YearsService)
                .FirstOrDefault();

            return applicableIncrease?.NewRate ?? baseRate;
        }


        private int CalculateMonthDifference(DateTime startDate, DateTime endDate)
        {
             if (endDate < startDate) return 0; // Return 0 instead of -1 for simplicity in accrual calcs


            int months = (endDate.Year - startDate.Year) * 12 + endDate.Month - startDate.Month;

            if (endDate.Day < startDate.Day)
            {
                months--;
            }
             // Ensure months isn't negative after adjustment if start/end are close but cross month boundary backward
             return Math.Max(0, months);

        }
    }
