// Base class providing common implementation
public abstract class CadObjectBase : ICadObject, INotifyPropertyChanged
{
    private readonly Guid _id;
    private string _name;
    private ICadLayer _layer;
    private bool _isVisible = true;
    private bool _isLocked = false;
    private bool _isDirty = true;

    private readonly HashSet<ICadObject> _dependencies = new();
    private readonly HashSet<ICadObject> _dependents = new();

    protected CadObjectBase(string name, ICadLayer layer)
    {
        _id = Guid.NewGuid();
        _name = name ?? throw new ArgumentNullException(nameof(name));
        _layer = layer ?? throw new ArgumentNullException(nameof(layer));
    }

    public Guid Id => _id;

    public string Name
    {
        get => _name;
        set => SetProperty(ref _name, value);
    }

    public ICadLayer Layer
    {
        get => _layer;
        set => SetProperty(ref _layer, value);
    }

    // Property change notification with automatic invalidation
    protected bool SetProperty<T>(ref T field, T value, [CallerMemberName] string propertyName = null)
    {
        if (EqualityComparer<T>.Default.Equals(field, value))
            return false;

        field = value;
        OnPropertyChanged(propertyName);
        Invalidate();
        return true;
    }

    public virtual void Invalidate()
    {
        if (_isDirty) return;

        _isDirty = true;

        // Propagate invalidation to dependents
        foreach (var dependent in _dependents)
        {
            dependent.Invalidate();
        }

        // Notify the document that this object needs updating
        InvalidationRequested?.Invoke(this, EventArgs.Empty);
    }

    public async Task<bool> UpdateAsync(CancellationToken cancellationToken = default)
    {
        if (!_isDirty) return true;

        try
        {
            // Ensure dependencies are up to date first
            foreach (var dependency in _dependencies)
            {
                if (!await dependency.UpdateAsync(cancellationToken))
                    return false;
            }

            // Perform the actual update
            var result = await OnUpdateAsync(cancellationToken);
            if (result)
            {
                _isDirty = false;
                Updated?.Invoke(this, EventArgs.Empty);
            }

            return result;
        }
        catch (Exception ex)
        {
            // Log error and mark as still dirty
            return false;
        }
    }

    protected abstract Task<bool> OnUpdateAsync(CancellationToken cancellationToken);

    public event EventHandler InvalidationRequested;
    public event EventHandler Updated;
    public event PropertyChangedEventHandler PropertyChanged;
}
