### 2. Dependency Management System

A robust dependency tracking system is crucial:

```csharp
public interface IDependencyManager
{
    void RegisterDependency(ICadObject dependent, ICadObject dependency);
    void UnregisterDependency(ICadObject dependent, ICadObject dependency);
    void UnregisterAllDependencies(ICadObject cadObject);
    IEnumerable<ICadObject> GetDependencies(ICadObject cadObject);
    IEnumerable<ICadObject> GetDependents(ICadObject cadObject);
    IEnumerable<ICadObject> GetUpdateOrder(IEnumerable<ICadObject> objects);
}

public class DependencyManager : IDependencyManager
{
    private readonly Dictionary<Guid, HashSet<Guid>> _dependencyGraph = new();
    private readonly Dictionary<Guid, HashSet<Guid>> _dependentGraph = new();
    private readonly Dictionary<Guid, WeakReference<ICadObject>> _objectRegistry = new();

    public void RegisterDependency(ICadObject dependent, ICadObject dependency)
    {
        if (dependent == null || dependency == null) return;
        if (dependent.Id == dependency.Id) return;

        // Check for circular dependencies
        if (WouldCreateCycle(dependent.Id, dependency.Id))
        {
            throw new InvalidOperationException($"Circular dependency detected between {dependent.Name} and {dependency.Name}");
        }

        // Update graphs
        _dependencyGraph.TryAdd(dependent.Id, new HashSet<Guid>());
        _dependencyGraph[dependent.Id].Add(dependency.Id);

        _dependentGraph.TryAdd(dependency.Id, new HashSet<Guid>());
        _dependentGraph[dependency.Id].Add(dependent.Id);

        // Register objects
        _objectRegistry[dependent.Id] = new WeakReference<ICadObject>(dependent);
        _objectRegistry[dependency.Id] = new WeakReference<ICadObject>(dependency);
    }

    public IEnumerable<ICadObject> GetUpdateOrder(IEnumerable<ICadObject> objects)
    {
        // Topological sort to ensure dependencies are updated before dependents
        var sorted = new List<ICadObject>();
        var visited = new HashSet<Guid>();
        var visiting = new HashSet<Guid>();

        void Visit(ICadObject obj)
        {
            if (visited.Contains(obj.Id)) return;
            if (visiting.Contains(obj.Id))
            {
                throw new InvalidOperationException("Circular dependency detected during update");
            }

            visiting.Add(obj.Id);

            foreach (var dep in GetDependencies(obj))
            {
                Visit(dep);
            }

            visiting.Remove(obj.Id);
            visited.Add(obj.Id);
            sorted.Add(obj);
        }

        foreach (var obj in objects)
        {
            Visit(obj);
        }

        return sorted;
    }

    private bool WouldCreateCycle(Guid dependent, Guid dependency)
    {
        // DFS to check if adding this edge would create a cycle
        var visited = new HashSet<Guid>();
        var stack = new Stack<Guid>();
        stack.Push(dependency);

        while (stack.Count > 0)
        {
            var current = stack.Pop();
            if (current == dependent) return true;

            if (visited.Contains(current)) continue;
            visited.Add(current);

            if (_dependencyGraph.TryGetValue(current, out var deps))
            {
                foreach (var dep in deps)
                {
                    stack.Push(dep);
                }
            }
        }

        return false;
    }
}
