### 3. Reactive Property System

For fine-grained reactivity, we need a property system that can track changes:

```csharp
public interface IReactiveProperty<T> : INotifyPropertyChanged
{
    T Value { get; set; }
    IObservable<T> Changed { get; }
}

public class ReactiveProperty<T> : IReactiveProperty<T>
{
    private T _value;
    private readonly Subject<T> _changed = new();

    public ReactiveProperty(T initialValue = default)
    {
        _value = initialValue;
    }

    public T Value
    {
        get => _value;
        set
        {
            if (EqualityComparer<T>.Default.Equals(_value, value))
                return;

            _value = value;
            OnPropertyChanged();
            _changed.OnNext(value);
        }
    }

    public IObservable<T> Changed => _changed.AsObservable();

    public event PropertyChangedEventHandler PropertyChanged;

    protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
    {
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }
}

// Extension for computed properties
public class ComputedProperty<T> : IReactiveProperty<T>
{
    private readonly Func<T> _compute;
    private readonly List<IDisposable> _subscriptions = new();
    private T _cachedValue;
    private bool _isValid;

    public ComputedProperty(Func<T> compute, params IObservable<object>[] dependencies)
    {
        _compute = compute;

        foreach (var dependency in dependencies)
        {
            var subscription = dependency.Subscribe(_ => Invalidate());
            _subscriptions.Add(subscription);
        }
    }

    public T Value
    {
        get
        {
            if (!_isValid)
            {
                _cachedValue = _compute();
                _isValid = true;
            }
            return _cachedValue;
        }
        set => throw new InvalidOperationException("Cannot set value of computed property");
    }

    private void Invalidate()
    {
        _isValid = false;
        OnPropertyChanged(nameof(Value));
    }
}
