            }));

            // Left face (x = -1)
            materials.push(new THREE.MeshLambertMaterial({ 
                color: x === -1 ? colors.orange : 0x000000 
            }));

            // Top face (y = 1)
            materials.push(new THREE.MeshLambertMaterial({ 
                color: y === 1 ? colors.white : 0x000000 
            }));

            // Bottom face (y = -1)
            materials.push(new THREE.MeshLambertMaterial({ 
                color: y === -1 ? colors.yellow : 0x000000 
            }));

            // Front face (z = 1)
            materials.push(new THREE.MeshLambertMaterial({ 
                color: z === 1 ? colors.blue : 0x000000 
            }));

            // Back face (z = -1)
            materials.push(new THREE.MeshLambertMaterial({ 
