        function animateRotation(axis, layer, clockwise) {
            isAnimating = true;

            // Find cubies in the layer
            const layerCubies = cubies.filter(cubie => {
                const pos = cubie.position;
                switch (axis) {
                    case 'y': return Math.abs(pos.y - layer) < 0.1;
                    case 'x': return Math.abs(pos.x - layer) < 0.1;
                    case 'z': return Math.abs(pos.z - layer) < 0.1;
