    <script>
        (function() {
            "use strict";

            // Navigation Toggle
            const hamburger = document.querySelector('.hamburger');
            const nav = document.querySelector('nav');

            if (hamburger && nav) {
                hamburger.addEventListener('click', () => {
                    const expanded = hamburger.getAttribute('aria-expanded') === 'true' || false;
                    hamburger.setAttribute('aria-expanded', !expanded);
                    nav.classList.toggle('open');
                    document.body.style.overflow = nav.classList.contains('open') ? 'hidden' : ''; // Lock scroll
                });

                document.addEventListener('keydown', (event) => {
                    if (nav.classList.contains('open') && event.key === 'Escape') {
                        hamburger.setAttribute('aria-expanded', false);
                        nav.classList.remove('open');
                        document.body.style.overflow = ''; // Re-enable scroll
                    }
                });
            }

            // Intersection Observer for Reveal-on-Scroll
            const reveals = document.querySelectorAll('.reveal');
            const observer = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        observer.unobserve(entry.target); // Only reveal once
                    }
                });
            }, { threshold: 0.2 }); // Adjust threshold as needed

            reveals.forEach(reveal => {
                observer.observe(reveal);
            });

            // Gallery Parallax Effect
            const gallery = document.querySelector('.gallery');
            if (gallery) {
                gallery.addEventListener('scroll', () => {
                    const scrollLeft = gallery.scrollLeft;
                    const items = gallery.querySelectorAll('div');
                    items.forEach((item, index) => {
                        item.style.transform = `translateX(${-scrollLeft * 0.1 * (index % 2 === 0 ? 1 : -1)}px)`;
                    });
                });
            }


            // Form Validation (Client-Side)
            const form = document.getElementById('join-form');
            const nameInput = document.getElementById('name');
            const emailInput = document.getElementById('email');
            const messageInput = document.getElementById('message');
            const nameError = document.getElementById('name-error');
            const emailError = document.getElementById('email-error');
            const messageError = document.getElementById('message-error');
            const successMessage = document.getElementById('success-message');

            if (form) {
                form.addEventListener('submit', function(event) {
                    event.preventDefault();

                    let isValid = true;

                    if (!nameInput.value.trim()) {
                        nameError.textContent = 'Name is required.';
                        isValid = false;
                    } else {
                        nameError.textContent = '';
                    }

                    if (!emailInput.value.trim()) {
                        emailError.textContent = 'Email is required.';
                        isValid = false;
                    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value)) {
                        emailError.textContent = 'Invalid email format.';
                        isValid = false;
                    } else {
                        emailError.textContent = '';
                    }

                    if (!messageInput.value.trim()) {
                        messageError.textContent = 'Message is required.';
                        isValid = false;
                    } else {
                        messageError.textContent = '';
                    }

                    if (isValid) {
                        // Mock success
                        successMessage.style.display = 'block';
                        form.reset(); // Clear the form
                        setTimeout(() => { successMessage.style.display = 'none'; }, 3000); // Hide the success message after 3 seconds
                    }
                });
            }

        })();
    </script>
