  <script>
  (function(){
    'use strict';

    // Add JS marker (enables progressive enhancement features like reveal animations and off-canvas menu)
    document.body.classList.add('js');

    // Utility selectors
    const qs = (s, el=document) => el.querySelector(s);
    const qsa = (s, el=document) => Array.from(el.querySelectorAll(s));

    // Elements
    const navToggle = qs('#navToggle');
    const siteNav = qs('#siteNav');
    const navOverlay = qs('#navOverlay');
    const body = document.body;
    const ctaInvite = qs('#ctaInvite');
    const yearEl = qs('#year');
    const requestForm = qs('#requestForm');
    const formStatus = qs('#formStatus');

    // Set year
    if(yearEl) yearEl.textContent = new Date().getFullYear();

    // NAV TOGGLE: open/close mobile nav, lock scroll, trap focus
    let lastFocusedBeforeNav = null;
    let removeFocusTrap = null;

    const FOCUSABLE = 'a[href],area[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled]),[tabindex]:not([tabindex="-1"])';

    function trapFocus(container){
      const nodes = Array.from(container.querySelectorAll(FOCUSABLE));
      if(!nodes.length) return function(){};
      const first = nodes[0];
      const last = nodes[nodes.length-1];

      function handler(e){
        if(e.key !== 'Tab') return;
        if(e.shiftKey){
          if(document.activeElement === first){
            e.preventDefault();
            last.focus();
          }
        } else {
          if(document.activeElement === last){
            e.preventDefault();
            first.focus();
          }
        }
      }
      document.addEventListener('keydown', handler);
      return function cleanup(){ document.removeEventListener('keydown', handler); };
    }

    function openNav(){
      if(!siteNav) return;
      lastFocusedBeforeNav = document.activeElement;
      siteNav.classList.add('open');
      siteNav.setAttribute('aria-hidden','false');
      navToggle.setAttribute('aria-expanded','true');
      navOverlay.classList.add('open');
      body.style.overflow = 'hidden';
      // focus first focusable in nav
      const first = siteNav.querySelector(FOCUSABLE);
      if(first) first.focus();
      removeFocusTrap = trapFocus(siteNav);
      // change menu icon to close
      navToggle.setAttribute('aria-label','Close menu');
      // update button icon to close
      const use = navToggle.querySelector('use');
      if(use) use.setAttribute('href','#icon-close');
    }

    function closeNav(){
      if(!siteNav) return;
      siteNav.classList.remove('open');
      siteNav.setAttribute('aria-hidden','true');
      navToggle.setAttribute('aria-expanded','false');
      navOverlay.classList.remove('open');
      body.style.overflow = '';
      if(removeFocusTrap) removeFocusTrap();
      if(lastFocusedBeforeNav && typeof lastFocusedBeforeNav.focus === 'function') lastFocusedBeforeNav.focus();
      navToggle.setAttribute('aria-label','Open menu');
      const use = navToggle.querySelector('use');
      if(use) use.setAttribute('href','#icon-hamburger');
    }

    function toggleNav(){
      const expanded = navToggle.getAttribute('aria-expanded') === 'true';
      if(expanded) closeNav(); else openNav();
    }

    if(navToggle){
      navToggle.addEventListener('click', (e) => {
        e.preventDefault();
        toggleNav();
      });

      // Close when overlay clicked
      if(navOverlay){
        navOverlay.addEventListener('click', closeNav);
      }

      // Close on Escape
      document.addEventListener('keydown', (e) => {
        if(e.key === 'Escape'){
          const expanded = navToggle.getAttribute('aria-expanded') === 'true';
          if(expanded) closeNav();
        }
      });
    }

    // Smoothly focus form when CTA clicked
    if(ctaInvite){
      ctaInvite.addEventListener('click', (e) => {
        // Let the anchor do its default jump then focus form
        e.preventDefault();
        const join = qs('#join');
        if(join){
          join.scrollIntoView({behavior: 'smooth', block:'start'});
          // After a little delay to allow scroll, focus first input
          setTimeout(() => {
            const first = qs('#name');
            if(first){ first.focus(); }
          }, 400);
          // Close nav if open (mobile)
          const expanded = navToggle.getAttribute && (navToggle.getAttribute('aria-expanded') === 'true');
          if(expanded){ closeNav(); }
        }
      });
    }

    // IntersectionObserver: reveal-on-scroll (progressive enhancement)
    (function initReveal(){
      const reveals = qsa('.reveal');
      if(!('IntersectionObserver' in window)){
        reveals.forEach(el => el.classList.add('in-view'));
        return;
      }
      const io = new IntersectionObserver((entries, obs) => {
        entries.forEach(entry => {
          if(entry.isIntersecting){
            entry.target.classList.add('in-view');
            obs.unobserve(entry.target);
          }
        });
      }, {threshold: 0.12});
      reveals.forEach(el => io.observe(el));
    })();

    // Simple parallax using requestAnimationFrame; disabled when user prefers reduced motion
    (function initParallax(){
      if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      const nodes = qsa('.parallax');
      if(!nodes.length) return;
      let ticking = false;
      function update(){
        const sc = window.scrollY || window.pageYOffset || 0;
        nodes.forEach(el => {
          const s = parseFloat(el.dataset.speed) || 0.06;
          // translate with small values
          el.style.transform = `translateY(${Math.round(sc * s)}px)`;
        });
        ticking = false;
      }
      function onScroll(){
        if(!ticking){
          window.requestAnimationFrame(update);
          ticking = true;
        }
      }
      window.addEventListener('scroll', onScroll, {passive:true});
      // initial
      update();
    })();

    // Form validation (client-side only) with inline errors and a mock success toast
    (function handleForm(){
      if(!requestForm) return;

      const nameEl = qs('#name');
      const emailEl = qs('#email');
      const msgEl = qs('#message');

      function setError(el, message){
        const id = el.id ? `error-${el.id}` : null;
        if(id){
          const errNode = qs(`#${id}`);
          if(errNode){ errNode.textContent = message; }
        }
        el.setAttribute('aria-invalid', 'true');
      }

      function clearError(el){
        const id = el.id ? `error-${el.id}` : null;
        if(id){
          const errNode = qs(`#${id}`);
          if(errNode){ errNode.textContent = ''; }
        }
        el.removeAttribute('aria-invalid');
      }

      function validateEmail(value){
        // simple, permissive email regex
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
      }

      function showToast(message, success=true){
        const t = document.createElement('div');
        t.className = 'toast';
        t.setAttribute('role','status');
        t.setAttribute('aria-live','polite');
        t.textContent = message;
        document.body.appendChild(t);
        // allow styles to compute then show
        requestAnimationFrame(() => t.classList.add('show'));
        // remove after 4s
        setTimeout(() => {
          t.classList.remove('show');
          setTimeout(() => { if(t.parentNode) t.parentNode.removeChild(t); }, 200);
        }, 4000);
      }

      requestForm.addEventListener('submit', (e) => {
        e.preventDefault();
        formStatus.textContent = '';
        let valid = true;
        // Clear previous errors
        [nameEl, emailEl, msgEl].forEach(clearError);

        const name = nameEl.value.trim();
        const email = emailEl.value.trim();
        const msg = msgEl.value.trim();

        if(!name){
          setError(nameEl, 'Please enter your full name.');
          valid = false;
        }
        if(!email){
          setError(emailEl, 'Please enter your email address.');
          valid = false;
        } else if(!validateEmail(email)){
          setError(emailEl, 'Please enter a valid email address.');
          valid = false;
        }

        if(!valid){
          // Announce a polite message in the form status area
          formStatus.textContent = 'Please check the highlighted fields.';
          // focus first invalid field
          const firstInvalid = requestForm.querySelector('[aria-invalid="true"]');
          if(firstInvalid) firstInvalid.focus();
          return;
        }

        // Mock submission (no network)
        requestForm.querySelectorAll('input,textarea,button').forEach(n => n.setAttribute('disabled','disabled'));
        formStatus.textContent = 'Sending…';
        // Simulate network delay, then success
        setTimeout(() => {
          // Reset form
          requestForm.reset();
          requestForm.querySelectorAll('input,textarea,button').forEach(n => n.removeAttribute('disabled'));
          formStatus.textContent = '';
          showToast('Request received. We will be in touch should your request be accepted.');
          // return focus to the name field
          if(nameEl) nameEl.focus();
        }, 900);
      });

      // Clear error on input
      [nameEl, emailEl, msgEl].forEach(el => {
        el.addEventListener('input', () => clearError(el));
      });
    })();

    // Ensure anchor links close nav on activation (mobile)
    (function anchorCloseNav(){
      const anchors = qsa('a[href^="#"]');
      anchors.forEach(a => {
        a.addEventListener('click', (e) => {
          // If anchor targets an element on the page, close nav
          const href = a.getAttribute('href');
          if(!href || href === '#') return;
          if(href.startsWith('#')){
            const target = document.getElementById(href.slice(1));
            if(target){
              // allow default behaviour (scroll), but close nav for mobile
              const expanded = navToggle && navToggle.getAttribute && (navToggle.getAttribute('aria-expanded') === 'true');
              if(expanded){ closeNav(); }
            }
          }
        });
      });
    })();

  })();
  </script>
