In the following C++ code a function is given that implements the elementary cellular automata rule for a given rule. Can you check for me if it is implemented correctly? ```cpp
static inline void eca_step(
    uint8_t rule,
    const Vec &src, 
    Vec &dst
) {
    const size_t n = src.size();

    // replicate rule byte   0bABCDEFGH  ->  0xHGFEDCBA'HGF...
    const U64 ruleLUT = U64{rule} * 0x0101010101010101ULL;

    // helpers for boundaries (periodic)
    const U64 first_lsb = src[0] & 1ULL;
    const U64 last_msb  = src.back() >> 63;

    for (size_t i = 0; i < n; ++i)
    {
        const U64 c = src[i];

        // neighbour bits with wrap-around in one go
        const U64 left  = (c << 1) |
                          (i ? (src[i-1] >> 63) : last_msb);

        const U64 right = (c >> 1) |
                          (i + 1 < n ? (src[i+1] << 63) : first_lsb << 63);

        const U64 idx = (left << 2) | (c << 1) | right;

        // look-up 64 neighbourhoods simultaneously
        U64 bits = (ruleLUT >> idx) & 0x0101010101010101ULL;

        // pack: pick bit0 of every byte => consecutive bits 0…63
        dst[i] = _pext_u64(bits, 0x0101010101010101ULL);
    }
}
